l=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"end\" font-family=\"monospace\" font-weight=\"600\">1</text>\n  <circle cx=\"38\" cy=\"28\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"38\" y=\"32.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"38\" cy=\"60\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"38\" y=\"64.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"280\" cy=\"84\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"280\" y=\"88.5\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"280\" cy=\"162\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"280\" y=\"166.5\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"280\" cy=\"138\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"280\" y=\"142.5\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n", "code": "<div class=\"origam-bracket-match origam-bracket-match--interactive\" role=\"group\">\n  <!-- meta header: visible when status or scheduledAt is set -->\n  <div class=\"origam-bracket-match__meta\">\n    <span class=\"origam-bracket-match__status origam-bracket-match__status--live\">LIVE</span>\n    <a class=\"origam-bracket-match__watch\" href=\"...\" target=\"_blank\" rel=\"noopener noreferrer\">Watch live</a>\n    <span class=\"origam-bracket-match__schedule\">14:00 UTC</span>\n  </div>\n\n  <!-- body: the two competitor rows -->\n  <div class=\"origam-bracket-match__body\">\n    <!-- #competitor slot (side A) -->\n    <origam-bracket-competitor class=\"origam-bracket-match__row\" :is-winner=\"true\" />\n\n    <origam-divider class=\"origam-bracket-match__divider\" />\n\n    <!-- #competitor slot (side B) -->\n    <origam-bracket-competitor class=\"origam-bracket-match__row\" :is-loser=\"true\" />\n  </div>\n</div>", "legend": [{"cls": ".origam-bracket-match", "num": 1, "descriptionKey": "components.bracket_match.anatomy.root", "descriptionFallback": "Root card element. Flex column with border, rounded corners and optional box-shadow. role=\"group\"."}, {"cls": ".origam-bracket-match__meta", "num": 2, "descriptionKey": "components.bracket_match.anatomy.meta", "descriptionFallback": "Meta header bar. Visible only when match.scheduledAt or a resolved status is present. Contains status badge, watch link and schedule time."}, {"cls": ".origam-bracket-match__row (side A)", "num": 3, "descriptionKey": "components.bracket_match.anatomy.row_a", "descriptionFallback": "Competitor A row — an OrigamBracketCompetitor with isWinner/isLoser derived from match.winnerId."}, {"cls": ".origam-bracket-match__row (side B)", "num": 4, "descriptionKey": "components.bracket_match.anatomy.row_b", "descriptionFallback": "Competitor B row — same as A but for the second participant."}, {"cls": ".origam-bracket-match__divider", "num": 5, "descriptionKey": "components.bracket_match.anatomy.divider", "descriptionFallback": "OrigamDivider separator between the two competitor rows."}], "classes": [{"cls": "origam-bracket-match", "descriptionKey": "components.bracket_match.anatomy.root", "descriptionFallback": "Root card element with border and shadow."}, {"cls": "origam-bracket-match__meta", "descriptionKey": "components.bracket_match.anatomy.meta", "descriptionFallback": "Meta header bar with status, watch link and schedule."}, {"cls": "origam-bracket-match__status", "descriptionKey": "components.bracket_match.anatomy.status", "descriptionFallback": "Status badge with colored dot prefix (LIVE / Completed / TBD / Forfeit)."}, {"cls": "origam-bracket-match__body", "descriptionKey": "components.bracket_match.anatomy.body", "descriptionFallback": "Container for the two