onent", "descriptionKey": "components.component_icon.anatomy.component", "descriptionFallback": "Strategy modifier. Signals the component-icon rendering path."}, {"cls": "origam-icon--size-{size}", "descriptionKey": "components.component_icon.anatomy.size", "descriptionFallback": "Size modifier when a named TSize token is passed."}], "svgDesc": "Schematic of ComponentIcon with 2 internal parts.", "svgTitle": "Anatomy of OrigamComponentIcon", "rootClass": "origam-icon", "figcaption": "Anatomy of <code>&lt;origam-component-icon&gt;</code> — 2 parts. The wrapper <code>div</code> hosts a dynamic <code>&lt;component :is=\"icon\"&gt;</code>.", "svgViewBox": "0 0 400 120"}, "cssVars": [{"name": "--origam-icon---font-size", "defaultValue": "24px", "descriptionKey": "components.component_icon.css_vars.font_size", "descriptionFallback": "Controls width and height of the component icon wrapper."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.component_icon.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.component_icon.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.component_icon.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.component_icon.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.component_icon.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.component_icon.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.component_icon.playground.color", "defaultValue": "", "labelFallback": "Color / Intent"}, {"kind": "select", "prop": "size", "options": [{"label": "(default)", "value": ""}, {"label": "x-small", "value": "x-small"}, {"label": "small", "value": "small"}, {"label": "default", "value": "default"}, {"label": "large", "value": "large"}, {"label": "x-large", "value": "x-large"}], "labelKey": "components.component_icon.playground.size", "defaultValue": "", "labelFallback": "Size"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.component_icon.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}], "defaultSlotContent": "Content"}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('be6ebc72-2a17-4811-84c3-2c929db2f785', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'component', 'confirm-wrapper', 'ConfirmWrapper', 'Form & Input', NULL, 'mdi-form-textbox', 'components.catalog.confirm_wrapper.description', '"Type-it-twice" form helper that pairs a primary input with a confirmation input and validates that both values match.', NULL, NULL, 'origam-confirm-wrapper', NULL, 'packages/ds/src/components/ConfirmWrapper/OrigamConfirmWrapper.vue', 'origam', NULL, NULL, '/stories/?story=components-confirmwrapper--design', '/docs/components/ConfirmWrapper/OrigamConfirmWrapper.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.confirm_wrapper.a11y.error_note", "noteFallback": "When validation fails (values do not match), the error message is associated with the confirmation field via aria-describedby. The confirmation input receives aria-invalid=\"true\"."}, {"noteKey": "components.confirm_wrapper.a11y.required_note", "noteFallback": "When required=true, aria-required=\"true\" is forwarded to both inner inputs."}], "roles": [], "keyboard": [{"key": "Tab", "actionKey": "components.confirm_wrapper.a11y.key_tab", "actionFallback": "Moves focus from the primary input to the confirmation input, then to the next focusable element."}]}, "tokens": {"excerpt": [{"type": "dimension", "value": "var(--origam-space---4)", "tokenPath": "--origam-confirm-wrapper---padding-bottom", "descriptionKey": "components.confirm_wrapper.tokens.padding_bottom", "descriptionFallback": "Block-end padding of the wrapper."}, {"type": "dimension", "value": "22px", "tokenPa