m-wrapper---details-min-height</code>."}], "classes": [{"cls": "origam-confirm-wrapper", "descriptionKey": "components.confirm_wrapper.anatomy.root", "descriptionFallback": "Root container. Manages shared form validation."}, {"cls": "origam-confirm-wrapper__header", "descriptionKey": "components.confirm_wrapper.anatomy.header", "descriptionFallback": "Header row with prepend / label / append regions."}, {"cls": "origam-confirm-wrapper__prepend", "descriptionKey": "components.confirm_wrapper.anatomy.prepend", "descriptionFallback": "Leading icon/avatar area in the header."}, {"cls": "origam-confirm-wrapper__label", "descriptionKey": "components.confirm_wrapper.anatomy.label", "descriptionFallback": "Title area in the header."}, {"cls": "origam-confirm-wrapper__append", "descriptionKey": "components.confirm_wrapper.anatomy.append", "descriptionFallback": "Trailing icon/avatar area in the header."}, {"cls": "origam-confirm-wrapper__content", "descriptionKey": "components.confirm_wrapper.anatomy.content", "descriptionFallback": "Flex container holding both input slots (direction-aware: vertical / horizontal)."}, {"cls": "origam-confirm-wrapper__field", "descriptionKey": "components.confirm_wrapper.anatomy.field", "descriptionFallback": "Primary input slot wrapper."}, {"cls": "origam-confirm-wrapper__confirm", "descriptionKey": "components.confirm_wrapper.anatomy.confirm", "descriptionFallback": "Confirmation input slot wrapper."}, {"cls": "origam-confirm-wrapper__details", "descriptionKey": "components.confirm_wrapper.anatomy.details", "descriptionFallback": "Messages and hint area below the inputs."}], "svgDesc": "Schematic of the ConfirmWrapper component with numbered internal parts.", "svgTitle": "Anatomy of OrigamConfirmWrapper", "rootClass": "origam-confirm-wrapper", "figcaption": "Anatomy of <code>&lt;origam-confirm-wrapper&gt;</code> — 5 regions. The wrapper coordinates validation between the #default and #confirm slots, surfacing match errors in the details zone.", "svgViewBox": "0 0 700 280"}, "cssVars": [{"name": "--origam-confirm-wrapper---padding-start", "defaultValue": "{space.2}", "descriptionKey": "components.confirm_wrapper.css_vars.padding_start", "descriptionFallback": "Inline-start (left in LTR) padding of the wrapper."}, {"name": "--origam-confirm-wrapper---padding-end", "defaultValue": "{space.2}", "descriptionKey": "components.confirm_wrapper.css_vars.padding_end", "descriptionFallback": "Inline-end (right in LTR) padding of the wrapper."}, {"name": "--origam-confirm-wrapper---padding-top", "defaultValue": "{space.2}", "descriptionKey": "components.confirm_wrapper.css_vars.padding_top", "descriptionFallback": "Block-start padding of the wrapper."}, {"name": "--origam-confirm-wrapper---padding-bottom", "defaultValue": "{space.4}", "descriptionKey": "components.confirm_wrapper.css_vars.padding_bottom", "descriptionFallback": "Block-end padding of the wrapper."}, {"name": "--origam-confirm-wrapper---details-min-height", "defaultValue": "22px", "descriptionKey": "components.confirm_wrapper.css_vars.details_min_height", "descriptionFallback": "Minimum height of the details row to prevent layout shift when messages appear."}, {"name": "--origam-confirm-wrapper---horizontal-gap", "defaultValue": "1em", "descriptionKey": "components.confirm_wrapper.css_vars.horizontal_gap", "descriptionFallback": "Gap between primary and confirmation fields in horizontal direction mode."}, {"name": "--origam-confirm-wrapper--error---color", "defaultValue": "{color.feedback.danger.fgSubtle}", "descriptionKey": "components.confirm_wrapper.css_vars.error_color", "descriptionFallback": "Error text color rendered in the details row when values do not match."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.confirm_wrapper.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to child components."}, {"name": 