ied to each column cell td."}, {"cls": "origam-data-table-row__column--select-row", "descriptionKey": "components.data_table_row.anatomy.select_row", "descriptionFallback": "Modifier for the selection checkbox column."}, {"cls": "origam-data-table-row__column--expanded-row", "descriptionKey": "components.data_table_row.anatomy.expanded_row", "descriptionFallback": "Modifier for the expand toggle column."}, {"cls": "origam-data-table-row__column-title", "descriptionKey": "components.data_table_row.anatomy.column_title", "descriptionFallback": "Column label shown in mobile layout (left cell). Font-weight: medium."}, {"cls": "origam-data-table-row__column-value", "descriptionKey": "components.data_table_row.anatomy.column_value", "descriptionFallback": "Column value shown in mobile layout (right cell, text-align: right)."}], "svgDesc": "Schematic of DataTableRow with 4 internal parts.", "svgTitle": "Anatomy of OrigamDataTableRow", "rootClass": "origam-data-table-row", "figcaption": "Anatomy of <code>&lt;origam-data-table-row&gt;</code> — 4 parts: tr root ①, select column (CheckboxBtn) ②, data column cell ③, expand column (Btn) ④.", "svgViewBox": "0 0 560 120"}, "cssVars": [{"name": "--origam-data-table-row---background-color", "defaultValue": "var(--origam-color__surface---default)", "descriptionKey": "components.data_table_row.css_vars.background_color", "descriptionFallback": "Default row background colour."}, {"name": "--origam-data-table-row---color", "defaultValue": "var(--origam-color__text---primary)", "descriptionKey": "components.data_table_row.css_vars.color", "descriptionFallback": "Default row text colour."}, {"name": "--origam-data-table-row--hover---background-color", "defaultValue": "var(--origam-color__surface---overlay)", "descriptionKey": "components.data_table_row.css_vars.hover_background_color", "descriptionFallback": "Row background colour on hover."}, {"name": "--origam-data-table-row---transition-duration", "defaultValue": "100ms", "descriptionKey": "components.data_table_row.css_vars.transition_duration", "descriptionFallback": "Duration of the background-colour transition on hover/select."}, {"name": "--origam-data-table-row---transition-easing", "defaultValue": "cubic-bezier(0.4, 0, 0.2, 1)", "descriptionKey": "components.data_table_row.css_vars.transition_easing", "descriptionFallback": "Easing function for the row background transition."}, {"name": "--origam-data-table-row__column-title---font-weight", "defaultValue": "500", "descriptionKey": "components.data_table_row.css_vars.column_title_font_weight", "descriptionFallback": "Font weight of the column title label in mobile stacked layout."}, {"name": "--origam-data-table-row--mobile__column-min-height", "defaultValue": "52px", "descriptionKey": "components.data_table_row.css_vars.mobile_column_min_height", "descriptionFallback": "Minimum height of each stacked cell in mobile layout."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.data_table_row.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.data_table_row.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.data_table_row.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.data_table_row.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.data_table_row.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.data_table_row.exposed.is_loaded", "descriptionFallback": "True on