INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('ba85f6c4-d135-495a-8a73-aa7c0b45ee65', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'component', 'expansion-panel-content', 'ExpansionPanelContent', 'Layout & Structure', NULL, 'mdi-card-text-outline', 'components.catalog.expansion_panel_content.description', 'Animated content region revealed when the parent ExpansionPanel is expanded. Has role="region" and aria-labelledby pointing to the header.', NULL, NULL, 'origam-expansion-panel-content', NULL, 'packages/ds/src/components/ExpansionPanel/OrigamExpansionPanelContent.vue', 'origam', NULL, NULL, '/stories/?story=components-expansionpanel--design', '/docs/components/ExpansionPanel/OrigamExpansionPanel.html', 'expansion-panel', '{"a11y": {"notes": [{"noteKey": "components.expansion_panel_content.a11y.aria_labelledby", "noteFallback": "The content root carries aria-labelledby pointing to the sibling header ID, associating the region with its label for screen readers."}, {"noteKey": "components.expansion_panel_content.a11y.visibility", "noteFallback": "Uses v-show to hide the content — it remains in the DOM (unless eager=false and not yet revealed) so focus management works correctly after expand."}, {"noteKey": "components.expansion_panel_content.a11y.lazy", "noteFallback": "Content is lazily rendered on first expand (unless eager is true). After first expand, the DOM is preserved on collapse via v-show."}], "roles": ["region"], "keyboard": [{"key": "Tab", "actionKey": "components.expansion_panel_content.a11y.key_tab", "actionFallback": "Moves focus into and out of the content region when it is expanded."}]