rop-item", "descriptionKey": "components.file_field_drag_n_drop_item.anatomy.root", "descriptionFallback": "Root flex container."}, {"cls": "origam-file-field-dragndrop-item__icon", "descriptionKey": "components.file_field_drag_n_drop_item.anatomy.icon", "descriptionFallback": "File type icon (flex-shrink: 0)."}, {"cls": "origam-file-field-dragndrop-item__content", "descriptionKey": "components.file_field_drag_n_drop_item.anatomy.content", "descriptionFallback": "Column container for name, meta and progress."}, {"cls": "origam-file-field-dragndrop-item__name", "descriptionKey": "components.file_field_drag_n_drop_item.anatomy.name", "descriptionFallback": "File name text. Truncated with text-overflow: ellipsis."}, {"cls": "origam-file-field-dragndrop-item__meta", "descriptionKey": "components.file_field_drag_n_drop_item.anatomy.meta", "descriptionFallback": "Human-readable file size display."}, {"cls": "origam-file-field-dragndrop-item__progress", "descriptionKey": "components.file_field_drag_n_drop_item.anatomy.progress", "descriptionFallback": "Progress bar (conditional on progress prop)."}, {"cls": "origam-file-field-dragndrop-item__actions", "descriptionKey": "components.file_field_drag_n_drop_item.anatomy.actions", "descriptionFallback": "Action buttons zone (remove)."}], "svgDesc": "Schematic of the drag-and-drop file item with 5 numbered parts: root, icon, content, progress bar, actions.", "svgTitle": "Anatomy of OrigamFileFieldDragNDropItem", "rootClass": "origam-file-field-dragndrop-item", "figcaption": "Anatomy of <code>&lt;origam-file-field-dragndrop-item&gt;</code> — 5 internal parts. The root ① is a horizontal flex row; the icon ② is a static file glyph; the content ③ stacks the name, meta text and optional progress bar ④; the actions zone ⑤ holds the remove button.", "svgViewBox": "0 0 700 160"}, "cssVars": [{"name": "--origam-file-field-dragndrop-item---gap", "defaultValue": "{space.3} (12px)", "descriptionKey": "components.file_field_drag_n_drop_item.