x)", "descriptionKey": "components.file_field_drag_n_drop_item.css_vars.progress_margin_top", "descriptionFallback": "Top margin of the progress bar inside the content column."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.file_field_drag_n_drop_item.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to child components."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.file_field_drag_n_drop_item.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from the computed root styles."}, {"name": "id", "type": "string", "descriptionKey": "components.file_field_drag_n_drop_item.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.file_field_drag_n_drop_item.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.file_field_drag_n_drop_item.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.file_field_drag_n_drop_item.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.file_field_drag_n_drop_item.playground.color", "defaultValue": "", "labelFallback": "Color / Intent"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.file_field_drag_n_drop_item.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "switch", "prop": "readonly", "labelKey": "components.file_field_drag_n_drop_item.playground.readonly", "defaultValue": false, "labelFallback": "Read-only"}], "defaultSlotContent": "Content"}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('34259141-8b46-4baf-b775-f0abb73e036f', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'component', 'file-field-list-item', 'FileFieldListItem', 'Form & Input', NULL, 'mdi-file-document-outline', 'components.catalog.file_field_list_item.description', 'File card rendered in list mode for each selected file. Displays name, human-readable size, an optional progress bar and a remove button. Renders as a semantic <li> element.', NULL, NULL, 'origam-file-field-list-item', NULL, 'packages/ds/src/components/FileField/OrigamFileFieldListItem.vue', 'origam', NULL, NULL, '/stories/?story=components-filefield--design', '/docs/components/FileField/OrigamFileField.html', 'file-field', '{"a11y": {"notes": [{"noteKey": "components.file_field_list_item.a11y.semantic_li", "noteFallback": "The root element is a semantic <li>. It must be used inside a <ul> (provided by OrigamFileField in list display mode) to satisfy the HTML content model."}, {"noteKey": "components.file_field_list_item.a11y.remove_btn", "noteFallback": "The remove button is a native <button> (via OrigamBtn). It is disabled when disabled=true or readonly=true."}], "roles": ["listitem"], "keyboard": [{"key": "Enter / Space", "actionKey": "components.file_field_list_item.a11y.key_remove", "actionFallback": "Activates the remove button when focused — native <button> behaviour."}, {"key": "Tab", "actionKey": "components.file_field_list_item.a11y.key_tab", "actionFallback": "Moves focus to the remove button and then to the next interactive element."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__surface---overlay)", "tokenPath": "--origam-file-field-list-item---background-color", "descriptionKey": "components.file_field_list_item.tokens.background_color", "descriptionFallback": "Card background color."}, {"type": "color", "value": "var(--origam-color__border---subtle)", "tokenPath": "--origam-file-field-list-item---border-color", "descriptionKey": "components.file_field_list_item.tokens.border_color", "descriptionFallback": "Card border color."}, {"type": "dimension", "value": "var(--origam-radius---sm)", "tokenPath": "--origam-file-field-list-item---border-radius", "descriptionKey": "components.file_field_list_item.tokens.border_radius", "descriptionFallback": "Card corner radius."}, {"type": "dimension", "value": "var(--origam-space---3)", "tokenPath": "--origam-file-field-list-item---gap", "descriptionKey": "components.file_field_list_item.tokens.gap", "descriptionFallback": "Gap between icon, content and actions (12px)."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"160\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"30\" width=\"660\" height=\"100\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <circle cx=\"28\" cy=\"38\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"42\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <rect x=\"40\" y=\"44\" width=\"60\" height=\"72\" rx=\"4\" fill=\"var(--origam-color__surface---sunken, #f3eeff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\"/>\n  <text x=\"70\" y=\"83\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">icon</text>\n  <circle cx=\"48\" cy=\"52\" r=\"8\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"48\" y=\"56\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <rect x=\"116\" y=\"44\" width=\"450\" height=\"72\" rx=\"4\" fill=\"var(--origam-color__surface---sunken, #f9f5ff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\"/>\n  <text x=\"210\" y=\"64\" font-size=\"10\" fill=\"var(--origam-color__text---primary, #3b1c6e)\" font-weight=\"600\" font-family=\"''JetBrains Mono'',monospace\">document.docx</text>\n  <text x=\"210\" y=\"80\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #7e5fb0)\" font-family=\"''JetBrains Mono'',monospace\">320 kB</text>\n  <rect x=\"136\" y=\"90\" width=\"410\" height=\"6\" rx=\"3\" fill=\"var(--origam-color__surface---overlay, rgba(124,58,237,0.12))\"/>\n  <rect x=\"136\" y=\"90\" width=\"267\" height=\"6\" rx=\"3\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <circle cx=\"124\" cy=\"52\" r=\"8\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"124\" y=\"56\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"340\" cy=\"95\" r=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"340\" y=\"99\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <rect x=\"580\" y=\"44\" width=\"72\" height=\"72\" rx=\"4\" fill=\"var(--origam-color__surface---sunken, #f3eeff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\"/>\n  <text x=\"616\" y=\"83\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">remove</text>\n  <circle cx=\"588\" cy=\"52\" r=\"8\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"588\" y=\"56\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n", "code": "<li class=\"origam-file-field-list-item\">\n  <slot>\n    <origam-icon class=\"origam-file-field-list-item__icon\" />\n    <div class=\"origam-file-field-list-item__content\">\n      <div class=\"origam-file-field-list-item__name\">document.docx</div>\n      <div class=\"origam-file-field-list-item__meta\">320 kB</div>\n      <origam-progress class=\"origam-file-field-list-item__progress\" />\n    </div>\n    <div class=\"origam-file-field-list-item__actions\">\n      <origam-btn :icon=\"removeIcon\" flat size=\"small\" @click.stop=\"handleRemove\" />\n    </div>\n  </slot>\n</li>", "legend": [{"cls": ".origam-file-field-list-item", "num": 1, "descriptionKey": "components.file_field_list_item.anatomy.root", "descriptionFallback": "Root <li> element. display: flex; align-items: center. Has background-color, border (1px solid), border-radius and padding from design tokens."}, {"cls": ".origam-file-field-list-item__icon", "num": 2, "descriptionKey": "components.file_field_list_item.anatomy.icon", "descriptionFallback": "OrigamIcon rendered from the fileIcon prop. flex-shrink: 0; color from --origam-file-field-list-item__icon---color."}, {"cls": ".origam-file-field-list-item__content", "num": 3, "descriptionKey": "components.file_field_list_item.anatomy.content", "descriptionFallback": "Flex column: stacks __name, __meta and optional __progress. flex-grow: 1; min-width: 0 for truncation support."}, {"cls": ".origam-file-field-list-item__progress", "num": 4, "descriptionKey": "components.file_field_list_item.anatomy.progress", "descriptionFallback": "OrigamProgress bar. Rendered only when the progress prop is a number. height: 4px; rounded; has margin-top from token."}, {"cls": ".origam-file-field-list-item__actions", "num": 5, "descriptionKey": "components.file_field_list_item.anatomy.actions", "descriptionFallback": "Flex row of action buttons. flex-shrink: 0. Contains the remove OrigamBtn (flat, size=\"small\")."}], "classes": [{"cls": "origam-file-field-list-item", "descriptionKey": "components.file_field_list_item.anatomy.root", "descriptionFallback": "Root <li> flex container with background, border, border-radius and padding tokens."}, {"cls": "origam-file-field-list-item__icon", "descriptionKey": "components.file_field_list_item.anatomy.icon", "descriptionFallback": "File type icon (flex-shrink: 0)."}, {"cls": "origam-file-field-list-item__content", "descriptionKey": "components.file_field_list_item.anatomy.content", "descriptionFallback": "Column container for name, meta and progress."}, {"cls": "origam-file-field-list-item__name", "descriptionKey": "components.file_field_list_item.anatomy.name", "descriptionFallback": "File name text. Truncated with text-overflow: ellipsis."}, {"cls": "origam-file-field-list-item__meta", "descriptionKey": "components.file_field_list_item.anatomy.meta", "descriptionFallback": "Human-readable file size text."}, {"cls": "origam-file-field-list-item__progress", "descriptionKey": "components.file_field_list_item.anatomy.progress", "descriptionFallback": "Upload progress bar (conditional on progress prop)."}, {"cls": "origam-file-field-list-item__actions", "descriptionKey": "components.file_field_list_item.anatomy.actions", "descriptionFallback": "Action buttons zone (remove button)."}], "svgDesc": "Schematic of the list file item with 5 numbered parts: root <li>, icon, content column, progress bar, actions.", "svgTitle": "Anatomy of OrigamFileFieldListItem", "rootClass": "origam-file-field-list-item", "figcaption": "Anatomy of <code>&lt;origam-file-field-list-item&gt;</code> — renders as a semantic <code>&lt;li&gt;</code>. 5 internal parts: root card ①, file icon ②, content column ③ (name + meta + optional progress ④), and the actions zone ⑤ with the remove button.", "svgViewBox": "0 0 700 160"}, "cssVars": [{"name": "--origam-file-field-list-item---background-color", "defaultValue": "{color.surface.overlay}", "descriptionKey": "components.file_field_list_item.css_vars.background_color", "descriptionFallback": "Card background color."}, {"name": "--origam-file-field-list-item---border-color", "defaultValue": "{color.border.subtle}", "descriptionKey": "components.file_field_list_item.css_vars.border_color", "descriptionFallback": "Card border color."}, {"name": "--origam-file-field-list-item---border-width", "defaultValue": "1px", "descriptionKey": "components.file_field_list_item.css_vars.border_width", "descriptionFallback": "Card border width."}, {"name": "--origam-file-field-list-item---border-style", "defaultValue": "solid", "descriptionKey": "components.file_field_list_item.css_vars.border_style", "descriptionFallback": "Card border style."}, {"name": "--origam-file-field-list-item---border-radius", "defaultValue": "{radius.sm} (6px)", "descriptionKey": "components.file_field_list_item.css_vars.border_radius", "descriptionFallback": "Card corner radius (6px as fallback in the .vue; closest token is radius.sm = 4px)."}, {"name": "--origam-file-field-list-item---gap", "defaultValue": "{space.3} (12px)", "descriptionKey": "components.file_field_list_item.css_vars.gap", "descriptionFallback": "Gap between the icon, content column and actions zone."}, {"name": "--origam-file-field-list-item---padding-block", "defaultValue": "{space.2} (10px)", "descriptionKey": "components.file_field_list_item.css_vars.padding_block", "descriptionFallback": "Block (top/bottom) padding of the card."}, {"name": "--origam-file-field-list-item---padding-inline", "defaultValue": "{space.3} (12px)", "descriptionKey": "components.file_field_list_item.css_vars.padding_inline", "descriptionFallback": "Inline (left/right) padding of the card."}, {"name": "--origam-file-field-list-item__icon---color", "defaultValue": "{color.text.secondary}", "descriptionKey": "components.file_field_list_item.css_vars.icon_color", "descriptionFallback": "Color of the file type icon glyph."}, {"name": "--origam-file-field-list-item__name---font-size", "defaultValue": "{font.size.md} (0.875rem)", "descriptionKey": "components.file_field_list_item.css_vars.name_font_size", "descriptionFallback": "Font size for the file name label."}, {"name": "--origam-file-field-list-item__name---font-weight", "defaultValue": "{font.weight.medium} (500)", "descriptionKey": "components.file_field_list_item.css_vars.name_font_weight", "descriptionFallback": "Font weight for the file name label."}, {"name": "--origam-file-field-list-item__meta---color", "defaultValue": "{color.text.secondary}", "descriptionKey": "components.file_field_list_item.css_vars.meta_color", "descriptionFallback": "Color of the file size / meta text."}, {"name": "--origam-file-field-list-item__meta---font-size", "defaultValue": "{font.size.sm} (0.75rem)", "descriptionKey": "components.file_field_list_item.css_vars.meta_font_size", "descriptionFallback": "Font size for the file size / meta text."}, {"name": "--origam-file-field-list-item__progress---margin-top", "defaultValue": "{space.1} (4px)", "descriptionKey": "components.file_field_list_item.css_vars.progress_margin_top", "descriptionFallback": "Top margin of the progress bar inside the content column."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.file_field_list_item.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to child components."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.file_field_list_item.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from the computed root styles."}, {"name": "id", "type": "string", "descriptionKey": "components.file_field_list_item.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.file_field_list_item.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.file_field_list_item.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.file_field_list_item.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.file_field_list_item.playground.color", "defaultValue": "", "labelFallback": "Color / Intent"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.file_field_list_item.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "switch", "prop": "readonly", "labelKey": "components.file_field_list_item.playground.readonly", "defaultValue": false, "labelFallback": "Read-only"}], "defaultSlotContent": "Content"}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('c543edd7-039a-41ea-9e3c-27c0ace53f3c', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'component', 'form', 'Form', 'Form & Input', NULL, 'mdi-form-select', 'components.catalog.form.description', 'Form container with centralised validation, global error messaging, accessible submit/reset lifecycle, and an optional scroll-to-first-error behaviour. Wraps any number of Origam input fields and coordinates their validation state.', NULL, NULL, 'origam-form', NULL, 'packages/ds/src/components/Form/OrigamForm.vue', 'origam', NULL, NULL, '/stories/?story=components-form--design', '/docs/components/Form/OrigamForm.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.form.a11y.novalidate", "noteFallback": "The form element uses novalidate to suppress browser-native validation bubbles. All validation is handled by Origam components and displayed in field detail zones."}, {"noteKey": "components.form.a11y.live_region", "noteFallback": "Form-level messages appear in the __details section via OrigamMessages which carries aria-live=\"polite\" internally. Screen readers announce errors after submit."}, {"noteKey": "components.form.a11y.scroll_to_error", "noteFallback": "scrollToError (prop) and scrollToFirstError (exposed method) move focus to the first errored field after validation. This is an important accessibility improvement for long forms — screen readers naturally encounter the error context without manual navigation."}, {"noteKey": "components.form.a11y.disabled", "noteFallback": "Setting disabled=true injects IFormProvide.isDisabled = true into all descendant fields via provide/inject. No need to set disabled individually on each field."}], "roles": [], "keyboard": [{"key": "Enter (on submit button)", "actionKey": "components.form.a11y.key_submit", "actionFallback": "Submits the form when focus is on a [type=submit] button inside the form."}, {"key": "Escape", "actionKey": "components.form.a11y.key_escape", "actionFallback": "No built-in behaviour — consumers may bind Escape to call reset() or navigate away."}]}, "tokens": {"excerpt": [{"type": "dimension", "value": "var(--origam-space---4)", "tokenPath": "--origam-form__actions---margin-top", "descriptionKey": "components.form.tokens.actions_margin_top", "descriptionFallback": "Top margin of the actions zone (16px)."}, {"type": "dimension", "value": "var(--origam-space---2)", "tokenPath": "--origam-form__actions---gap", "descriptionKey": "components.form.tokens.actions_gap", "descriptionFallback": "Gap between action buttons (8px)."}, {"type": "dimension", "value": "var(--origam-font__size---sm)", "tokenPath": "--origam-form__details---font-size", "descriptionKey": "components.form.tokens.details_font_size", "descriptionFallback": "Message text font size (0.75rem)."}, {"type": "dimension", "value": "22px", "tokenPath": "--origam-form__details---min-height", "descriptionKey": "components.form.tokens.details_min_height", "descriptionFallback": "Minimum height of the message zone."}, {"type": "color", "value": "var(--origam-color__feedback--danger---fgSubtle)", "tokenPath": "--origam-form--error---messages-color", "descriptionKey": "components.form.tokens.error_messages_color", "descriptionFallback": "Error message colour."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"28\" y=\"16\" width=\"644\" height=\"168\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"48\" y=\"32\" width=\"604\" height=\"80\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.25))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"350\" y=\"76\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">__content (#default slot — form fields)</text>\n  <rect x=\"48\" y=\"124\" width=\"604\" height=\"24\" rx=\"3\" fill=\"var(--origam-color__feedback--danger---bgSubtle, rgba(220,38,38,0.05))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"350\" y=\"140\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">__details (OrigamMessages — error / hint)</text>\n  <rect x=\"48\" y=\"156\" width=\"200\" height=\"20\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"148\" y=\"169\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\">__actions (#actions slot)</text>\n  <circle cx=\"36\" cy=\"24\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"28.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"56\" cy=\"40\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"56\" y=\"44\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"56\" cy=\"132\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"56\" y=\"136\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n", "code": "<form class=\"origam-form\" novalidate @submit=\"handleSubmit\" @reset=\"handleReset\">\n\n  <!-- input fields register automatically via inject(IFormProvide) -->\n  <div class=\"origam-form__content\">\n    <slot name=\"default\" v-bind=\"form\" />\n  </div>\n\n  <!-- form-level error / hint messages — v-if hasMessages -->\n  <div class=\"origam-form__details\">\n    <slot name=\"messages\" v-bind=\"{ hasMessages, messages }\">\n      <origam-messages :messages=\"messages\" />\n    </slot>\n  </div>\n\n  <!-- action buttons — v-if slots.actions -->\n  <div class=\"origam-form__actions\">\n    <slot name=\"actions\" v-bind=\"{ submit, reset }\" />\n  </div>\n</form>", "legend": [{"cls": ".origam-form", "num": 1, "descriptionKey": "components.form.anatomy.root", "descriptionFallback": "Root <form> element with novalidate (prevents browser default validation). Handles @submit and @reset natively."}, {"cls": ".origam-form__content", "num": 2, "descriptionKey": "components.form.anatomy.content", "descriptionFallback": "Wrapper div hosting the #default slot. Contains all field components that register with the form."}, {"cls": ".origam-form__details", "num": 3, "descriptionKey": "components.form.anatomy.details", "descriptionFallback": "Form-level messages zone. Renders OrigamMessages when there are form-level errors or hints. Hidden when no messages are active."}, {"cls": ".origam-form__actions", "num": 4, "descriptionKey": "components.form.anatomy.actions", "descriptionFallback": "Actions row. Rendered only when the #actions slot is provided. Flex container with gap and top margin."}], "classes": [{"cls": "origam-form", "descriptionKey": "components.form.anatomy.root", "descriptionFallback": "Root <form> element."}, {"cls": "origam-form--error", "descriptionKey": "components.form.anatomy.error", "descriptionFallback": "Applied when form-level validation fails. Changes message/icon colour to danger semantic."}, {"cls": "origam-form__content", "descriptionKey": "components.form.anatomy.content", "descriptionFallback": "Form fields wrapper."}, {"cls": "origam-form__details", "descriptionKey": "components.form.anatomy.details", "descriptionFallback": "Form-level message zone (error / hint)."}, {"cls": "origam-form__actions", "descriptionKey": "components.form.anatomy.actions", "descriptionFallback": "Action buttons row. Flex with gap."}], "svgDesc": "Schematic of the Form component with 3 numbered internal parts.", "svgTitle": "Anatomy of OrigamForm", "rootClass": "origam-form", "figcaption": "Anatomy of <code>&lt;origam-form&gt;</code> — 3 internal zones. The root ① is a native <code>&lt;form novalidate&gt;</code>. Content ② holds the input fields. Details ③ shows form-level error/hint messages via OrigamMessages.", "svgViewBox": "0 0 700 200"}, "cssVars": [{"name": "--origam-form__actions---margin-top", "defaultValue": "{space.4} (16px)", "descriptionKey": "components.form.css_vars.actions_margin_top", "descriptionFallback": "Top margin separating the actions row from the form body."}, {"name": "--origam-form__actions---gap", "defaultValue": "{space.2} (8px)", "descriptionKey": "components.form.css_vars.actions_gap", "descriptionFallback": "Gap between action buttons in the __actions row."}, {"name": "--origam-form__details---font-size", "defaultValue": "{font.size.sm} (0.75rem)", "descriptionKey": "components.form.css_vars.details_font_size", "descriptionFallback": "Font size of form-level messages."}, {"name": "--origam-form__details---min-height", "defaultValue": "22px", "descriptionKey": "components.form.css_vars.details_min_height", "descriptionFallback": "Minimum height of the details zone. Prevents layout shift when messages appear."}, {"name": "--origam-form--error---messages-color", "defaultValue": "{color.feedback.danger.fgSubtle}", "descriptionKey": "components.form.css_vars.error_messages_color", "descriptionFallback": "Message text colour in error state."}, {"name": "--origam-form--error---icon-color", "defaultValue": "{color.feedback.danger.fgSubtle}", "descriptionKey": "components.form.css_vars.error_icon_color", "descriptionFallback": "Icon colour in error state."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.form.exposed.filter_props", "descriptionFallback": "Filters and forwards props to child components."}, {"name": "submit", "type": "() => void", "descriptionKey": "components.form.exposed.submit", "descriptionFallback": "Triggers form validation and submit. Equivalent to clicking a [type=submit] button."}, {"name": "reset", "type": "() => void", "descriptionKey": "components.form.exposed.reset", "descriptionFallback": "Resets all child fields to their initial value and clears validation errors."}, {"name": "validate", "type": "() => Promise<IFormValidationResult>", "descriptionKey": "components.form.exposed.validate", "descriptionFallback": "Programmatically validates all registered child fields. Returns { valid, errors }."}, {"name": "resetValidation", "type": "() => void", "descriptionKey": "components.form.exposed.reset_validation", "descriptionFallback": "Clears all validation errors without resetting field values."}, {"name": "isValid", "type": "Ref<boolean | null>", "descriptionKey": "components.form.exposed.is_valid", "descriptionFallback": "Current overall validity: true (valid), false (invalid), null (pending)."}, {"name": "isValidating", "type": "Ref<boolean>", "descriptionKey": "components.form.exposed.is_validating", "descriptionFallback": "True while async validators are running."}, {"name": "items", "type": "Ref<IFormField[]>", "descriptionKey": "components.form.exposed.items", "descriptionFallback": "All registered child field descriptors (id, validate, reset, resetValidation, isValid, errorMessages)."}, {"name": "errors", "type": "ComputedRef<IFieldValidationResult[]>", "descriptionKey": "components.form.exposed.errors", "descriptionFallback": "Flat list of { id, errorMessages } for all fields currently in error."}, {"name": "scrollToFirstError", "type": "(options?: boolean | ScrollIntoViewOptions) => Promise<void>", "descriptionKey": "components.form.exposed.scroll_to_first_error", "descriptionFallback": "Scrolls to the first .origam-input--error element in the form DOM."}], "playground": {"controls": [{"kind": "switch", "prop": "disabled", "labelKey": "components.form.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "switch", "prop": "readonly", "labelKey": "components.form.playground.readonly", "defaultValue": false, "labelFallback": "Readonly"}, {"kind": "switch", "prop": "fastFail", "labelKey": "components.form.playground.fast_fail", "defaultValue": false, "labelFallback": "Fast fail"}, {"kind": "select", "prop": "validateOn", "options": [{"label": "(default)", "value": ""}, {"label": "blur", "value": "blur"}, {"label": "input", "value": "input"}, {"label": "submit", "value": "submit"}], "labelKey": "components.form.playground.validate_on", "defaultValue": "", "labelFallback": "Validate on"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('7f1154d2-b9e3-4a12-bb63-283e35f15a1c', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'component', 'grid', 'Grid', 'Layout & Structure', NULL, 'mdi-grid', 'components.catalog.grid.description', 'Declarative CSS Grid container. Exposes every CSS grid property through typed Vue props — no JS track measurement, no fallback to flexbox. columns, rows, gap, areas, autoFlow and alignment props map directly to the corresponding CSS grid properties.', NULL, NULL, 'origam-grid', NULL, 'packages/ds/src/components/Grid/OrigamGrid.vue', 'origam', NULL, NULL, '/stories/?story=components-grid--design', '/docs/components/Grid/OrigamGrid.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.grid.a11y.semantic_root", "noteFallback": "The tag prop defaults to \"div\" — change it to a semantic element when the grid represents a meaningful structure (e.g. tag=\"ul\" with list items, tag=\"section\" for a named region)."}, {"noteKey": "components.grid.a11y.no_reorder", "noteFallback": "CSS Grid visual reordering (via order or explicit grid-row/column placement) can diverge from DOM order. Keyboard navigation follows DOM order — avoid visual arrangements that confuse users navigating by Tab."}], "roles": [], "keyboard": []}, "tokens": {"excerpt": [{"type": "dimension", "value": "var(--origam-space---1)", "tokenPath": "--origam-grid---gap-xs", "descriptionKey": "components.grid.tokens.gap_xs", "descriptionFallback": "Gap size xs (4px)."}, {"type": "dimension", "value": "var(--origam-space---2)", "tokenPath": "--origam-grid---gap-sm", "descriptionKey": "components.grid.tokens.gap_sm", "descriptionFallback": "Gap size sm (8px)."}, {"type": "dimension", "value": "var(--origam-space---4)", "tokenPath": "--origam-grid---gap-md", "descriptionKey": "components.grid.tokens.gap_md", "descriptionFallback": "Gap size md / default (16px)."}, {"type": "dimension", "value": "var(--origam-space---6)", "tokenPath": "--origam-grid---gap-lg", "descriptionKey": "components.grid.tokens.gap_lg", "descriptionFallback": "Gap size lg (24px)."}, {"type": "dimension", "value": "var(--origam-space---8)", "tokenPath": "--origam-grid---gap-xl", "descriptionKey": "components.grid.tokens.gap_xl", "descriptionFallback": "Gap size xl (32px)."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"180\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"28\" y=\"24\" width=\"644\" height=\"132\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"48\" y=\"44\" width=\"184\" height=\"92\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"140\" y=\"94\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\">item 1</text>\n  <rect x=\"244\" y=\"44\" width=\"184\" height=\"92\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.25))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"336\" y=\"94\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\">item 2</text>\n  <rect x=\"440\" y=\"44\" width=\"212\" height=\"92\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"546\" y=\"94\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\">item 3</text>\n  <circle cx=\"36\" cy=\"32\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"36.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"56\" cy=\"52\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"56\" y=\"56\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n", "code": "<!-- OrigamGrid — single declarative element -->\n<div\n  class=\"origam-grid\"\n  style=\"\n    --origam-grid---template-columns: repeat(3, 1fr);\n    --origam-grid---template-rows: auto;\n    --origam-grid---gap: var(--origam-grid---gap-md, 1rem);\n    --origam-grid---auto-flow: row;\n  \"\n>\n  <slot />\n</div>", "legend": [{"cls": ".origam-grid", "num": 1, "descriptionKey": "components.grid.anatomy.root", "descriptionFallback": "Root element. display: grid (or inline-grid when inline=true). All grid properties are applied as inline CSS custom properties computed from props."}, {"cls": "(slotted children)", "num": 2, "descriptionKey": "components.grid.anatomy.items", "descriptionFallback": "Grid items — any element placed in the default slot. No BEM wrapping. Use grid-area or span CSS on individual items for advanced placement."}], "classes": [{"cls": "origam-grid", "descriptionKey": "components.grid.anatomy.root", "descriptionFallback": "Root element. display: grid (or inline-grid). No BEM children."}], "svgDesc": "Schematic of the Grid component with 2 numbered internal parts.", "svgTitle": "Anatomy of OrigamGrid", "rootClass": "origam-grid", "figcaption": "Anatomy of <code>&lt;origam-grid&gt;</code>. The root ① is a single element with CSS Grid properties applied via inline custom properties. Items ② are slotted children — any DOM element, without a BEM wrapper.", "svgViewBox": "0 0 700 180"}, "cssVars": [{"name": "--origam-grid---gap-xs", "defaultValue": "{space.1} (4px)", "descriptionKey": "components.grid.css_vars.gap_xs", "descriptionFallback": "Gap token for size xs."}, {"name": "--origam-grid---gap-sm", "defaultValue": "{space.2} (8px)", "descriptionKey": "components.grid.css_vars.gap_sm", "descriptionFallback": "Gap token for size sm."}, {"name": "--origam-grid---gap-md", "defaultValue": "{space.4} (16px)", "descriptionKey": "components.grid.css_vars.gap_md", "descriptionFallback": "Gap token for size md (default)."}, {"name": "--origam-grid---gap-lg", "defaultValue": "{space.6} (24px)", "descriptionKey": "components.grid.css_vars.gap_lg", "descriptionFallback": "Gap token for size lg."}, {"name": "--origam-grid---gap-xl", "defaultValue": "{space.8} (32px)", "descriptionKey": "components.grid.css_vars.gap_xl", "descriptionFallback": "Gap token for size xl."}, {"name": "--origam-grid---template-columns", "defaultValue": "none", "descriptionKey": "components.grid.css_vars.template_columns", "descriptionFallback": "Computed grid-template-columns value set from the columns prop."}, {"name": "--origam-grid---template-rows", "defaultValue": "none", "descriptionKey": "components.grid.css_vars.template_rows", "descriptionFallback": "Computed grid-template-rows value set from the rows prop."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.grid.exposed.filter_props", "descriptionFallback": "Filters and forwards a subset of props."}, {"name": "columnsCss", "type": "ComputedRef<string | undefined>", "descriptionKey": "components.grid.exposed.columns_css", "descriptionFallback": "Serialised grid-template-columns CSS value computed from the columns prop."}, {"name": "rowsCss", "type": "ComputedRef<string | undefined>", "descriptionKey": "components.grid.exposed.rows_css", "descriptionFallback": "Serialised grid-template-rows CSS value computed from the rows prop."}, {"name": "areasCss", "type": "ComputedRef<string | undefined>", "descriptionKey": "components.grid.exposed.areas_css", "descriptionFallback": "Serialised grid-template-areas CSS value computed from the areas prop."}, {"name": "gapCss", "type": "ComputedRef<string | undefined>", "descriptionKey": "components.grid.exposed.gap_css", "descriptionFallback": "Resolved gap value (size token → CSS var reference, or raw CSS value)."}, {"name": "columnGapCss", "type": "ComputedRef<string | undefined>", "descriptionKey": "components.grid.exposed.column_gap_css", "descriptionFallback": "Resolved column-gap value."}, {"name": "rowGapCss", "type": "ComputedRef<string | undefined>", "descriptionKey": "components.grid.exposed.row_gap_css", "descriptionFallback": "Resolved row-gap value."}], "playground": {"controls": [{"kind": "select", "prop": "columns", "options": [{"label": "1", "value": 1}, {"label": "2", "value": 2}, {"label": "3", "value": 3}, {"label": "4", "value": 4}, {"label": "6", "value": 6}, {"label": "12", "value": 12}, {"label": "auto-fill 200px", "value": "repeat(auto-fill, minmax(200px, 1fr))"}], "labelKey": "components.grid.playground.columns", "defaultValue": 3, "labelFallback": "Columns"}, {"kind": "select", "prop": "gap", "options": [{"label": "xs", "value": "xs"}, {"label": "sm", "value": "sm"}, {"label": "md", "value": "md"}, {"label": "lg", "value": "lg"}, {"label": "xl", "value": "xl"}], "labelKey": "components.grid.playground.gap", "defaultValue": "md", "labelFallback": "Gap"}, {"kind": "select", "prop": "alignItems", "options": [{"label": "stretch", "value": "stretch"}, {"label": "start", "value": "start"}, {"label": "end", "value": "end"}, {"label": "center", "value": "center"}], "labelKey": "components.grid.playground.align_items", "defaultValue": "stretch", "labelFallback": "Align items"}, {"kind": "switch", "prop": "inline", "labelKey": "components.grid.playground.inline", "defaultValue": false, "labelFallback": "Inline grid"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('21b23bdd-2a2e-428a-944f-190506b0d6cb', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'component', 'grid-item', 'GridItem', 'Layout & Structure', NULL, 'mdi-grid', 'components.catalog.grid_item.description', 'Grid placement wrapper that serialises column, row and area props into CSS Grid shorthand.', NULL, NULL, 'origam-grid-item', NULL, 'packages/ds/src/components/Grid/OrigamGridItem.vue', 'origam', NULL, NULL, '/stories/?story=components-grid--design', '/docs/components/Grid/OrigamGrid.html', 'grid', '{"a11y": {"notes": [{"noteKey": "components.grid_item.a11y.semantic_note", "noteFallback": "GridItem is a layout wrapper with no semantic role. Place semantic content inside the default slot. The tag prop lets you promote it to a meaningful element (e.g. tag=\"article\")."}], "roles": [], "keyboard": []}, "tokens": {"excerpt": [{"type": "dimension", "value": "var(--origam-space---1)", "tokenPath": "--origam-grid---gap-xs", "descriptionKey": "components.grid_item.tokens.gap_xs", "descriptionFallback": "Extra-small gap token shared with parent OrigamGrid."}, {"type": "dimension", "value": "var(--origam-space---4)", "tokenPath": "--origam-grid---gap-md", "descriptionKey": "components.grid_item.tokens.gap_md", "descriptionFallback": "Medium gap token shared with parent OrigamGrid."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"28\" y=\"40\" width=\"644\" height=\"120\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"350\" y=\"78\" font-size=\"10\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">grid-column / grid-row / grid-area</text>\n  <rect x=\"60\" y=\"90\" width=\"580\" height=\"48\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"350\" y=\"119\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">#default slot</text>\n  <circle cx=\"36\" cy=\"48\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"52.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"68\" cy=\"98\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"68\" y=\"102.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <line x1=\"46\" y1=\"44\" x2=\"88\" y2=\"28\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"92\" y=\"28\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-grid-item</text>\n", "legend": [{"cls": ".origam-grid-item", "num": 1, "descriptionKey": "components.grid_item.anatomy.root", "descriptionFallback": "Root element. Sets <code>grid-column</code>, <code>grid-row</code> or <code>grid-area</code> via inline styles. Also applies <code>min-width: 0; min-height: 0</code> to prevent overflow."}, {"cls": ".origam-grid-item #default", "num": 2, "descriptionKey": "components.grid_item.anatomy.slot", "descriptionFallback": "Default slot hosting the cell content. No constraints imposed — content defines its own sizing."}], "svgDesc": "Schematic of the GridItem component with 2 numbered internal parts.", "svgTitle": "Anatomy of OrigamGridItem", "rootClass": "origam-grid-item", "figcaption": "Anatomy of <code>&lt;origam-grid-item&gt;</code> — 2 parts: the root element carrying grid placement styles, and the default slot hosting the cell content.", "svgViewBox": "0 0 700 200"}, "cssVars": [], "exposed": [{"name": "columnCss", "type": "ComputedRef<string | undefined>", "descriptionKey": "components.grid_item.exposed.column_css", "descriptionFallback": "Serialised grid-column value derived from the column prop. Readable by parent tooling."}, {"name": "rowCss", "type": "ComputedRef<string | undefined>", "descriptionKey": "components.grid_item.exposed.row_css", "descriptionFallback": "Serialised grid-row value derived from the row prop."}], "playground": {"controls": [{"kind": "select", "prop": "alignSelf", "options": [{"label": "(default)", "value": ""}, {"label": "start", "value": "start"}, {"label": "center", "value": "center"}, {"label": "end", "value": "end"}, {"label": "stretch", "value": "stretch"}], "labelKey": "components.grid_item.playground.align_self", "defaultValue": "", "labelFallback": "Align Self"}, {"kind": "select", "prop": "justifySelf", "options": [{"label": "(default)", "value": ""}, {"label": "start", "value": "start"}, {"label": "center", "value": "center"}, {"label": "end", "value": "end"}, {"label": "stretch", "value": "stretch"}], "labelKey": "components.grid_item.playground.justify_self", "defaultValue": "", "labelFallback": "Justify Self"}], "defaultSlotContent": "Content"}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('4b96a8fb-4149-455d-b71f-32762b9829f4', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'component', 'icon', 'Icon', 'Media', NULL, 'mdi-star-four-points', 'components.catalog.icon.description', 'Universal icon renderer that adapts to MDI class icons, SVG paths, component-based icons and Unicode ligatures.', NULL, NULL, 'origam-icon', NULL, 'packages/ds/src/components/Icon/OrigamIcon.vue', 'origam', NULL, NULL, '/stories/?story=components-icon--design', '/docs/components/Icon/OrigamIcon.html', NULL, '{"playground": {"controls": [{"kind": "switch", "prop": "disabled", "labelKey": "components.icon.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}], "defaultSlotContent": "Content"}}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('e8c3ec76-ad2c-4e87-99fe-a994d30c4645', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'component', 'img', 'Img', 'Data Display', NULL, 'mdi-image-outline', 'components.catalog.img.description', 'Responsive image component with lazy loading, aspect-ratio enforcement, placeholder and error slot, optional gradient overlay, srcset / sizes support, and a smooth fade-in transition on load.', NULL, NULL, 'origam-img', NULL, 'packages/ds/src/components/Img/OrigamImg.vue', 'origam', NULL, NULL, '/stories/?story=components-img--design', '/docs/components/Img/OrigamImg.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.img.a11y.alt", "noteFallback": "Always provide a meaningful alt text. When alt is present, role=\"img\" and aria-label={alt} are set on the root. For decorative images, omit alt and set aria-hidden=\"true\" on the parent."}, {"noteKey": "components.img.a11y.lazy_loading", "noteFallback": "Lazy loading is handled via IntersectionObserver (not the native loading=\"lazy\" attribute) so the component loads the image only when it enters the viewport. The placeholder slot is announced by the browser as the alt text is still present on the root."}, {"noteKey": "components.img.a11y.error_slot", "noteFallback": "When the image fails to load, the #error slot is shown. The slot content should include meaningful text or an icon-with-label so users know the image did not load."}, {"noteKey": "components.img.a11y.reduced_motion", "noteFallback": "The fade-in transition respects prefers-reduced-motion. When the user prefers reduced motion, set transition=\"false\" or use --origam-img---transition-duration: 0ms."}], "roles": ["img"], "keyboard": []}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"28\" y=\"16\" width=\"644\" height=\"168\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"48\" y=\"36\" width=\"604\" height=\"108\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"350\" y=\"80\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">__picture (absolute, object-fit: contain/cover)</text>\n  <rect x=\"200\" y=\"52\" width=\"300\" height=\"40\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"350\" y=\"76\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\">__placeholder (lazy load blur)</text>\n  <rect x=\"48\" y=\"156\" width=\"604\" height=\"20\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.15))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"350\" y=\"170\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\">#default slot (overlay content)</text>\n  <circle cx=\"36\" cy=\"24\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"28.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"56\" cy=\"44\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"56\" y=\"48\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"200\" cy=\"56\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"200\" y=\"60\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n", "code": "<!-- OrigamImg — wraps OrigamResponsive for aspect ratio -->\n<origam-responsive\n  v-intersect=\"intersect\"\n  :aria-label=\"alt\"\n  :aspect-ratio=\"aspectRatio\"\n  :role=\"alt ? ''img'' : undefined\"\n  class=\"origam-img\"\n>\n  <template #additional>\n    <!-- main image (fade-in on load) -->\n    <origam-transition :transition=\"transition\">\n      <img v-show=\"isLoaded\" class=\"origam-img__picture origam-img__picture--cover\" />\n    </origam-transition>\n\n    <!-- lazySrc placeholder (blur filter) -->\n    <origam-transition :transition=\"transition\">\n      <img v-if=\"lazySrc && !isLoaded\" class=\"origam-img__picture origam-img__picture--preload\" />\n    </origam-transition>\n\n    <!-- #placeholder slot — v-if isLoading && slots.placeholder -->\n    <div v-if=\"(isLoading || isError) && slots.placeholder\" class=\"origam-img__placeholder\">\n      <slot name=\"placeholder\" />\n    </div>\n\n    <!-- #error slot — v-if isError && slots.error -->\n    <div v-if=\"isError && slots.error\" class=\"origam-img__error\">\n      <slot name=\"error\" />\n    </div>\n\n    <!-- gradient overlay — v-if gradient -->\n    <div v-if=\"gradient\" class=\"origam-img__gradient\" />\n  </template>\n\n  <!-- #default slot — overlay content -->\n  <template #default v-if=\"hasContent\">\n    <slot name=\"default\" />\n  </template>\n</origam-responsive>", "legend": [{"cls": ".origam-img", "num": 1, "descriptionKey": "components.img.anatomy.root", "descriptionFallback": "Root element wrapping OrigamResponsive. Carries role=\"img\" when alt is present. Has --booting modifier until aspectRatio resolves."}, {"cls": ".origam-img__picture", "num": 2, "descriptionKey": "components.img.anatomy.picture", "descriptionFallback": "Native <img> element. Absolutely positioned, 100% width/height. Has --cover (object-fit: cover) or --contain (object-fit: contain) modifier. Has --preload modifier with blur filter when showing lazySrc."}, {"cls": ".origam-img__placeholder", "num": 3, "descriptionKey": "components.img.anatomy.placeholder", "descriptionFallback": "Shown during loading (or lazySrc phase) when the #placeholder slot is provided. Absolutely positioned layer behind the main image."}, {"cls": ".origam-img__error", "num": 4, "descriptionKey": "components.img.anatomy.error", "descriptionFallback": "Shown when the image fails to load and the #error slot is provided."}, {"cls": ".origam-img__gradient", "num": 5, "descriptionKey": "components.img.anatomy.gradient", "descriptionFallback": "Absolutely positioned <div> rendered when gradient prop is set. Applies background-image: linear-gradient(...)."}], "classes": [{"cls": "origam-img", "descriptionKey": "components.img.anatomy.root", "descriptionFallback": "Root element. Has --booting class until aspectRatio resolves (prevents premature paint)."}, {"cls": "origam-img--booting", "descriptionKey": "components.img.anatomy.booting", "descriptionFallback": "Disables the sizer transition during initial mount. Removed after first rAF."}, {"cls": "origam-img__picture", "descriptionKey": "components.img.anatomy.picture", "descriptionFallback": "Native <img>. Always absolutely positioned inside the responsive sizer."}, {"cls": "origam-img__picture--cover", "descriptionKey": "components.img.anatomy.picture_cover", "descriptionFallback": "object-fit: cover — image fills the container, cropped."}, {"cls": "origam-img__picture--contain", "descriptionKey": "components.img.anatomy.picture_contain", "descriptionFallback": "object-fit: contain — image fits inside the container without cropping."}, {"cls": "origam-img__picture--preload", "descriptionKey": "components.img.anatomy.picture_preload", "descriptionFallback": "Applied to the lazySrc image. Has blur filter while the full-res image loads."}, {"cls": "origam-img__placeholder", "descriptionKey": "components.img.anatomy.placeholder", "descriptionFallback": "#placeholder slot wrapper. Shown during loading."}, {"cls": "origam-img__error", "descriptionKey": "components.img.anatomy.error", "descriptionFallback": "#error slot wrapper. Shown on load failure."}, {"cls": "origam-img__gradient", "descriptionKey": "components.img.anatomy.gradient", "descriptionFallback": "Gradient overlay div. background-image set from the gradient prop."}], "svgDesc": "Schematic of the Img component with 5 numbered internal parts.", "svgTitle": "Anatomy of OrigamImg", "rootClass": "origam-img", "figcaption": "Anatomy of <code>&lt;origam-img&gt;</code> — 5 internal parts. The root ① wraps OrigamResponsive for aspect-ratio enforcement. The picture ② is absolutely positioned. Placeholder ③ and error ④ layers are conditional. The gradient ⑤ is an absolute div when the gradient prop is set.", "svgViewBox": "0 0 700 200"}, "cssVars": [{"name": "--origam-img---background-color", "defaultValue": "{color.surface.overlay}", "descriptionKey": "components.img.css_vars.background_color", "descriptionFallback": "Background colour of the image container while the image loads."}, {"name": "--origam-img---border-radius", "defaultValue": "{radius.none} (0px)", "descriptionKey": "components.img.css_vars.border_radius", "descriptionFallback": "Corner radius of the image root. Overridden by the rounded prop."}, {"name": "--origam-img---transition-duration", "defaultValue": "{motion.duration.medium}", "descriptionKey": "components.img.css_vars.transition_duration", "descriptionFallback": "Fade-in transition duration when the image loads."}, {"name": "--origam-img__picture--preload---filter", "defaultValue": "blur(4px)", "descriptionKey": "components.img.css_vars.picture_preload_filter", "descriptionFallback": "CSS filter applied to the lazySrc placeholder image."}, {"name": "--origam-img__picture--contain---object-fit", "defaultValue": "contain", "descriptionKey": "components.img.css_vars.picture_contain_object_fit", "descriptionFallback": "object-fit value for the --contain modifier."}, {"name": "--origam-img__picture--cover---object-fit", "defaultValue": "cover", "descriptionKey": "components.img.css_vars.picture_cover_object_fit", "descriptionFallback": "object-fit value for the --cover modifier."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.img.exposed.filter_props", "descriptionFallback": "Filters and forwards a subset of props."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.img.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.img.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.img.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.img.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "ComputedRef<boolean>", "descriptionKey": "components.img.exposed.is_loaded", "descriptionFallback": "True when the image has successfully loaded (state === LOADED)."}, {"name": "styleIsLoaded", "type": "Ref<boolean>", "descriptionKey": "components.img.exposed.style_is_loaded", "descriptionFallback": "True once the component style sheet has been injected. Note: distinct from isLoaded (image load state)."}], "playground": {"controls": [{"kind": "text", "prop": "src", "labelKey": "components.img.playground.src", "defaultValue": "https://picsum.photos/600/400", "labelFallback": "Source URL"}, {"kind": "text", "prop": "alt", "labelKey": "components.img.playground.alt", "defaultValue": "Landscape photo", "labelFallback": "Alt text"}, {"kind": "switch", "prop": "cover", "labelKey": "components.img.playground.cover", "defaultValue": false, "labelFallback": "Cover (vs contain)"}, {"kind": "select", "prop": "aspectRatio", "options": [{"label": "(auto)", "value": ""}, {"label": "16/9", "value": "1.7778"}, {"label": "4/3", "value": "1.3333"}, {"label": "1/1 (square)", "value": "1"}, {"label": "3/4 (portrait)", "value": "0.75"}], "labelKey": "components.img.playground.aspect_ratio", "defaultValue": "", "labelFallback": "Aspect ratio"}, {"kind": "select", "prop": "rounded", "options": [{"label": "(none)", "value": ""}, {"label": "sm", "value": "sm"}, {"label": "md", "value": "md"}, {"label": "lg", "value": "lg"}, {"label": "xl", "value": "xl"}, {"label": "pill", "value": "pill"}], "labelKey": "components.img.playground.rounded", "defaultValue": "", "labelFallback": "Rounded"}, {"kind": "select", "prop": "gradient", "options": [{"label": "(none)", "value": ""}, {"label": "to bottom (dark)", "value": "to bottom, transparent, rgba(0,0,0,0.6)"}, {"label": "to top (dark)", "value": "to top, transparent, rgba(0,0,0,0.6)"}], "labelKey": "components.img.playground.gradient", "defaultValue": "", "labelFallback": "Gradient"}]}, "previewVariants": [{"label": "contain", "props": {"alt": "Photo (contain)", "src": "https://picsum.photos/400/300", "width": 200, "aspectRatio": "4/3"}}, {"label": "cover", "props": {"alt": "Photo (cover)", "src": "https://picsum.photos/400/300", "cover": true, "width": 200, "aspectRatio": "4/3"}}, {"label": "rounded", "props": {"alt": "Rounded photo", "src": "https://picsum.photos/300/300", "cover": true, "width": 120, "rounded": "xl", "aspectRatio": 1}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('aa6d8d95-4702-4f95-bc0b-6a63236d2123', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'component', 'infinite-scroll', 'InfiniteScroll', 'Data Display', NULL, 'mdi-infinity', 'components.catalog.infinite_scroll.description', 'Sentinel-based infinite scroll that fires a load event when the user reaches the start or end of a scrollable area.', NULL, NULL, 'origam-infinite-scroll', NULL, 'packages/ds/src/components/InfiniteScroll/OrigamInfiniteScroll.vue', 'origam', NULL, NULL, '/stories/?story=components-infinite-scroll--design', '/docs/components/InfiniteScroll/OrigamInfiniteScroll.html', NULL, '{"playground": {"controls": [{"kind": "select", "prop": "side", "options": [{"label": "(default)", "value": ""}, {"label": "start", "value": "start"}, {"label": "end", "value": "end"}, {"label": "both", "value": "both"}], "labelKey": "components.infinite_scroll.playground.side", "defaultValue": "", "labelFallback": "Side"}, {"kind": "select", "prop": "mode", "options": [{"label": "(default)", "value": ""}, {"label": "intersect", "value": "intersect"}, {"label": "manual", "value": "manual"}], "labelKey": "components.infinite_scroll.playground.mode", "defaultValue": "", "labelFallback": "Mode"}, {"kind": "select", "prop": "direction", "options": [{"label": "(default)", "value": ""}, {"label": "horizontal", "value": "horizontal"}, {"label": "vertical", "value": "vertical"}], "labelKey": "components.infinite_scroll.playground.direction", "defaultValue": "", "labelFallback": "Direction"}], "defaultSlotContent": "Content"}}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('3081f5b5-1eaa-4ad5-8391-1c6105b56b8c', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'component', 'infinite-scroll-intersect', 'InfiniteScrollIntersect', 'Data Display', NULL, 'mdi-arrow-collapse-down', 'components.catalog.infinite_scroll_intersect.description', 'Low-level sentinel element used by InfiniteScroll to detect when the scroll boundary enters the viewport via IntersectionObserver.', NULL, NULL, 'origam-infinite-scroll-intersect', NULL, 'packages/ds/src/components/InfiniteScroll/OrigamInfiniteScrollIntersect.vue', 'origam', NULL, NULL, '/stories/?story=components-infinite-scroll--design', '/docs/components/InfiniteScroll/OrigamInfiniteScroll.html', 'infinite-scroll', '{"a11y": {"notes": [{"noteKey": "components.infinite_scroll_intersect.a11y.invisible_note", "noteFallback": "The sentinel is a non-interactive, invisible element with no ARIA role. Screen readers ignore it. Announce newly loaded content via a live region on the parent component."}], "roles": [], "keyboard": []}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__action--primary---bg)", "tokenPath": "--origam-infinite-scroll__loader---color", "descriptionKey": "components.infinite_scroll_intersect.tokens.loader_color", "descriptionFallback": "Color passed to the OrigamProgress spinner in the loading slot."}, {"type": "dimension", "value": "var(--origam-space---3)", "tokenPath": "--origam-infinite-scroll__loader---gap", "descriptionKey": "components.infinite_scroll_intersect.tokens.loader_gap", "descriptionFallback": "Gap between loader and adjacent elements within the side zone."}, {"type": "color", "value": "var(--origam-color__text---secondary)", "tokenPath": "--origam-infinite-scroll__empty---color", "descriptionKey": "components.infinite_scroll_intersect.tokens.empty_color", "descriptionFallback": "Text color for the empty-state message shown when no more items are available."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"160\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"28\" y=\"40\" width=\"644\" height=\"80\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\" stroke-dasharray=\"6 3\"/>\n  <text x=\"350\" y=\"84\" font-size=\"10\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">height: 1px (invisible sentinel)</text>\n  <circle cx=\"36\" cy=\"48\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"52.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <line x1=\"46\" y1=\"44\" x2=\"88\" y2=\"28\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"92\" y=\"28\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-infinite-scroll-intersect</text>\n", "legend": [{"cls": ".origam-infinite-scroll-intersect", "num": 1, "descriptionKey": "components.infinite_scroll_intersect.anatomy.root", "descriptionFallback": "Root element. A minimal <code>&lt;div&gt;</code> containing a non-breaking space (<code>&amp;nbsp;</code>) to ensure the browser paints it. Observed by <code>useIntersectionObserver</code> and fires the <code>intersect</code> emit on visibility change."}], "svgDesc": "Schematic of the InfiniteScrollIntersect sentinel element with 1 numbered part.", "svgTitle": "Anatomy of OrigamInfiniteScrollIntersect", "rootClass": "origam-infinite-scroll-intersect", "figcaption": "Anatomy of <code>&lt;origam-infinite-scroll-intersect&gt;</code> — a single invisible sentinel <code>&lt;div&gt;</code> observed by an IntersectionObserver.", "svgViewBox": "0 0 700 160"}, "cssVars": [{"name": "--origam-infinite-scroll---loader-color", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.infinite_scroll_intersect.css_vars.loader_color", "descriptionFallback": "Color of the loading spinner in the parent InfiniteScroll loader slot."}, {"name": "--origam-infinite-scroll---loader-gap", "defaultValue": "{space.3}", "descriptionKey": "components.infinite_scroll_intersect.css_vars.loader_gap", "descriptionFallback": "Gap between the loader and adjacent elements in the side zone."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.infinite_scroll_intersect.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}], "playground": {"controls": [{"kind": "select", "prop": "side", "options": [{"label": "(default)", "value": ""}, {"label": "start", "value": "start"}, {"label": "INFINITE_SCROLL_SIDE.START", "value": "INFINITE_SCROLL_SIDE.START"}, {"label": "INFINITE_SCROLL_SIDE.END", "value": "INFINITE_SCROLL_SIDE.END"}, {"label": "end", "value": "end"}, {"label": "INFINITE_SCROLL_SIDE.BOTH", "value": "INFINITE_SCROLL_SIDE.BOTH"}, {"label": "both", "value": "both"}], "labelKey": "components.infinite_scroll_intersect.playground.side", "defaultValue": "", "labelFallback": "Side"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('8a162e9b-578a-4e52-afeb-43f8b2f3b04d', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'component', 'list-subheader', 'ListSubheader', 'Data Display', NULL, 'mdi-format-list-group', 'components.catalog.list_subheader.description', 'Section heading rendered inside a List. Supports inset indent and sticky positioning.', NULL, NULL, 'origam-list-subheader', NULL, 'packages/ds/src/components/List/OrigamListSubheader.vue', 'origam', NULL, NULL, '/stories/?story=components-list-subheader--design', '/docs/components/List/OrigamListSubheader.html', 'list', '{"a11y": {"notes": [{"noteKey": "components.list_subheader.a11y.semantic_note", "noteFallback": "For screen-reader accessibility, consider using tag=\"h2\" through \"h6\" so the subheader is part of the heading outline. The default <div> tag is appropriate when the list is not a standalone section."}, {"noteKey": "components.list_subheader.a11y.sticky_note", "noteFallback": "The sticky variant uses position: sticky; top: 0 — the parent list must have overflow: auto or overflow: scroll for this to work correctly."}, {"noteKey": "components.list_subheader.a11y.contrast_note", "noteFallback": "The default secondary text color may have reduced contrast. Ensure at least 4.5:1 contrast ratio when customising the color prop."}], "roles": [], "keyboard": []}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__text---secondary)", "tokenPath": "--origam-list-subheader---color", "descriptionKey": "components.list_subheader.tokens.color", "descriptionFallback": "Default text color (secondary)."}, {"type": "dimension", "value": "var(--origam-font__size---md)", "tokenPath": "--origam-list__subheader---font-size", "descriptionKey": "components.list_subheader.tokens.font_size", "descriptionFallback": "Font size (0.875rem)."}, {"type": "dimension", "value": "40px", "tokenPath": "--origam-list-subheader---min-height", "descriptionKey": "components.list_subheader.tokens.min_height", "descriptionFallback": "Minimum row height."}, {"type": "dimension", "value": "32px", "tokenPath": "--origam-list-subheader---inset-indent-padding", "descriptionKey": "components.list_subheader.tokens.inset_indent_padding", "descriptionFallback": "Indent applied in --inset mode to align with prepend icon items."}, {"type": "duration", "value": "var(--origam-motion__duration---medium)", "tokenPath": "--origam-list-subheader---transition-duration", "descriptionKey": "components.list_subheader.tokens.transition_duration", "descriptionFallback": "Transition duration for min-height changes."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"140\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"30\" width=\"660\" height=\"50\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"20\" y=\"30\" width=\"660\" height=\"50\" rx=\"4\" fill=\"none\" stroke=\"var(--origam-color__action--primary---bg, #a855f7)\" stroke-width=\"1\" stroke-dasharray=\"6 3\" opacity=\"0.6\"/>\n  <rect x=\"32\" y=\"44\" width=\"400\" height=\"22\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\"/>\n  <text x=\"232\" y=\"59\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">__text (label)</text>\n  <circle cx=\"28\" cy=\"38\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"42\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"60\" cy=\"44\" r=\"8\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"60\" y=\"48\" font-size=\"8\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <line x1=\"38\" y1=\"36\" x2=\"90\" y2=\"20\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"94\" y=\"22\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-list-subheader</text>\n  <text x=\"350\" y=\"125\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">--inset adds 32px indent-padding · --sticky sets position: sticky top: 0</text>\n", "legend": [{"cls": ".origam-list-subheader", "num": 1, "descriptionKey": "components.list_subheader.anatomy.root", "descriptionFallback": "Root element. Flex container (align-items: center). Renders as <code>&lt;div&gt;</code> by default; use <code>tag=\"h2\"</code>–<code>\"h6\"</code> for semantic sectioning."}, {"cls": ".origam-list-subheader__text", "num": 2, "descriptionKey": "components.list_subheader.anatomy.text", "descriptionFallback": "Label text wrapper. <code>overflow: hidden; text-overflow: ellipsis; white-space: nowrap</code>. Rendered only when the title prop or default slot is provided."}], "svgDesc": "Schematic of the ListSubheader component with 2 numbered internal parts.", "svgTitle": "Anatomy of OrigamListSubheader", "rootClass": "origam-list-subheader", "figcaption": "Anatomy of <code>&lt;origam-list-subheader&gt;</code> — 2 internal parts. The root ① is a flex container; the inner text element ② truncates with ellipsis.", "svgViewBox": "0 0 700 140"}, "cssVars": [{"name": "--origam-list-subheader---color", "defaultValue": "{color.text.secondary}", "descriptionKey": "components.list_subheader.css_vars.color", "descriptionFallback": "Text color of the subheader label. Defaults to the semantic secondary text color."}, {"name": "--origam-list-subheader---font-size", "defaultValue": "0.875rem", "descriptionKey": "components.list_subheader.css_vars.font_size", "descriptionFallback": "Font size of the subheader label."}, {"name": "--origam-list-subheader---font-weight", "defaultValue": "400", "descriptionKey": "components.list_subheader.css_vars.font_weight", "descriptionFallback": "Font weight of the subheader label."}, {"name": "--origam-list-subheader---min-height", "defaultValue": "40px", "descriptionKey": "components.list_subheader.css_vars.min_height", "descriptionFallback": "Minimum height of the subheader row. Transitions with density changes."}, {"name": "--origam-list-subheader---padding-inline-end", "defaultValue": "16px", "descriptionKey": "components.list_subheader.css_vars.padding_inline_end", "descriptionFallback": "Trailing padding to avoid text running to the edge."}, {"name": "--origam-list-subheader---line-height", "defaultValue": "1.375rem", "descriptionKey": "components.list_subheader.css_vars.line_height", "descriptionFallback": "Line height of the subheader text."}, {"name": "--origam-list-subheader---inset-indent-padding", "defaultValue": "32px", "descriptionKey": "components.list_subheader.css_vars.inset_indent_padding", "descriptionFallback": "Indent padding applied when --inset modifier is active. Aligns the label with prepend icons."}, {"name": "--origam-list-subheader---transition-duration", "defaultValue": "0.2s", "descriptionKey": "components.list_subheader.css_vars.transition_duration", "descriptionFallback": "Duration of the min-height transition."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.list_subheader.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.list_subheader.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from the computed listSubheaderStyles."}, {"name": "id", "type": "string", "descriptionKey": "components.list_subheader.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.list_subheader.exposed.load", "descriptionFallback": "Injects the computed style sheet. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.list_subheader.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.list_subheader.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "text", "prop": "title", "labelKey": "components.list_subheader.playground.title", "defaultValue": "Section header", "labelFallback": "Title"}, {"kind": "switch", "prop": "inset", "labelKey": "components.list_subheader.playground.inset", "defaultValue": false, "labelFallback": "Inset"}, {"kind": "switch", "prop": "sticky", "labelKey": "components.list_subheader.playground.sticky", "defaultValue": false, "labelFallback": "Sticky"}]}, "previewVariants": [{"label": "default", "props": {"title": "Section header"}}, {"label": "inset", "props": {"inset": true, "title": "Inset header"}}, {"label": "sticky", "props": {"title": "Sticky header", "sticky": true}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('f0de4edb-ce5f-4f86-8333-bff222997c23', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'component', 'loader', 'Loader', 'Feedback & Status', NULL, 'mdi-loading', 'components.catalog.loader.description', 'Toggle container that swaps between a loading spinner (OrigamProgress circular) and the default slot content. Carries aria-busy and aria-label when loading.', NULL, NULL, 'origam-loader', NULL, 'packages/ds/src/components/Loader/OrigamLoader.vue', 'origam', NULL, NULL, '/stories/?story=components-loader--design', '/docs/components/Loader/OrigamLoader.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.loader.a11y.aria_busy_note", "noteFallback": "While loading, the root carries <code>aria-busy=\"true\"</code> and <code>aria-label=\"Loading\"</code> (or the custom loadingText). Screen readers announce the loading state."}, {"noteKey": "components.loader.a11y.live_region_note", "noteFallback": "For critical async operations that change page content, consider wrapping OrigamLoader in a live region (<code>aria-live=\"polite\"</code>) so the transition from loading to loaded is announced."}], "roles": [], "keyboard": []}, "tokens": {"excerpt": [{"type": "other", "value": "100%", "tokenPath": "--origam-loader---height", "descriptionKey": "components.loader.tokens.height", "descriptionFallback": "Default height of the loader root."}, {"type": "other", "value": "auto", "tokenPath": "--origam-loader__progress---margin", "descriptionKey": "components.loader.tokens.progress_margin", "descriptionFallback": "Margin around the progress element in the loader slot."}, {"type": "other", "value": "fixed", "tokenPath": "--origam-loader__fullscreen---position", "descriptionKey": "components.loader.tokens.fullscreen_position", "descriptionFallback": "Position in fullscreen mode."}, {"type": "other", "value": "100vh", "tokenPath": "--origam-loader__fullscreen---height", "descriptionKey": "components.loader.tokens.fullscreen_height", "descriptionFallback": "Height in fullscreen mode."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"24\" y=\"24\" width=\"300\" height=\"152\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <circle cx=\"174\" cy=\"96\" r=\"28\" fill=\"none\" stroke=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.20))\" stroke-width=\"4\"/>\n  <path d=\"M174 68 A28 28 0 0 1 202 96\" fill=\"none\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"4\" stroke-linecap=\"round\"/>\n  <text x=\"174\" y=\"148\" font-size=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">loading=true → #loader slot</text>\n  <rect x=\"376\" y=\"24\" width=\"300\" height=\"152\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1.5\"/>\n  <text x=\"526\" y=\"96\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">#default slot content</text>\n  <text x=\"526\" y=\"112\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">loading=false</text>\n  <circle cx=\"32\" cy=\"32\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"32\" y=\"36.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"384\" cy=\"32\" r=\"10\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"384\" y=\"36.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"174\" cy=\"96\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"174\" y=\"100\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n", "code": "<component\n  :is=\"tag\"\n  :aria-busy=\"isLoading || undefined\"\n  :aria-label=\"isLoading ? ''Loading'' : undefined\"\n  class=\"origam-loader\"\n>\n  <!-- shown when loading=true -->\n  <template v-if=\"isLoading\">\n    <slot name=\"loader\">\n      <origam-progress\n        :color=\"color\"\n        :size=\"23\"\n        type=\"circular\"\n        :width=\"2\"\n        class=\"origam-loader__progress\"\n        indeterminate\n      />\n    </slot>\n  </template>\n  <!-- shown when loading=false -->\n  <template v-else>\n    <slot name=\"default\" />\n  </template>\n</component>", "legend": [{"cls": ".origam-loader (loading)", "num": 1, "descriptionKey": "components.loader.anatomy.loading_state", "descriptionFallback": "Root element while <code>loading</code> is truthy. Carries <code>aria-busy=\"true\"</code> and <code>aria-label=\"Loading\"</code>. Renders the <code>#loader</code> slot."}, {"cls": ".origam-loader (loaded)", "num": 2, "descriptionKey": "components.loader.anatomy.loaded_state", "descriptionFallback": "Root element while <code>loading</code> is falsy. <code>aria-busy</code> and <code>aria-label</code> are absent. Renders the <code>#default</code> slot."}, {"cls": ".origam-loader__progress", "num": 3, "descriptionKey": "components.loader.anatomy.progress", "descriptionFallback": "OrigamProgress circular spinner injected in the default <code>#loader</code> slot. <code>margin: auto</code> centres it. Can be replaced by a custom slot."}], "classes": [{"cls": "origam-loader", "descriptionKey": "components.loader.anatomy.root", "descriptionFallback": "Root element. height: 100% by default."}, {"cls": "origam-loader--fullscreen", "descriptionKey": "components.loader.anatomy.fullscreen", "descriptionFallback": "Optional consumer-applied modifier. position: fixed; top: 0; left: 0; 100vw × 100vh."}, {"cls": "origam-loader__progress", "descriptionKey": "components.loader.anatomy.progress", "descriptionFallback": "OrigamProgress element rendered in the default loader slot. margin: auto centres it."}], "svgDesc": "Schematic of the Loader component in its two states: loading and loaded.", "svgTitle": "Anatomy of OrigamLoader", "rootClass": "origam-loader", "figcaption": "Anatomy of <code>&lt;origam-loader&gt;</code> — ① loading state (root with aria-busy, spinner rendered via #loader slot), ② loaded state (#default content visible), ③ OrigamProgress spinner (size=23, width=2, type=circular).", "svgViewBox": "0 0 700 200"}, "cssVars": [{"name": "--origam-loader---height", "defaultValue": "100%", "descriptionKey": "components.loader.css_vars.height", "descriptionFallback": "Height of the root element. Defaults to 100% to fill its parent."}, {"name": "--origam-loader__fullscreen---position", "defaultValue": "fixed", "descriptionKey": "components.loader.css_vars.fullscreen_position", "descriptionFallback": "Position value when the fullscreen modifier class is applied."}, {"name": "--origam-loader__fullscreen---height", "defaultValue": "100vh", "descriptionKey": "components.loader.css_vars.fullscreen_height", "descriptionFallback": "Height in fullscreen mode."}, {"name": "--origam-loader__fullscreen---width", "defaultValue": "100vw", "descriptionKey": "components.loader.css_vars.fullscreen_width", "descriptionFallback": "Width in fullscreen mode."}, {"name": "--origam-loader__progress---margin", "defaultValue": "auto", "descriptionKey": "components.loader.css_vars.progress_margin", "descriptionFallback": "Margin around the progress spinner — auto centres it."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.loader.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.loader.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.loader.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.loader.exposed.load", "descriptionFallback": "Injects the computed style sheet. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.loader.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.loader.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "switch", "prop": "loading", "labelKey": "components.loader.playground.loading", "defaultValue": true, "labelFallback": "Loading"}, {"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}], "labelKey": "components.loader.playground.color", "defaultValue": "primary", "labelFallback": "Spinner color"}, {"kind": "select", "prop": "tag", "options": [{"label": "span", "value": "span"}, {"label": "div", "value": "div"}, {"label": "section", "value": "section"}], "labelKey": "components.loader.playground.tag", "defaultValue": "span", "labelFallback": "Tag"}]}, "previewVariants": [{"label": "loading", "props": {"color": "primary", "loading": true}, "slotContent": "Content hidden while loading"}, {"label": "loaded", "props": {"loading": false}, "slotContent": "Content visible"}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
