\n  <rect x=\"255\" y=\"55\" width=\"190\" height=\"70\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1.5\"/>\n  <text x=\"350\" y=\"94\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">Col slot</text>\n  <rect x=\"470\" y=\"55\" width=\"190\" height=\"70\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1.5\"/>\n  <text x=\"565\" y=\"94\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">Col slot</text>\n  <circle cx=\"28\" cy=\"38\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"42\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"50\" cy=\"63\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"50\" y=\"67\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"350\" cy=\"40\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"350\" y=\"44\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n", "code": "<!-- root: flex container, tag configurable -->\n<div class=\"origam-row origam-row--density-default origam-row--align-stretch origam-row--justify-start\">\n  <!-- default slot: Col children -->\n  <slot name=\"default\" />\n</div>", "legend": [{"cls": ".origam-row", "num": 1, "descriptionKey": "components.row.anatomy.root", "descriptionFallback": "Root element. Renders as a flex container (display: flex, flex-wrap: wrap). Tag is configurable via the tag prop."}, {"cls": ".origam-row (Col children)", "num": 2, "descriptionKey": "components.row.anatomy.cols", "descriptionFallback": "Direct Col children receive gutter via negative margin on the row and padding on each Col."}, {"cls": ".origam-row--density-{compact|default|comfortable}", "num": 3, "descriptionKey": "components.row.anatomy.density", "descriptionFallback": "Density modifier class. Adjusts --origam-row---density offset on block and inline margins."}], "classes": [{"cls": "origam-row", "descriptionKey": "components.row.anatomy.root", "descriptionFallback": "Root flex container."}, {"cls": "origam-row--density-default", "descriptionKey": "components.row.anatomy.density_default", "descriptionFallback": "Default density (0 offset)."}, {"cls": "origam-row--density-compact", "descriptionKey": "components.row.anatomy.density_compact", "descriptionFallback": "Compact density (−8px margin offset)."}, {"cls": "origam-row--density-comfortable", "descriptionKey": "components.row.anatomy.density_comfortable", "descriptionFallback": "Comfortable density (+8px margin offset)."}, {"cls": "origam-row--align-{value}", "descriptionKey": "components.row.anatomy.align", "descriptionFallback": "Sets --origam-row---align-items. Values: start, end, center, baseline, stretch."}, {"cls": "origam-row--justify-{value}", "descriptionKey": "components.row.anatomy.justify", "descriptionFallback": "Sets --origam-row---justify-content. Values: start, end, center, space-between, space-around, space-evenly."}, {"cls": "origam-row--direction-{value}", "descriptionKey": "components.row.anatomy.direction", "descriptionFallback": "Sets --origam-row---flex-direction. Values: row, row-reverse, column, column-reverse."}, {"cls": "origam-row--border", "descriptionKey": "components.row.anatomy.border", "descriptionFallback": "Applied when border prop is set. Activates border-width and box-shadow tokens."}], "svgDesc": "Schematic of the Row component with 3 numbered parts.", "svgTitle": "Anatomy of OrigamRow", "rootClass": "origam-row", "figcaption": "Anatomy of <code>&lt;origam-row&gt;</code> — 3 parts: root flex container ①, Col children ②, density-driven margin adjustment ③.", "svgViewBox": "0 0 700 180"}, "cssVars": [{"name": "--origam-row---display", "defaultValue": "flex", "descriptionKey": "components.row.css_vars.display", "descriptionFallback": "Display value for the row (always flex)."}, {"name": "--origam-row---flex-direction", "defaultValue": "row", "descriptionKey": "components.row.css_vars.flex_direction", "descriptionFallback": "Flex direction. Overridden by direction prop class."}, {"name": "--origam-row---flex-wrap", "defaultValue": "wrap", "descriptionKey": "components.row.css_vars.flex_wrap", "descriptionFallback": "Wrap mode. Default: wrap (columns stack on overflow)."}, {"name": "--origam-row---flex", "defaultValue": "1 1 auto", "descriptionKey": "components.row.css_vars.flex", "descriptionFallback": "Flex shorthand applied to the row itself."}, {"name": "--origam-row---align-items", "defaultValue": "stretch", "descriptionKey": "components.row.css_vars.align_items", "descriptionFallback": "Cross-axis alignment. Overridden by align / alignSm … alignXxl classes."}, {"name": "--origam-row---justify-content", "defaultValue": "flex-start", "descriptionKey": "components.row.css_vars.justify_content", "descriptionFallback": "Main-axis distribution. Overridden by justify / justifySm … justifyXxl classes."}, {"name": "--origam-row---margin-block-start", "defaultValue": "-4px", "descriptionKey": "components.row.css_vars.margin_block_start", "descriptionFallback": "Default negative block-start margin that creates gutters with Col padding."}, {"name": "--origam-row---margin-inline-start", "defaultValue": "-4px", "descriptionKey": "components.row.css_vars.margin_inline_start", "descriptionFallback": "Default negative inline-start margin."}, {"name": "--origam-row---density", "defaultValue": "0px", "descriptionKey": "components.row.css_vars.density", "descriptionFallback": "Density offset added to block and inline margins. compact: −8px, comfortable: +8px."}, {"name": "--origam-row--border---border-width", "defaultValue": "{border.width.1}", "descriptionKey": "components.row.css_vars.border_width", "descriptionFallback": "Border width when the border modifier class is active."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.row.exposed.filter_props", "descriptionFallback": "Forwards a filtered subset of props to child components."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.row.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from computed row styles."}, {"name": "id", "type": "string", "descriptionKey": "components.row.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.row.exposed.load", "descriptionFallback": "Injects the computed style sheet. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.row.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.row.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.row.playground.color", "defaultValue": "", "labelFallback": "Color / Intent"}, {"kind": "select", "prop": "bgColor", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.row.playground.bg_color", "defaultValue": "", "labelFallback": "Background color"}, {"kind": "select", "prop": "density", "options": [{"label": "(default)", "value": ""}, {"label": "default", "value": "default"}, {"label": "DENSITY.DEFAULT", "value": "DENSITY.DEFAULT"}, {"label": "compact", "value": "compact"}, {"label": "DENSITY.COMPACT", "value": "DENSITY.COMPACT"}, {"label": "DENSITY.COMFORTABLE", "value": "DENSITY.COMFORTABLE"}, {"label": "comfortable", "value": "comfortable"}], "labelKey": "components.row.playground.density", "defaultValue": "", "labelFallback": "Density"}, {"kind": "select", "prop": "align", "options": [{"label": "(default)", "value": ""}, {"label": "start", "value": "start"}, {"label": "center", "value": "center"}, {"label": "end", "value": "end"}, {"label": "stretch", "value": "stretch"}, {"label": "baseline", "value": "baseline"}], "labelKey": "components.row.playground.align", "defaultValue": "", "labelFallback": "Align"}, {"kind": "select", "prop": "justify", "options": [{"label": "(default)", "value": ""}, {"label": "start", "value": "start"}, {"label": "center", "value": "center"}, {"label": "end", "value": "end"}, {"label": "space-between", "value": "space-between"}, {"label": "space-around", "value": "space-around"}, {"label": "space-evenly", "value": "space-evenly"}], "labelKey": "components.row.playground.justify", "defaultValue": "", "labelFallback": "Justify"}, {"kind": "select", "prop": "direction", "options": [{"label": "(default)", "value": ""}, {"label": "FLEX_DIRECTION.ROW", "value": "FLEX_DIRECTION.ROW"}, {"label": "row", "value": "row"}, {"label": "column", "value": "column"}, {"label": "FLEX_DIRECTION.COLUMN", "value": "FLEX_DIRECTION.COLUMN"}, {"label": "FLEX_DIRECTION.COLUMN_REVERSE", "value": "FLEX_DIRECTION.COLUMN_REVERSE"}, {"label": "row-reverse", "value": "row-reverse"}, {"label": "FLEX_DIRECTION.ROW_REVERSE", "value": "FLEX_DIRECTION.ROW_REVERSE"}, {"label": "column-reverse", "value": "column-reverse"}], "labelKey": "components.row.playground.direction", "defaultValue": "", "labelFallback": "Direction"}], "defaultSlotContent": "Content"}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('b7a88bb2-5036-47fa-9539-d74847020225', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'component', 'scale-rotate', 'ScaleRotate', 'Utilities & Providers', NULL, 'mdi-rotate-3d-variant', 'components.catalog.transition_scale_rotate.description', 'CSS-driven Vue transition that combines scale(0) + rotate(−45deg) + opacity on enter, with a symmetric leave. Sub-component of the Transition family.', NULL, NULL, 'origam-scale-rotate', NULL, 'packages/ds/src/components/Transition/OrigamScaleRotate.vue', 'origam', NULL, NULL, '/stories/?story=components-transition--design', '/docs/components/Transition/OrigamTransition.html', 'transition', '{"a11y": {"notes": [{"noteKey": "components.scale_rotate.a11y.reduced_motion", "noteFallback": "The transition is disabled automatically when prefers-reduced-motion: reduce is detected (disabled prop becomes true via useCssTransition)."}, {"noteKey": "components.scale_rotate.a11y.no_role", "noteFallback": "The wrapper is transparent to the accessibility tree. Only the slotted child is announced by screen readers."}], "roles": [], "keyboard": []}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"180\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"40\" y=\"40\" width=\"260\" height=\"100\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"170\" y=\"86\" font-size=\"11\" fill=\"var(--origam-color__text---primary, #3b1c6e)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">enter-active</text>\n  <text x=\"170\" y=\"102\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">scale(0) rotate(−45deg) → full</text>\n  <rect x=\"400\" y=\"40\" width=\"260\" height=\"100\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\" stroke-dasharray=\"5 3\" opacity=\"0.5\"/>\n  <text x=\"530\" y=\"86\" font-size=\"11\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">leave-active</text>\n  <text x=\"530\" y=\"102\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">full → opacity 0</text>\n  <circle cx=\"48\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"48\" y=\"52\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"408\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"408\" y=\"52\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <text x=\"350\" y=\"95\" font-size=\"22\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" text-anchor=\"middle\">→</text>\n", "code": "<!-- wraps <transition> or <transition-group> via useCssTransition -->\n<component :is=\"tag\" :name=\"name\" v-bind=\"transitionProps\">\n  <slot name=\"default\" />\n</component>\n\n<!-- CSS keyframes (global, not scoped) -->\n<!-- .origam-transition--scale-rotate-enter-from { opacity: 0; transform: scale(0) rotate(-45deg); }\n     .origam-transition--scale-rotate-enter-active,\n     .origam-transition--scale-rotate-leave-active { transition-property: transform, opacity; transition-duration: 0.3s; } -->", "legend": [{"cls": ".origam-transition--scale-rotate-enter-active", "num": 1, "descriptionKey": "components.scale_rotate.anatomy.enter", "descriptionFallback": "Enter phase. Child animates from scale(0) rotate(−45deg) opacity:0 to identity. Duration: 0.3 s, easing: cubic-bezier(0.4,0,0.2,1)."}, {"cls": ".origam-transition--scale-rotate-leave-active", "num": 2, "descriptionKey": "components.scale_rotate.anatomy.leave", "descriptionFallback": "Leave phase. Child transitions opacity and transform out over 0.3 s."}], "classes": [{"cls": "origam-transition--scale-rotate", "descriptionKey": "components.scale_rotate.anatomy.class_root", "descriptionFallback": "CSS transition class prefix applied by Vue."}, {"cls": "origam-transition--scale-rotate-enter-from", "descriptionKey": "components.scale_rotate.anatomy.class_enter_from", "descriptionFallback": "Starting state: opacity:0, transform: scale(0) rotate(−45deg)."}, {"cls": "origam-transition--scale-rotate-enter-active", "descriptionKey": "components.scale_rotate.anatomy.class_enter_active", "descriptionFallback": "Transition active state for enter (0.3 s, standard easing)."}, {"cls": "origam-transition--scale-rotate-leave-active", "descriptionKey": "components.scale_rotate.anatomy.class_leave_active", "descriptionFallback": "Transition active state for leave (0.3 s)."}, {"cls": "origam-transition--scale-rotate-move", "descriptionKey": "components.scale_rotate.anatomy.class_move", "descriptionFallback": "Move transition applied in group mode (0.5 s, transform-only)."}], "svgDesc": "Schematic of the scale-rotate transition with entering and leaving elements.", "svgTitle": "Anatomy of OrigamScaleRotate", "rootClass": "origam-transition--scale-rotate", "figcaption": "Anatomy of <code>&lt;origam-scale-rotate&gt;</code> — wraps one child element. The enter ① animates from scale(0) + rotate(−45deg) + opacity:0 to full. The leave ② transitions opacity out over 0.3 s.", "svgViewBox": "0 0 700 180"}, "cssVars": [{"name": "--origam-transition---default-duration", "defaultValue": "{motion.duration.medium}", "descriptionKey": "components.scale_rotate.css_vars.duration", "descriptionFallback": "Default transition duration for the scale-rotate animation (0.3 s hardcoded in the CSS class, token reference for override)."}, {"name": "--origam-transition---default-easing", "defaultValue": "{motion.easing.standard}", "descriptionKey": "components.scale_rotate.css_vars.easing", "descriptionFallback": "Easing function: cubic-bezier(0.4, 0, 0.2, 1)."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.scale_rotate.exposed.filter_props", "descriptionFallback": "Forwards a filtered subset of props to the underlying transition."}], "playground": {"controls": [{"kind": "select", "prop": "mode", "options": [{"label": "(none)", "value": ""}, {"label": "in-out", "value": "in-out"}, {"label": "out-in", "value": "out-in"}], "labelKey": "components.scale_rotate.playground.mode", "defaultValue": "", "labelFallback": "Mode"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.scale_rotate.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "switch", "prop": "group", "labelKey": "components.scale_rotate.playground.group", "defaultValue": false, "labelFallback": "Group mode"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('d64dc05c-6c5b-4fc3-bde3-e9eafd78ad82', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'component', 'select', 'Select', 'Form & Input', NULL, 'mdi-form-select', 'components.catalog.select.description', 'Dropdown selection control with single/multiple mode, chip display, search/autocomplete, and full TextField chrome (label, prefix, suffix, clearable).', NULL, NULL, 'origam-select', NULL, 'packages/ds/src/components/Select/OrigamSelect.vue', 'origam', NULL, NULL, '/stories/?story=components-select--design', '/docs/components/Select/OrigamSelect.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.select.a11y.combobox_note", "noteFallback": "The field uses role=\"combobox\" with aria-expanded reflecting the menu state and aria-haspopup=\"listbox\". The dropdown list has role=\"listbox\" and each item has role=\"option\"."}, {"noteKey": "components.select.a11y.aria_label_note", "noteFallback": "The label prop is used as aria-label on the internal text field. When using a placeholder-only UI, also provide an explicit aria-label for screen readers."}, {"noteKey": "components.select.a11y.multiple_note", "noteFallback": "In multiple mode, aria-multiselectable=\"true\" is set on the listbox. Each selected option has aria-selected=\"true\"."}], "roles": ["combobox", "listbox", "option"], "keyboard": [{"key": "Enter / Space", "actionKey": "components.select.a11y.key_enter", "actionFallback": "Opens the dropdown or confirms the highlighted option."}, {"key": "Escape", "actionKey": "components.select.a11y.key_escape", "actionFallback": "Closes the dropdown without changing the selection."}, {"key": "Arrow Down / Up", "actionKey": "components.select.a11y.key_arrows", "actionFallback": "Navigates between items in the open dropdown list."}, {"key": "Tab", "actionKey": "components.select.a11y.key_tab", "actionFallback": "Closes the dropdown and moves focus to the next element."}]}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"560\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"20\" width=\"520\" height=\"60\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"40\" y=\"43\" font-size=\"10\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" font-family=\"''JetBrains Mono'',monospace\">Framework</text>\n  <text x=\"40\" y=\"64\" font-size=\"12\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" font-family=\"''JetBrains Mono'',monospace\">Vue 3</text>\n  <text x=\"510\" y=\"56\" font-size=\"18\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">▾</text>\n  <rect x=\"20\" y=\"100\" width=\"520\" height=\"80\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(124,58,237,0.3))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"46\" y=\"122\" font-size=\"11\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-family=\"''JetBrains Mono'',monospace\">Vue 3</text>\n  <text x=\"46\" y=\"146\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" font-family=\"''JetBrains Mono'',monospace\">React</text>\n  <text x=\"46\" y=\"166\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" font-family=\"''JetBrains Mono'',monospace\">Svelte</text>\n  <circle cx=\"28\" cy=\"28\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"32\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"48\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"48\" y=\"52\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"120\" cy=\"68\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"120\" y=\"72\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"510\" cy=\"40\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"510\" y=\"44\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"28\" cy=\"108\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"112\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <circle cx=\"46\" cy=\"122\" r=\"7\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"46\" y=\"126\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">6</text>\n", "code": "<!-- extends TextField chrome -->\n<origam-text-field class=\"origam-select origam-select--single\">\n  <!-- dropdown via OrigamMenu -->\n  <origam-menu content-class=\"origam-select__content\">\n    <origam-list class=\"origam-select__menu-list\">\n      <origam-list-item>\n        <!-- item text with optional search highlight -->\n        <span class=\"origam-select__text\">Vue 3</span>\n      </origam-list-item>\n    </origam-list>\n  </origam-menu>\n\n  <!-- selected value display -->\n  <span class=\"origam-select__selection-text\">Vue 3</span>\n\n  <!-- menu toggle chevron (appendInner) -->\n  <origam-icon class=\"origam-select__menu-icon\" />\n</origam-text-field>", "legend": [{"cls": ".origam-select", "num": 1, "descriptionKey": "components.select.anatomy.root", "descriptionFallback": "Root element extending OrigamTextField. Carries BEM modifiers for single/multiple, chips, autocomplete and open states."}, {"cls": "origam-select (label via TextField)", "num": 2, "descriptionKey": "components.select.anatomy.label", "descriptionFallback": "Floating label managed by the inner TextField field slot."}, {"cls": ".origam-select__selection-text", "num": 3, "descriptionKey": "components.select.anatomy.selection_text", "descriptionFallback": "Selected value text displayed inside the field when not in chip mode."}, {"cls": ".origam-select__menu-icon", "num": 4, "descriptionKey": "components.select.anatomy.menu_icon", "descriptionFallback": "Chevron icon toggling the dropdown. Rotates 180° when the menu is open."}, {"cls": ".origam-select__content (inside OrigamMenu)", "num": 5, "descriptionKey": "components.select.anatomy.content", "descriptionFallback": "Dropdown container rendered by OrigamMenu. Contains the OrigamList of items."}, {"cls": ".origam-select__text / .origam-select__mask", "num": 6, "descriptionKey": "components.select.anatomy.text", "descriptionFallback": "Per-item text label. Includes .origam-select__mask and .origam-select__unmask for the search-highlight animation."}], "classes": [{"cls": "origam-select", "descriptionKey": "components.select.anatomy.root", "descriptionFallback": "Root block."}, {"cls": "origam-select--single", "descriptionKey": "components.select.anatomy.modifier_single", "descriptionFallback": "Applied when multiple=false."}, {"cls": "origam-select--multiple", "descriptionKey": "components.select.anatomy.modifier_multiple", "descriptionFallback": "Applied when multiple=true."}, {"cls": "origam-select--chips", "descriptionKey": "components.select.anatomy.modifier_chips", "descriptionFallback": "Applied when chips=true."}, {"cls": "origam-select--active-menu", "descriptionKey": "components.select.anatomy.modifier_active_menu", "descriptionFallback": "Applied while the dropdown is open."}, {"cls": "origam-select--autocomplete", "descriptionKey": "components.select.anatomy.modifier_autocomplete", "descriptionFallback": "Applied when autocomplete=true."}, {"cls": "origam-select__selection-text", "descriptionKey": "components.select.anatomy.selection_text", "descriptionFallback": "Selected value text."}, {"cls": "origam-select__menu-icon", "descriptionKey": "components.select.anatomy.menu_icon", "descriptionFallback": "Chevron toggle icon."}, {"cls": "origam-select__content", "descriptionKey": "components.select.anatomy.content", "descriptionFallback": "Dropdown content wrapper (applied to OrigamMenu content-class)."}, {"cls": "origam-select__text", "descriptionKey": "components.select.anatomy.text", "descriptionFallback": "Item title text span."}], "svgDesc": "Schematic of the Select component with 6 numbered parts.", "svgTitle": "Anatomy of OrigamSelect", "rootClass": "origam-select", "figcaption": "Anatomy of <code>&lt;origam-select&gt;</code> — 6 parts: the root field ①, label ②, selection text ③, menu chevron ④, dropdown list container ⑤, and list items ⑥.", "svgViewBox": "0 0 560 200"}, "cssVars": [{"name": "--origam-select---min-width", "defaultValue": "150px", "descriptionKey": "components.select.css_vars.min_width", "descriptionFallback": "Minimum width of the select field."}, {"name": "--origam-select__list---background-color", "defaultValue": "{color.surface.raised}", "descriptionKey": "components.select.css_vars.list_background_color", "descriptionFallback": "Background color of the dropdown list panel."}, {"name": "--origam-select__list---border-radius", "defaultValue": "{radius.md}", "descriptionKey": "components.select.css_vars.list_border_radius", "descriptionFallback": "Border-radius of the dropdown panel."}, {"name": "--origam-select__list---max-height", "defaultValue": "300px", "descriptionKey": "components.select.css_vars.list_max_height", "descriptionFallback": "Maximum height of the dropdown list before it scrolls."}, {"name": "--origam-select__list---box-shadow", "defaultValue": "{shadow.lg}", "descriptionKey": "components.select.css_vars.list_box_shadow", "descriptionFallback": "Box shadow of the dropdown panel."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.select.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to sub-components."}, {"name": "isFocused", "type": "Ref<boolean>", "descriptionKey": "components.select.exposed.is_focused", "descriptionFallback": "Reactive focus state of the underlying input."}, {"name": "menu", "type": "Ref<boolean>", "descriptionKey": "components.select.exposed.menu", "descriptionFallback": "Reactive open/closed state of the dropdown menu."}, {"name": "handleSelect", "type": "(item: any) => void", "descriptionKey": "components.select.exposed.handle_select", "descriptionFallback": "Imperatively select an item programmatically."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.select.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.select.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.select.exposed.load", "descriptionFallback": "Injects the computed style sheet. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.select.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.select.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "text", "prop": "label", "labelKey": "components.select.playground.label", "defaultValue": "Select an option", "labelFallback": "Label"}, {"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}], "labelKey": "components.select.playground.color", "defaultValue": "primary", "labelFallback": "Color"}, {"kind": "select", "prop": "density", "options": [{"label": "compact", "value": "compact"}, {"label": "default", "value": "default"}, {"label": "comfortable", "value": "comfortable"}], "labelKey": "components.select.playground.density", "defaultValue": "default", "labelFallback": "Density"}, {"kind": "switch", "prop": "clearable", "labelKey": "components.select.playground.clearable", "defaultValue": false, "labelFallback": "Clearable"}, {"kind": "switch", "prop": "multiple", "labelKey": "components.select.playground.multiple", "defaultValue": false, "labelFallback": "Multiple"}, {"kind": "switch", "prop": "chips", "labelKey": "components.select.playground.chips", "defaultValue": false, "labelFallback": "Chips"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.select.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}]}, "previewVariants": [{"label": "single", "props": {"items": ["Vue", "React", "Svelte"], "label": "Framework"}}, {"label": "with value", "props": {"items": ["Vue", "React", "Svelte"], "label": "Framework", "modelValue": "Vue"}}, {"label": "outlined", "props": {"items": ["primary", "secondary", "success"], "label": "Color", "variant": "outlined"}}, {"label": "disabled", "props": {"items": ["Vue", "React"], "label": "Disabled", "disabled": true, "modelValue": "Vue"}, "ariaLabel": "Disabled select"}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('ea5bbebd-0cab-491e-86c7-ac0b87ad4cd8', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'component', 'selection-control', 'SelectionControl', 'Form & Input', NULL, 'mdi-checkbox-marked-circle-outline', 'components.catalog.selection_control.description', 'Base selection-control primitive used by Checkbox, Radio, Switch and similar inputs. Renders a ripple zone, a native input and a label with full ARIA support.', NULL, NULL, 'origam-selection-control', NULL, 'packages/ds/src/components/SelectionControl/OrigamSelectionControl.vue', 'origam', NULL, NULL, '/stories/?story=components-selection-control--design', '/docs/components/SelectionControl/OrigamSelectionControl.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.selection_control.a11y.native_note", "noteFallback": "A native <input type=\"checkbox|radio\"> is always rendered (even when the input slot is customised). This ensures browser-native focus, keyboard handling and form participation."}, {"noteKey": "components.selection_control.a11y.aria_checked_note", "noteFallback": "aria-checked is set automatically by the native input. For type=\"checkbox\", aria-checked is forwarded explicitly via the :aria-checked binding."}, {"noteKey": "components.selection_control.a11y.label_note", "noteFallback": "The label is wired to the input via for/id. Clicking the label toggles the control and fires click:label."}, {"noteKey": "components.selection_control.a11y.error_note", "noteFallback": "When error=true, the label and icon adopt --origam-selection-control---color-error for visual feedback. No aria-invalid is set at this layer — use OrigamInput / form-level components for validation semantics."}], "roles": ["checkbox", "radio"], "keyboard": [{"key": "Space", "actionKey": "components.selection_control.a11y.key_space", "actionFallback": "Toggles the checkbox or selects the radio option."}, {"key": "Tab", "actionKey": "components.selection_control.a11y.key_tab", "actionFallback": "Moves focus to the next interactive element."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__text---primary)", "tokenPath": "--origam-selection-control---color", "descriptionKey": "components.selection_control.tokens.color", "descriptionFallback": "Default control color."}, {"type": "color", "value": "var(--origam-color__text---disabled)", "tokenPath": "--origam-selection-control---color-disabled", "descriptionKey": "components.selection_control.tokens.color_disabled", "descriptionFallback": "Color when disabled."}, {"type": "number", "value": "var(--origam-opacity---50)", "tokenPath": "--origam-selection-control---opacity-disabled", "descriptionKey": "components.selection_control.tokens.opacity_disabled", "descriptionFallback": "Opacity when disabled."}, {"type": "dimension", "value": "40px", "tokenPath": "--origam-selection-control__wrapper---width", "descriptionKey": "components.selection_control.tokens.wrapper_width", "descriptionFallback": "Base width of the ripple wrapper (before density offset)."}, {"type": "dimension", "value": "40px", "tokenPath": "--origam-selection-control__wrapper---height", "descriptionKey": "components.selection_control.tokens.wrapper_height", "descriptionFallback": "Base height of the ripple wrapper."}, {"type": "duration", "value": "var(--origam-motion__duration---medium)", "tokenPath": "--origam-selection-control---transition-duration", "descriptionKey": "components.selection_control.tokens.transition_duration", "descriptionFallback": "Transition duration for icon/color animations."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"520\" height=\"180\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"20\" width=\"480\" height=\"140\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\" stroke-dasharray=\"6 3\"/>\n  <rect x=\"40\" y=\"50\" width=\"60\" height=\"60\" rx=\"30\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1.5\"/>\n  <text x=\"70\" y=\"85\" font-size=\"18\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">✓</text>\n  <rect x=\"115\" y=\"68\" width=\"220\" height=\"24\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\"/>\n  <text x=\"225\" y=\"85\" font-size=\"12\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">Label text</text>\n  <circle cx=\"28\" cy=\"28\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"32\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"50\" cy=\"60\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"50\" y=\"64\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"70\" cy=\"54\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"70\" y=\"58\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"70\" cy=\"82\" r=\"8\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"70\" y=\"86\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"130\" cy=\"60\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"130\" y=\"64\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n", "code": "<div class=\"origam-selection-control origam-selection-control--dirty\">\n  <!-- wrapper: ripple target + background color -->\n  <div class=\"origam-selection-control__wrapper\">\n    <!-- input zone with v-ripple -->\n    <div class=\"origam-selection-control__input\">\n      <!-- icon (true/false icon) -->\n      <origam-icon :icon=\"icon\" :color=\"bgColor\" />\n      <!-- visually hidden native input -->\n      <input type=\"checkbox\" :id :name :value :checked :disabled />\n    </div>\n  </div>\n\n  <!-- label -->\n  <div class=\"origam-selection-control__label\">\n    <origam-label :for=\"id\" :text=\"label\" :color=\"color\" />\n  </div>\n</div>", "legend": [{"cls": ".origam-selection-control", "num": 1, "descriptionKey": "components.selection_control.anatomy.root", "descriptionFallback": "Root element. Flex-row, aligns wrapper and label. Carries state modifiers (dirty, disabled, error, focused, inline)."}, {"cls": ".origam-selection-control__wrapper", "num": 2, "descriptionKey": "components.selection_control.anatomy.wrapper", "descriptionFallback": "Square wrapper (40px + density). Hosts the ripple zone and the background color layer."}, {"cls": ".origam-selection-control__input", "num": 3, "descriptionKey": "components.selection_control.anatomy.input", "descriptionFallback": "Circular ripple zone (v-ripple). Contains the OrigamIcon (true/falseIcon) and the native input."}, {"cls": "input[type=\"checkbox|radio\"] (native)", "num": 4, "descriptionKey": "components.selection_control.anatomy.native_input", "descriptionFallback": "Visually hidden native input. Manages browser check state, form submission, and screen-reader focus."}, {"cls": ".origam-selection-control__label", "num": 5, "descriptionKey": "components.selection_control.anatomy.label", "descriptionFallback": "Label container. Renders OrigamLabel with for/id wiring."}], "classes": [{"cls": "origam-selection-control", "descriptionKey": "components.selection_control.anatomy.root", "descriptionFallback": "Root block."}, {"cls": "origam-selection-control--dirty", "descriptionKey": "components.selection_control.anatomy.modifier_dirty", "descriptionFallback": "Applied when modelValue is truthy (checked state)."}, {"cls": "origam-selection-control--disabled", "descriptionKey": "components.selection_control.anatomy.modifier_disabled", "descriptionFallback": "Applied when disabled=true."}, {"cls": "origam-selection-control--error", "descriptionKey": "components.selection_control.anatomy.modifier_error", "descriptionFallback": "Applied when error=true. Changes icon and label color."}, {"cls": "origam-selection-control--focused", "descriptionKey": "components.selection_control.anatomy.modifier_focused", "descriptionFallback": "Applied when the native input is focused."}, {"cls": "origam-selection-control--focus-visible", "descriptionKey": "components.selection_control.anatomy.modifier_focus_visible", "descriptionFallback": "Applied on keyboard focus for the visible outline."}, {"cls": "origam-selection-control--inline", "descriptionKey": "components.selection_control.anatomy.modifier_inline", "descriptionFallback": "Applied when inline=true."}, {"cls": "origam-selection-control__wrapper", "descriptionKey": "components.selection_control.anatomy.wrapper", "descriptionFallback": "Inner wrapper hosting ripple and background."}, {"cls": "origam-selection-control__input", "descriptionKey": "components.selection_control.anatomy.input", "descriptionFallback": "Ripple zone with icon and native input."}, {"cls": "origam-selection-control__label", "descriptionKey": "components.selection_control.anatomy.label", "descriptionFallback": "Label container."}], "svgDesc": "Schematic of the SelectionControl component with 5 numbered parts.", "svgTitle": "Anatomy of OrigamSelectionControl", "rootClass": "origam-selection-control", "figcaption": "Anatomy of <code>&lt;origam-selection-control&gt;</code> — 5 parts: root ①, wrapper ②, input zone ③ (with ripple), icon/native input ④, and label ⑤.", "svgViewBox": "0 0 520 180"}, "cssVars": [{"name": "--origam-selection-control---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.selection_control.css_vars.color", "descriptionFallback": "Default text/icon color."}, {"name": "--origam-selection-control---color-disabled", "defaultValue": "{color.text.disabled}", "descriptionKey": "components.selection_control.css_vars.color_disabled", "descriptionFallback": "Color when the control is disabled."}, {"name": "--origam-selection-control---color-error", "defaultValue": "{color.feedback.danger.bg}", "descriptionKey": "components.selection_control.css_vars.color_error", "descriptionFallback": "Color when the control is in error state."}, {"name": "--origam-selection-control---opacity-disabled", "defaultValue": "{opacity.50}", "descriptionKey": "components.selection_control.css_vars.opacity_disabled", "descriptionFallback": "Opacity of the entire control when disabled."}, {"name": "--origam-selection-control---density", "defaultValue": "0px", "descriptionKey": "components.selection_control.css_vars.density", "descriptionFallback": "Density modifier. compact → -8px, comfortable → +8px."}, {"name": "--origam-selection-control---transition-duration", "defaultValue": "{motion.duration.medium}", "descriptionKey": "components.selection_control.css_vars.transition_duration", "descriptionFallback": "Transition duration for icon and color animations."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.selection_control.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to sub-components."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.selection_control.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.selection_control.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.selection_control.exposed.load", "descriptionFallback": "Injects the computed style sheet. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.selection_control.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.selection_control.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "select", "prop": "type", "options": [{"label": "checkbox", "value": "checkbox"}, {"label": "radio", "value": "radio"}], "labelKey": "components.selection_control.playground.type", "defaultValue": "checkbox", "labelFallback": "Type"}, {"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}], "labelKey": "components.selection_control.playground.color", "defaultValue": "primary", "labelFallback": "Color"}, {"kind": "text", "prop": "label", "labelKey": "components.selection_control.playground.label", "defaultValue": "Option label", "labelFallback": "Label"}, {"kind": "select", "prop": "density", "options": [{"label": "compact", "value": "compact"}, {"label": "default", "value": "default"}, {"label": "comfortable", "value": "comfortable"}], "labelKey": "components.selection_control.playground.density", "defaultValue": "default", "labelFallback": "Density"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.selection_control.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "switch", "prop": "error", "labelKey": "components.selection_control.playground.error", "defaultValue": false, "labelFallback": "Error"}, {"kind": "switch", "prop": "inline", "labelKey": "components.selection_control.playground.inline", "defaultValue": false, "labelFallback": "Inline"}]}, "previewVariants": [{"label": "unchecked", "props": {"type": "checkbox", "color": "primary", "label": "Unchecked", "trueIcon": "mdi-checkbox-marked", "falseIcon": "mdi-checkbox-blank-outline"}}, {"label": "checked", "props": {"type": "checkbox", "color": "primary", "label": "Checked", "trueIcon": "mdi-checkbox-marked", "falseIcon": "mdi-checkbox-blank-outline", "trueValue": true, "modelValue": true}}, {"label": "radio", "props": {"type": "radio", "color": "secondary", "label": "Radio", "trueIcon": "mdi-radiobox-marked", "falseIcon": "mdi-radiobox-blank"}}, {"label": "error", "props": {"type": "checkbox", "color": "danger", "error": true, "label": "Error", "trueIcon": "mdi-checkbox-marked", "falseIcon": "mdi-checkbox-blank-outline"}}, {"label": "disabled", "props": {"type": "checkbox", "label": "Disabled", "disabled": true, "trueIcon": "mdi-checkbox-marked", "falseIcon": "mdi-checkbox-blank-outline"}, "ariaLabel": "Disabled selection control"}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
