"Loading"}, {"kind": "switch", "prop": "readonly", "labelKey": "components.text_field.playground.readonly", "defaultValue": false, "labelFallback": "Read-only"}, {"kind": "text", "prop": "label", "labelKey": "components.text_field.playground.label", "defaultValue": "", "labelFallback": "Label"}, {"kind": "text", "prop": "placeholder", "labelKey": "components.text_field.playground.placeholder", "defaultValue": "", "labelFallback": "Placeholder"}, {"kind": "select", "prop": "type", "options": [{"label": "(default)", "value": ""}, {"label": "text", "value": "text"}, {"label": "email", "value": "email"}, {"label": "number", "value": "number"}, {"label": "password", "value": "password"}, {"label": "search", "value": "search"}, {"label": "tel", "value": "tel"}, {"label": "url", "value": "url"}, {"label": "date", "value": "date"}, {"label": "time", "value": "time"}], "labelKey": "components.text_field.playground.type", "defaultValue": "", "labelFallback": "Type"}], "defaultSlotContent": "Content"}}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('2d8365e7-215b-41a4-85c8-67acbd4d2344', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'component', 'text-mask', 'TextMask', 'Data Display', NULL, 'mdi-format-color-text', 'components.catalog.text_mask.description', 'Renders text with a gradient or image as a transparent fill via background-clip: text. Supports animated gradients (pan, rotate, pulse, zoom).', NULL, NULL, 'origam-text-mask', NULL, 'packages/ds/src/components/TextMask/OrigamTextMask.vue', 'origam', NULL, NULL, '/stories/?story=components-textmask--design', '/docs/components/TextMask/OrigamTextMask.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.text_mask.a11y.dom_text_note", "noteFallback": "The text content is preserved in the DOM as plain text (or semantic slot content). The background-clip:text transform is purely CSS — screen readers and search engines read the real text."}, {"noteKey": "components.text_mask.a11y.reduced_motion_note", "noteFallback": "All CSS animations are disabled under prefers-reduced-motion: reduce. The background-size reverts to cover so the gradient is still visible."}, {"noteKey": "components.text_mask.a11y.contrast_note", "noteFallback": "Gradient backgrounds may produce low-contrast regions. Verify WCAG AA contrast ratios for the minimum-contrast point of the gradient. Add a fallback color for browsers that do not support background-clip:text."}], "roles": ["(none — inline text)"], "keyboard": []}, "tokens": {"excerpt": [{"type": "dimension", "value": "var(--origam-font__size---5xl)", "tokenPath": "--origam-text-mask---font-size-default", "descriptionKey": "components.text_mask.tokens.font_size_default", "descriptionFallback": "Reference display font size used in the DS story defaults."}, {"type": "fontWeight", "value": "var(--origam-font__weight---bold)", "tokenPath": "--origam-text-mask---font-weight-default", "descriptionKey": "components.text_mask.tokens.font_weight_default", "descriptionFallback": "Reference font weight used in the DS story defaults."}, {"type": "number", "value": "var(--origam-font__lineHeight---tight)", "tokenPath": "--origam-text-mask---line-height-default", "descriptionKey": "components.text_mask.tokens.line_height_default", "descriptionFallback": "Tight line-height suited to large display text."}, {"type": "duration", "value": "3s", "tokenPath": "--origam-text-mask__animation---duration-default", "descriptionKey": "components.text_mask.tokens.animation_duration", "descriptionFallback": "Default animation cycle duration."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"600\" height=\"160\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"28\" y=\"40\" width=\"544\" height=\"80\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <defs>\n    <linearGradient id=\"tmGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" style=\"stop-color:#7c3aed\"/>\n      <stop offset=\"50%\" style=\"stop-color:#a855f7\"/>\n      <stop offset=\"100%\" style=\"stop-color:#06b6d4\"/>\n    </linearGradient>\n  </defs>\n  <text x=\"300\" y=\"92\" font-size=\"32\" fill=\"url(#tmGrad)\" font-weight=\"900\" text-anchor=\"middle\" font-family=\"sans-serif\">Hello World</text>\n  <circle cx=\"36\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"52.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <line x1=\"46\" y1=\"40\" x2=\"80\" y2=\"22\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"84\" y=\"22\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-text-mask</text>\n  <text x=\"300\" y=\"148\" font-size=\"8\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">background-clip: text · -webkit-text-fill-color: transparent</text>\n", "code": "<!-- root: inline-block with background-clip: text -->\n<component\n  :is=\"tag\"\n  class=\"origam-text-mask\"\n  :class=\"[\n    `origam-text-mask--align-${align}`,\n    `origam-text-mask--${animationType}`,\n    { ''origam-text-mask--animated'': animated }\n  ]\"\n  :style=\"{\n    ''--origam-text-mask---bg'': resolvedBackground,\n    ''--origam-text-mask---font-size'': ...,\n    ''--origam-text-mask---font-weight'': ...,\n  }\"\n>\n  <!-- slot content (wins over text prop) -->\n  <slot v-if=\"hasSlot\"/>\n  <template v-else>{{ text }}</template>\n</component>", "legend": [{"cls": ".origam-text-mask", "num": 1, "descriptionKey": "components.text_mask.anatomy.root", "descriptionFallback": "Root element (span by default). Sets background-image, background-clip:text and -webkit-text-fill-color:transparent. Animation classes are added when animated=true."}], "classes": [{"cls": "origam-text-mask", "descriptionKey": "components.text_mask.anatomy.root", "descriptionFallback": "Root element. display:inline-block with background-clip:text."}, {"cls": "origam-text-mask--align-left", "descriptionKey": "components.text_mask.anatomy.align_left", "descriptionFallback": "text-align: left (default)."}, {"cls": "origam-text-mask--align-center", "descriptionKey": "components.text_mask.anatomy.align_center", "descriptionFallback": "text-align: center."}, {"cls": "origam-text-mask--align-right", "descriptionKey": "components.text_mask.anatomy.align_right", "descriptionFallback": "text-align: right."}, {"cls": "origam-text-mask--animated", "descriptionKey": "components.text_mask.anatomy.animated", "descriptionFallback": "Added when animated=true. Enables the keyframe animation selected by --{animationType}."}, {"cls": "origam-text-mask--pan", "descriptionKey": "components.text_mask.anatomy.pan", "descriptionFallback": "Horizontal pan animation (background-position 0% → 100%)."}, {"cls": "origam-text-mask--rotate", "descriptionKey": "components.text_mask.anatomy.rotate", "descriptionFallback": "Hue-rotate animation (filter: hue-rotate 0 → 360deg)."}, {"cls": "origam-text-mask--pulse", "descriptionKey": "components.text_mask.anatomy.pulse", "descriptionFallback": "Size pulse animation (background-size oscillates)."}, {"cls": "origam-text-mask--zoom", "descriptionKey": "components.text_mask.anatomy.zoom", "descriptionFallback": "Zoom animation (background-size 100% → 220%)."}], "svgDesc": "Schematic of the TextMask component — root with inline background-clip style.", "svgTitle": "Anatomy of OrigamTextMask", "rootClass": "origam-text-mask", "figcaption": "Anatomy of <code>&lt;origam-text-mask&gt;</code> — single root element with <code>background-clip: text</code>. The text content is preserved in the DOM; the gradient/image visual is CSS-only.", "svgViewBox": "0 0 600 160"}, "cssVars": [{"name": "--origam-text-mask---bg", "defaultValue": "undefined", "descriptionKey": "components.text_mask.css_vars.bg", "descriptionFallback": "Resolved background-image value (gradient or url()). Set from the background prop."}, {"name": "--origam-text-mask---duration", "defaultValue": "3s", "descriptionKey": "components.text_mask.css_vars.duration", "descriptionFallback": "Animation cycle duration. Maps to animationDuration prop."}, {"name": "--origam-text-mask---font-size", "defaultValue": "inherit", "descriptionKey": "components.text_mask.css_vars.font_size", "descriptionFallback": "Font size of the masked text."}, {"name": "--origam-text-mask---font-weight", "defaultValue": "inherit", "descriptionKey": "components.text_mask.css_vars.font_weight", "descriptionFallback": "Font weight of the masked text."}, {"name": "--origam-text-mask---font-family", "defaultValue": "inherit", "descriptionKey": "components.text_mask.css_vars.font_family", "descriptionFallback": "Font family of the masked text."}, {"name": "--origam-text-mask---line-height", "defaultValue": "1.1", "descriptionKey": "components.text_mask.css_vars.line_height", "descriptionFallback": "Line height of the masked text."}, {"name": "--origam-text-mask---letter-spacing", "defaultValue": "normal", "descriptionKey": "components.text_mask.css_vars.letter_spacing", "descriptionFallback": "Letter spacing of the masked text."}], "exposed": [{"name": "resolvedBackground", "type": "ComputedRef<string>", "descriptionKey": "components.text_mask.exposed.resolved_background", "descriptionFallback": "The resolved background-image CSS value (gradient or url()). Derived from the background prop after resolveGradient() processing."}, {"name": "hasSlot", "type": "ComputedRef<boolean>", "descriptionKey": "components.text_mask.exposed.has_slot", "descriptionFallback": "True when the default slot is provided. When false, the text prop is rendered."}], "playground": {"controls": [{"kind": "select", "prop": "background", "options": [{"label": "Violet → Cyan", "value": "linear-gradient(90deg, #7c3aed, #a855f7, #06b6d4)"}, {"label": "Sunset", "value": "linear-gradient(135deg, #f59e0b, #ef4444, #a855f7)"}, {"label": "Ocean", "value": "linear-gradient(135deg, #06b6d4, #3b82f6, #6366f1)"}, {"label": "Forest", "value": "linear-gradient(135deg, #10b981, #059669, #3b82f6)"}], "labelKey": "components.text_mask.playground.background", "defaultValue": "linear-gradient(90deg, #7c3aed, #a855f7, #06b6d4)", "labelFallback": "Background"}, {"kind": "switch", "prop": "animated", "labelKey": "components.text_mask.playground.animated", "defaultValue": false, "labelFallback": "Animated"}, {"kind": "select", "prop": "animationType", "options": [{"label": "pan", "value": "pan"}, {"label": "rotate", "value": "rotate"}, {"label": "pulse", "value": "pulse"}, {"label": "zoom", "value": "zoom"}], "labelKey": "components.text_mask.playground.animation_type", "defaultValue": "pan", "labelFallback": "Animation type"}, {"kind": "number", "prop": "fontSize", "labelKey": "components.text_mask.playground.font_size", "defaultValue": 48, "labelFallback": "Font size (px)"}, {"kind": "select", "prop": "fontWeight", "options": [{"label": "400", "value": 400}, {"label": "600", "value": 600}, {"label": "700", "value": 700}, {"label": "800", "value": 800}, {"label": "900", "value": 900}], "labelKey": "components.text_mask.playground.font_weight", "defaultValue": 800, "labelFallback": "Font weight"}, {"kind": "select", "prop": "align", "options": [{"label": "left", "value": "left"}, {"label": "center", "value": "center"}, {"label": "right", "value": "right"}], "labelKey": "components.text_mask.playground.align", "defaultValue": "left", "labelFallback": "Align"}], "defaultSlotContent": "Origam DS"}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('25e7e39f-0c4b-424d-83dd-05321a1c3cd8', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'const', 'chart-dash-array-dotted', 'CHART_DASH_ARRAY_DOTTED', 'Chart', NULL, NULL, NULL, NULL, 'export const CHART_DASH_ARRAY_DOTTED = ''2 4''', NULL, NULL, '''2 4''', 'packages/ds/src/consts/Chart/chart.const.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('c635f35b-7257-4bf5-aba7-4378db2a01ea', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'component', 'theme-provider', 'ThemeProvider', 'Utilities & Providers', NULL, 'mdi-palette-swatch-outline', 'components.catalog.theme_provider.description', 'Overrides the active theme and/or color mode for a sub-tree by setting data-theme and data-mode attributes on a display:contents wrapper.', NULL, NULL, 'origam-theme-provider', NULL, 'packages/ds/src/components/ThemeProvider/OrigamThemeProvider.vue', 'origam', NULL, NULL, '/stories/?story=components-themeprovider--design', '/docs/components/ThemeProvider/OrigamThemeProvider.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.theme_provider.a11y.contents_note", "noteFallback": "The root wrapper uses display:contents — it is invisible to the layout engine and does not create an extra stacking context or box. It should not affect the accessibility tree of its children."}, {"noteKey": "components.theme_provider.a11y.tag_note", "noteFallback": "When the sub-tree is a semantic region, use tag=''section'' or tag=''article'' to add semantic meaning to the wrapper instead of the invisible div default."}], "roles": ["(none — display:contents wrapper)"], "keyboard": []}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"600\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"28\" y=\"20\" width=\"544\" height=\"160\" rx=\"4\" fill=\"transparent\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\" stroke-dasharray=\"8 4\"/>\n  <text x=\"300\" y=\"48\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">data-theme=\"ocean\" data-mode=\"dark\"</text>\n  <text x=\"300\" y=\"62\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-style=\"italic\">display: contents — no layout impact</text>\n  <rect x=\"80\" y=\"80\" width=\"200\" height=\"80\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\"/>\n  <text x=\"180\" y=\"126\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"sans-serif\">child component A</text>\n  <rect x=\"320\" y=\"80\" width=\"200\" height=\"80\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\"/>\n  <text x=\"420\" y=\"126\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"sans-serif\">child component B</text>\n  <circle cx=\"36\" cy=\"28\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"32.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <line x1=\"46\" y1=\"20\" x2=\"80\" y2=\"6\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"84\" y=\"6\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-theme-provider</text>\n", "code": "<!-- root: display:contents — no layout impact -->\n<component\n  :is=\"tag\"\n  class=\"origam-theme-provider\"\n  :data-theme=\"theme !== ''auto'' ? theme : undefined\"\n  :data-mode=\"mode !== ''auto'' ? mode : undefined\"\n>\n  <!-- all children resolve CSS vars from this scope -->\n  <slot />\n</component>", "legend": [{"cls": ".origam-theme-provider", "num": 1, "descriptionKey": "components.theme_provider.anatomy.root", "descriptionFallback": "Root wrapper element (div by default). display:contents ensures it has no layout impact. data-theme and data-mode are set from the theme and mode props, enabling CSS variable scope resolution for all descendant components."}], "classes": [{"cls": "origam-theme-provider", "descriptionKey": "components.theme_provider.anatomy.root", "descriptionFallback": "Root wrapper. display:contents. Sole purpose is to carry data-theme / data-mode attribute for CSS scope."}], "svgDesc": "Schematic of the ThemeProvider — a display:contents wrapper that rewrites data-theme / data-mode.", "svgTitle": "Anatomy of OrigamThemeProvider", "rootClass": "origam-theme-provider", "figcaption": "Anatomy of <code>&lt;origam-theme-provider&gt;</code> — a single <code>display:contents</code> wrapper ① that rewrites <code>data-theme</code> and <code>data-mode</code> on its root element. Child components resolve their CSS custom properties against this new scope automatically.", "svgViewBox": "0 0 600 200"}, "playground": {"controls": [{"kind": "select", "prop": "mode", "options": [{"label": "(default)", "value": ""}, {"label": "MODE.HORIZONTAL", "value": "MODE.HORIZONTAL"}, {"label": "horizontal", "value": "horizontal"}, {"label": "MODE.VERTICAL", "value": "MODE.VERTICAL"}, {"label": "vertical", "value": "vertical"}, {"label": "shift", "value": "shift"}, {"label": "MODE.SHIFT", "value": "MODE.SHIFT"}], "labelKey": "components.theme_provider.playground.mode", "defaultValue": "", "labelFallback": "Mode"}], "defaultSlotContent": "Content"}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('7bad5797-09db-472d-a996-93bc128cef86', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'component', 'timeline', 'Timeline', 'Data Display', NULL, 'mdi-timeline-outline', 'components.catalog.timeline.description', 'Vertical or horizontal event timeline with dot, connector and item content slots. Supports alternating layout, custom intents per item, and scroll-snapping in horizontal mode.', NULL, NULL, 'origam-timeline', NULL, 'packages/ds/src/components/Timeline/OrigamTimeline.vue', 'origam', NULL, NULL, '/stories/?story=components-timeline--design', '/docs/components/Timeline/OrigamTimeline.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.timeline.a11y.list_note", "noteFallback": "The root element has role=\"list\". Each OrigamTimelineItem has role=\"listitem\". Screen readers announce the number of items in the timeline."}, {"noteKey": "components.timeline.a11y.label_note", "noteFallback": "Provide an ariaLabel prop to describe the timeline purpose (e.g. \"Project history\"). Without it, screen readers will not contextualise the list."}, {"noteKey": "components.timeline.a11y.connector_note", "noteFallback": "The track column (dot + connector) has aria-hidden=\"true\" — it is decorative. Meaningful content lives in the content area."}], "roles": ["list", "listitem (per item)"], "keyboard": [{"key": "Tab", "actionKey": "components.timeline.a11y.key_tab", "actionFallback": "Moves focus between interactive elements inside the timeline items (links, buttons in content slots)."}]}, "tokens": {"excerpt": [{"type": "dimension", "value": "var(--origam-space---4)", "tokenPath": "--origam-timeline---gap", "descriptionKey": "components.timeline.tokens.gap", "descriptionFallback": "Gap between items."}, {"type": "dimension", "value": "var(--origam-space---3)", "tokenPath": "--origam-timeline---dot-size", "descriptionKey": "components.timeline.tokens.dot_size", "descriptionFallback": "Dot diameter."}, {"type": "color", "value": "var(--origam-color__action--primary---bg)", "tokenPath": "--origam-timeline---dot-bg", "descriptionKey": "components.timeline.tokens.dot_bg", "descriptionFallback": "Default dot background color."}, {"type": "color", "value": "var(--origam-color__border---subtle)", "tokenPath": "--origam-timeline---connector-color", "descriptionKey": "components.timeline.tokens.connector_color", "descriptionFallback": "Connector line color."}, {"type": "dimension", "value": "var(--origam-border__width---thin)", "tokenPath": "--origam-timeline---connector-thickness", "descriptionKey": "components.timeline.tokens.connector_thickness", "descriptionFallback": "Connector line width."}, {"type": "fontWeight", "value": "var(--origam-font__weight---semibold)", "tokenPath": "--origam-timeline---title-font-weight", "descriptionKey": "components.timeline.tokens.title_font_weight", "descriptionFallback": "Title font weight."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"600\" height=\"300\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"28\" y=\"20\" width=\"544\" height=\"260\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <circle cx=\"120\" cy=\"70\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke=\"var(--origam-color__surface---default, #fff)\" stroke-width=\"2\"/>\n  <line x1=\"120\" y1=\"80\" x2=\"120\" y2=\"150\" stroke=\"var(--origam-color__border---subtle, rgba(168,85,247,0.3))\" stroke-width=\"1.5\"/>\n  <circle cx=\"120\" cy=\"160\" r=\"10\" fill=\"var(--origam-color__feedback--success---bg, #10b981)\" stroke=\"var(--origam-color__surface---default, #fff)\" stroke-width=\"2\"/>\n  <line x1=\"120\" y1=\"170\" x2=\"120\" y2=\"240\" stroke=\"var(--origam-color__border---subtle, rgba(168,85,247,0.3))\" stroke-width=\"1.5\"/>\n  <circle cx=\"120\" cy=\"250\" r=\"10\" fill=\"var(--origam-color__feedback--info---bg, #06b6d4)\" stroke=\"var(--origam-color__surface---default, #fff)\" stroke-width=\"2\"/>\n  <rect x=\"148\" y=\"50\" width=\"380\" height=\"40\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\"/>\n  <text x=\"160\" y=\"76\" font-size=\"11\" fill=\"var(--origam-color__text---primary, #1a1a2e)\" font-family=\"''JetBrains Mono'',monospace\">Account created</text>\n  <rect x=\"148\" y=\"140\" width=\"380\" height=\"40\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\"/>\n  <text x=\"160\" y=\"166\" font-size=\"11\" fill=\"var(--origam-color__text---primary, #1a1a2e)\" font-family=\"''JetBrains Mono'',monospace\">Profile completed</text>\n  <rect x=\"148\" y=\"230\" width=\"380\" height=\"40\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\"/>\n  <text x=\"160\" y=\"256\" font-size=\"11\" fill=\"var(--origam-color__text---primary, #1a1a2e)\" font-family=\"''JetBrains Mono'',monospace\">First payment</text>\n  <circle cx=\"36\" cy=\"28\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"32.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"110\" cy=\"58\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"110\" y=\"62.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"132\" cy=\"82\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"132\" y=\"86.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"148\" cy=\"58\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"148\" y=\"62.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <line x1=\"46\" y1=\"20\" x2=\"80\" y2=\"6\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"84\" y=\"6\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-timeline</text>\n", "code": "<!-- root: role=\"list\" -->\n<component :is=\"tag\" class=\"origam-timeline\" role=\"list\" :aria-label=\"ariaLabel\">\n  <!-- horizontal mode wraps items in a scroll-snap track -->\n  <div v-if=\"orientation === ''horizontal''\" class=\"origam-timeline__track-wrapper\">\n    <slot>\n      <origam-timeline-item v-for=\"(entry, i) in items\" :key=\"i\" v-bind=\"entry\" />\n    </slot>\n  </div>\n\n  <!-- vertical mode: direct slot -->\n  <slot v-else>\n    <origam-timeline-item v-for=\"(entry, i) in items\" :key=\"i\" v-bind=\"entry\" />\n  </slot>\n</component>", "legend": [{"cls": ".origam-timeline", "num": 1, "descriptionKey": "components.timeline.anatomy.root", "descriptionFallback": "Root element with role=\"list\". Contains a track-wrapper div in horizontal mode."}, {"cls": ".origam-timeline-item__dot", "num": 2, "descriptionKey": "components.timeline.anatomy.dot", "descriptionFallback": "Circular dot. Background color driven by the item intent via --origam-timeline-item---dot-bg. Hosts the #dot slot (icon by default when icon prop is set)."}, {"cls": ".origam-timeline-item__connector", "num": 3, "descriptionKey": "components.timeline.anatomy.connector", "descriptionFallback": "Vertical (or horizontal) line connecting consecutive dots. Hidden on the last item when truncateLine=true."}, {"cls": ".origam-timeline-item__content", "num": 4, "descriptionKey": "components.timeline.anatomy.content", "descriptionFallback": "Content area next to the dot. Contains the header (title + subtitle) and an optional body. Hosts the #default and #body slots."}], "classes": [{"cls": "origam-timeline", "descriptionKey": "components.timeline.anatomy.root", "descriptionFallback": "Root element (role=\"list\")."}, {"cls": "origam-timeline__track-wrapper", "descriptionKey": "components.timeline.anatomy.track_wrapper", "descriptionFallback": "Horizontal scroll container. Only rendered when orientation=\"horizontal\"."}, {"cls": "origam-timeline-item", "descriptionKey": "components.timeline.anatomy.item", "descriptionFallback": "Individual timeline entry (role=\"listitem\")."}, {"cls": "origam-timeline-item__track", "descriptionKey": "components.timeline.anatomy.track", "descriptionFallback": "Track column: dot + connector (aria-hidden)."}, {"cls": "origam-timeline-item__dot", "descriptionKey": "components.timeline.anatomy.dot", "descriptionFallback": "Circular dot. Intent-colored background."}, {"cls": "origam-timeline-item__connector", "descriptionKey": "components.timeline.anatomy.connector", "descriptionFallback": "Line connecting this dot to the next."}, {"cls": "origam-timeline-item__content", "descriptionKey": "components.timeline.anatomy.content", "descriptionFallback": "Content area: header + body."}], "svgDesc": "Schematic of the Timeline component with 5 numbered internal parts.", "svgTitle": "Anatomy of OrigamTimeline", "rootClass": "origam-timeline", "figcaption": "Anatomy of <code>&lt;origam-timeline&gt;</code> — 4 internal parts: root list ①, dot ②, connector ③ and content area ④ per item.", "svgViewBox": "0 0 600 300"}, "cssVars": [{"name": "--origam-timeline---gap", "defaultValue": "{space.4}", "descriptionKey": "components.timeline.css_vars.gap", "descriptionFallback": "Gap between timeline items and between the dot and content."}, {"name": "--origam-timeline---dot-size", "defaultValue": "{space.3}", "descriptionKey": "components.timeline.css_vars.dot_size", "descriptionFallback": "Diameter of the dot."}, {"name": "--origam-timeline---dot-bg", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.timeline.css_vars.dot_bg", "descriptionFallback": "Default dot background color (overridden per item by intent)."}, {"name": "--origam-timeline---dot-color", "defaultValue": "{color.action.primary.fg}", "descriptionKey": "components.timeline.css_vars.dot_color", "descriptionFallback": "Default dot foreground (icon) color."}, {"name": "--origam-timeline---connector-color", "defaultValue": "{color.border.subtle}", "descriptionKey": "components.timeline.css_vars.connector_color", "descriptionFallback": "Color of the connector line between dots."}, {"name": "--origam-timeline---connector-thickness", "defaultValue": "{border.width.thin}", "descriptionKey": "components.timeline.css_vars.connector_thickness", "descriptionFallback": "Width/height of the connector line."}, {"name": "--origam-timeline---track-width", "defaultValue": "{space.6}", "descriptionKey": "components.timeline.css_vars.track_width", "descriptionFallback": "Width of the track column (dot + connector area)."}, {"name": "--origam-timeline---title-font-size", "defaultValue": "{font.size.md}", "descriptionKey": "components.timeline.css_vars.title_font_size", "descriptionFallback": "Font size of the item title."}, {"name": "--origam-timeline---subtitle-color", "defaultValue": "{color.text.secondary}", "descriptionKey": "components.timeline.css_vars.subtitle_color", "descriptionFallback": "Color of the item subtitle and body text."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.timeline.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.timeline.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.timeline.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.timeline.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.timeline.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.timeline.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "select", "prop": "orientation", "options": [{"label": "vertical", "value": "vertical"}, {"label": "horizontal", "value": "horizontal"}], "labelKey": "components.timeline.playground.orientation", "defaultValue": "vertical", "labelFallback": "Orientation"}, {"kind": "select", "prop": "side", "options": [{"label": "start", "value": "start"}, {"label": "end", "value": "end"}, {"label": "alternating", "value": "alternating"}], "labelKey": "components.timeline.playground.side", "defaultValue": "start", "labelFallback": "Side"}, {"kind": "switch", "prop": "truncateLine", "labelKey": "components.timeline.playground.truncate_line", "defaultValue": true, "labelFallback": "Truncate last connector"}, {"kind": "select", "prop": "color", "optio