INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('9b9754dc-955b-4d48-9e83-6e35adbb8e4e', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'component', 'timeline-item', 'TimelineItem', 'Data Display', NULL, 'mdi-timeline-outline', 'components.catalog.timeline_item.description', 'Individual event entry inside an OrigamTimeline — renders a dot, connector and content area with optional title, subtitle, body, icon and intent.', NULL, NULL, 'origam-timeline-item', NULL, 'packages/ds/src/components/Timeline/OrigamTimelineItem.vue', 'origam', NULL, NULL, '/stories/?story=components-timeline--design', '/docs/components/Timeline/OrigamTimeline.html', 'timeline', '{"a11y": {"notes": [{"noteKey": "components.timeline_item.a11y.role_note", "noteFallback": "OrigamTimelineItem uses role=\"listitem\" matching the parent OrigamTimeline role=\"list\". The track area (dot + connector) is aria-hidden=\"true\" — it is decorative."}, {"noteKey": "components.timeline_item.a11y.icon_note", "noteFallback": "Icons inside the dot are decorative and aria-hidden by the parent track. If the icon conveys status, provide the information via title or description for screen readers."}], "roles": ["listitem"], "keyboard": []}, "tokens": {"excerpt": [{"type": "dimension", "value": "var(--origam-space---3)", "tokenPath": "--origam-timeline---dot-size", "descriptionKey": "components.timeline_item.tokens.dot_size", "descriptionFallback": "Diameter of the timeline dot."}, {"type": "color", "value": "var(--origam-color__action--primary---bg)", "tokenPath": "--origam-timeline---dot-bg", "descriptionKey": "components.timeline_item.tokens.dot_bg", "descriptionFallback": "Default dot background color (overridden per-item by intent)."}, {"type": "color", "value": "var(--origam-color__border---subtle)", "tokenPath": "--origam-timeline---connector-color", "descriptionKey": "components.timeline_item.tokens.connector_color", "descriptionFallback": "Connector line color."}, {"type": "dimension", "value": "var(--origam-border__width---thin)", "tokenPath": "--origam-timeline---connector-thickness", "descriptionKey": "components.timeline_item.tokens.connector_thickness", "descriptionFallback": "Connector line thickness."}, {"type": "fontWeight", "value": "var(--origam-font__weight---semibold)", "tokenPath": "--origam-timeline---title-font-weight", "descriptionKey": "components.timeline_item.tokens.title_font_weight", "descriptionFallback": "Font weight of the item title."}, {"type": "color", "value": "var(--origam-color__text---secondary)", "tokenPath": "--origam-timeline---subtitle-color", "descriptionKey": "components.timeline_item.tokens.subtitle_color", "descriptionFallback": "Color of subtitle and body text."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"640\" height=\"260\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <!-- root -->\n  <rect x=\"20\" y=\"30\" width=\"600\" height=\"200\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <!-- track -->\n  <rect x=\"40\" y=\"50\" width=\"40\" height=\"160\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.30))\" stroke-width=\"1\"/>\n  <!-- dot -->\n  <circle cx=\"60\" cy=\"80\" r=\"14\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke=\"var(--origam-color__surface---default, #fff)\" stroke-width=\"2\"/>\n  <text x=\"60\" y=\"85\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">icon</text>\n  <!-- connector -->\n  <line x1=\"60\" y1=\"96\" x2=\"60\" y2=\"200\" stroke=\"var(--origam-color__border---subtle, rgba(168,85,247,0.3))\" stroke-width=\"2\" stroke-dasharray=\"4 2\"/>\n  <!-- content -->\n  <rect x=\"100\" y=\"50\" width=\"500\" height=\"160\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.20))\" stroke-width=\"1\"/>\n  <!-- header -->\n  <rect x=\"116\" y=\"66\" width=\"460\" height=\"44\" rx=\"2\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.25))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"200\" y=\"84\" font-size=\"10\" fill=\"var(--origam-color__text---primary, #1a1035)\" font-family=\"''JetBrains Mono'',monospace\" font-weight=\"600\">title</text>\n  <text x=\"200\" y=\"100\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" font-family=\"''JetBrains Mono'',monospace\">subtitle</text>\n  <!-- body -->\n  <rect x=\"116\" y=\"120\" width=\"460\" height=\"72\" rx=\"2\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.25))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"346\" y=\"160\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">body / description</text>\n  <!-- number circles -->\n  <circle cx=\"30\" cy=\"38\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"30\" y=\"42.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"48\" cy=\"58\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"48\" y=\"62\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"60\" cy=\"80\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" stroke=\"none\"/>\n  <text x=\"60\" y=\"84\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"60\" cy=\"148\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"60\" y=\"152\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"110\" cy=\"58\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"110\" y=\"62\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <circle cx=\"120\" cy=\"74\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"120\" y=\"78\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">6</text>\n  <circle cx=\"120\" cy=\"128\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"120\" y=\"132\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">7</text>\n  <line x1=\"30\" y1=\"26\" x2=\"58\" y2=\"10\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"62\" y=\"8\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-timeline-item</text>\n  <text x=\"320\" y=\"248\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">③ dot · ④ connector · ⑥ header · ⑦ body — inside track ② and content ⑤</text>\n", "code": "<!-- root: role=\"listitem\" -->\n<div class=\"origam-timeline-item origam-timeline-item--orientation-vertical\">\n  <!-- track: dot + connector -->\n  <div class=\"origam-timeline-item__track\" aria-hidden=\"true\">\n    <div class=\"origam-timeline-item__dot\">\n      <slot name=\"dot\">\n        <origam-icon v-if=\"icon\" :icon=\"icon\" :size=\"10\" />\n      </slot>\n    </div>\n    <span v-if=\"showConnector\" class=\"origam-timeline-item__connector\" />\n  </div>\n\n  <!-- content area -->\n  <div class=\"origam-timeline-item__content\">\n    <slot name=\"default\">\n      <div class=\"origam-timeline-item__header\">\n        <span class=\"origam-timeline-item__title\">{{ title }}</span>\n        <span class=\"origam-timeline-item__subtitle\">{{ subtitle }}</span>\n      </div>\n      <div class=\"origam-timeline-item__body\">\n        <slot name=\"body\">{{ description }}</slot>\n      </div>\n    </slot>\n  </div>\n</div>", "legend": [{"cls": ".origam-timeline-item", "num": 1, "descriptionKey": "components.timeline_item.anatomy.root", "descriptionFallback": "Root element. <code>role=\"listitem\"</code>, flex row. Orientation modifier class switches to flex-column in horizontal mode."}, {"cls": ".origam-timeline-item__track", "num": 2, "descriptionKey": "components.timeline_item.anatomy.track", "descriptionFallback": "Track column: contains the dot and connector, flex-column, fixed width. In horizontal mode switches to flex-row."}, {"cls": ".origam-timeline-item__dot", "num": 3, "descriptionKey": "components.timeline_item.anatomy.dot", "descriptionFallback": "Colored dot circle. Background and foreground color driven by the resolved intent via CSS custom properties."}, {"cls": ".origam-timeline-item__connector", "num": 4, "descriptionKey": "components.timeline_item.anatomy.connector", "descriptionFallback": "Connector line between dots. Hidden when <code>isLast=true</code> and <code>truncateLine=true</code>."}, {"cls": ".origam-timeline-item__content", "num": 5, "descriptionKey": "components.timeline_item.anatomy.content", "descriptionFallback": "Content area, flex: 1. Hosts the header and body sub-elements or the entire default slot."}, {"cls": ".origam-timeline-item__header", "num": 6, "descriptionKey": "components.timeline_item.anatomy.header", "descriptionFallback": "Header row containing title and subtitle spans. Visible only when default slot is not used."}, {"cls": ".origam-timeline-item__body", "num": 7, "descriptionKey": "components.timeline_item.anatomy.body", "descriptionFallback": "Body text area. Rendered when description prop or the body slot is provided."}], "classes": [{"cls": "origam-timeline-item", "descriptionKey": "components.timeline_item.anatomy.root", "descriptionFallback": "Root element. role=\"listitem\", flex row, gap between track and content."}, {"cls": "origam-timeline-item--orientation-horizontal", "descriptionKey": "components.timeline_item.anatomy.horizontal", "descriptionFallback": "Applied when orientation=\"horizontal\". Switches to flex-column layout with horizontal track."}, {"cls": "origam-timeline-item--side-start", "descriptionKey": "components.timeline_item.anatomy.side_start", "descriptionFallback": "Applied when content is on the start side (default)."}, {"cls": "origam-timeline-item--side-end", "descriptionKey": "components.timeline_item.anatomy.side_end", "descriptionFallback": "Applied when content is on the end side (row-reverse layout)."}, {"cls": "origam-timeline-item--alternating", "descriptionKey": "components.timeline_item.anatomy.alternating", "descriptionFallback": "Applied when side=\"alternating\". Even items go to start, odd items to end."}, {"cls": "origam-timeline-item--last", "descriptionKey": "components.timeline_item.anatomy.last", "descriptionFallback": "Applied when isLast=true. Removes bottom padding from content area."}, {"cls": "origam-timeline-item__track", "descriptionKey": "components.timeline_item.anatomy.track", "descriptionFallback": "Track column containing dot and connector."}, {"cls": "origam-timeline-item__dot", "descriptionKey": "components.timeline_item.anatomy.dot", "descriptionFallback": "Circular dot. Color set via intent-resolved CSS custom properties."}, {"cls": "origam-timeline-item__connector", "descriptionKey": "components.timeline_item.anatomy.connector", "descriptionFallback": "Connector line. Hidden on last item when truncateLine is active."}, {"cls": "origam-timeline-item__content", "descriptionKey": "components.timeline_item.anatomy.content", "descriptionFallback": "Content wrapper. flex: 1."}, {"cls": "origam-timeline-item__header", "descriptionKey": "components.timeline_item.anatomy.header", "descriptionFallback": "Header row with title and subtitle."}, {"cls": "origam-timeline-item__title", "descriptionKey": "components.timeline_item.anatomy.title", "descriptionFallback": "Title text element."}, {"cls": "origam-timeline-item__subtitle", "descriptionKey": "components.timeline_item.anatomy.subtitle", "descriptionFallback": "Subtitle text element."}, {"cls": "origam-timeline-item__body", "descriptionKey": "components.timeline_item.anatomy.body", "descriptionFallback": "Body text area. Only rendered when description or body slot is present."}], "svgDesc": "Schematic of the TimelineItem component with 7 numbered internal parts.", "svgTitle": "Anatomy of OrigamTimelineItem", "rootClass": "origam-timeline-item", "figcaption": "Anatomy of <code>&lt;origam-timeline-item&gt;</code> — 7 internal parts. The track holds the dot and connector; the content area holds the header (title + subtitle) and the body.", "svgViewBox": "0 0 640 260"}, "cssVars": [{"name": "--origam-timeline---gap", "defaultValue": "14px", "descriptionKey": "components.timeline_item.css_vars.gap", "descriptionFallback": "Gap between the track and the content area."}, {"name": "--origam-timeline---track-width", "defaultValue": "24px", "descriptionKey": "components.timeline_item.css_vars.track_width", "descriptionFallback": "Fixed width of the track column (holds dot + connector)."}, {"name": "--origam-timeline---dot-size", "defaultValue": "12px", "descriptionKey": "components.timeline_item.css_vars.dot_size", "descriptionFallback": "Diameter of the timeline dot circle."}, {"name": "--origam-timeline-item---dot-bg", "defaultValue": "var(--origam-timeline---dot-bg)", "descriptionKey": "components.timeline_item.css_vars.dot_bg", "descriptionFallback": "Per-item dot background color. Set via intent-resolved CSS custom property on the dot element style."}, {"name": "--origam-timeline-item---dot-color", "defaultValue": "var(--origam-timeline---dot-color)", "descriptionKey": "components.timeline_item.css_vars.dot_color", "descriptionFallback": "Per-item dot foreground (icon) color. Set via intent-resolved CSS custom property."}, {"name": "--origam-timeline---dot-border-width", "defaultValue": "2px", "descriptionKey": "components.timeline_item.css_vars.dot_border_width", "descriptionFallback": "Border width of the dot circle (separates dot from background)."}, {"name": "--origam-timeline---connector-color", "defaultValue": "{color.border.subtle}", "descriptionKey": "components.timeline_item.css_vars.connector_color", "descriptionFallback": "Color of the connector line between dots."}, {"name": "--origam-timeline---connector-thickness", "defaultValue": "1px", "descriptionKey": "components.timeline_item.css_vars.connector_thickness", "descriptionFallback": "Thickness of the connector line."}, {"name": "--origam-timeline---title-font-size", "defaultValue": "0.875rem", "descriptionKey": "components.timeline_item.css_vars.title_font_size", "descriptionFallback": "Font size of the item title text."}, {"name": "--origam-timeline---title-font-weight", "defaultValue": "600", "descriptionKey": "components.timeline_item.css_vars.title_font_weight", "descriptionFallback": "Font weight of the item title text."}, {"name": "--origam-timeline---subtitle-font-size", "defaultValue": "0.75rem", "descriptionKey": "components.timeline_item.css_vars.subtitle_font_size", "descriptionFallback": "Font size of the subtitle and body text."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.timeline_item.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.timeline_item.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.timeline_item.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.timeline_item.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.timeline_item.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.timeline_item.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "text", "prop": "title", "labelKey": "components.timeline_item.playground.title", "defaultValue": "Event title", "labelFallback": "Title"}, {"kind": "text", "prop": "subtitle", "labelKey": "components.timeline_item.playground.subtitle", "defaultValue": "2024-01-10", "labelFallback": "Subtitle"}, {"kind": "text", "prop": "description", "labelKey": "components.timeline_item.playground.description", "defaultValue": "Event description text.", "labelFallback": "Description"}, {"kind": "select", "prop": "intent", "options": [{"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.timeline_item.playground.intent", "defaultValue": "primary", "labelFallback": "Intent"}, {"kind": "select", "prop": "icon", "options": [{"label": "(none)", "value": ""}, {"label": "mdi-check", "value": "mdi-check"}, {"label": "mdi-clock", "value": "mdi-clock"}, {"label": "mdi-alert", "value": "mdi-alert"}, {"label": "mdi-star", "value": "mdi-star"}], "labelKey": "components.timeline_item.playground.icon", "defaultValue": "", "labelFallback": "Icon"}, {"kind": "select", "prop": "side", "options": [{"label": "start", "value": "start"}, {"label": "end", "value": "end"}], "labelKey": "components.timeline_item.playground.side", "defaultValue": "start", "labelFallback": "Side"}], "defaultSlotContent": ""}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('2c6776a3-886a-4560-af17-17753036e655', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'component', 'title', 'Title', 'Data Display', NULL, 'mdi-format-header-1', 'components.catalog.title.description', 'Polymorphic heading with configurable tag (h1–h6 or any block element) and density-driven typography tokens.', NULL, NULL, 'origam-title', NULL, 'packages/ds/src/components/Title/OrigamTitle.vue', 'origam', NULL, NULL, '/stories/?story=components-title--design', '/docs/components/Title/OrigamTitle.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.title.a11y.heading_level_note", "noteFallback": "Always choose a tag value that fits the document heading hierarchy (h1 for the page title, h2 for sections, etc.). Skipping heading levels (h1 → h3) impairs screen reader navigation."}, {"noteKey": "components.title.a11y.vcontrast_note", "noteFallback": "The vContrast directive automatically adjusts the text color for sufficient contrast against the background. Do not suppress it without verifying WCAG AA compliance manually."}, {"noteKey": "components.title.a11y.color_note", "noteFallback": "When setting color or bgColor, verify that the contrast ratio meets WCAG 2.1 AA (≥ 4.5:1 for normal text). The vContrast directive assists but does not guarantee compliance for every color combination."}], "roles": ["heading (native HTML)"], "keyboard": []}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__text---primary)", "tokenPath": "--origam-title---color", "descriptionKey": "components.title.tokens.color", "descriptionFallback": "Default heading text color."}, {"type": "fontFamily", "value": "var(--origam-font__family---sans)", "tokenPath": "--origam-title---font-family", "descriptionKey": "components.title.tokens.font_family", "descriptionFallback": "Heading font family."}, {"type": "fontWeight", "value": "var(--origam-font__weight---semibold)", "tokenPath": "--origam-title---font-weight", "descriptionKey": "components.title.tokens.font_weight", "descriptionFallback": "Heading font weight."}, {"type": "dimension", "value": "var(--origam-font__size---xl)", "tokenPath": "--origam-title---font-size-md", "descriptionKey": "components.title.tokens.font_size_md", "descriptionFallback": "Font size for density=default."}, {"type": "dimension", "value": "var(--origam-font__size---3xl)", "tokenPath": "--origam-title---font-size-xl", "descriptionKey": "components.title.tokens.font_size_xl", "descriptionFallback": "Font size for density=comfortable."}, {"type": "dimension", "value": "var(--origam-font__size---md)", "tokenPath": "--origam-title---font-size-xs", "descriptionKey": "components.title.tokens.font_size_xs", "descriptionFallback": "Font size for density=compact."}, {"type": "dimension", "value": "var(--origam-font__letterSpacing---tight)", "tokenPath": "--origam-title---letter-spacing", "descriptionKey": "components.title.tokens.letter_spacing", "descriptionFallback": "Heading letter-spacing."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"600\" height=\"160\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"28\" y=\"40\" width=\"544\" height=\"80\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"52\" y=\"90\" font-size=\"28\" fill=\"var(--origam-color__text---primary, #1a1a2e)\" font-weight=\"700\" font-family=\"sans-serif\">Page Title</text>\n  <circle cx=\"36\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"52.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <line x1=\"46\" y1=\"40\" x2=\"80\" y2=\"22\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"84\" y=\"22\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-title (tag=h1 default)</text>\n  <text x=\"300\" y=\"140\" font-size=\"8\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">density: compact → xs · default → md · comfortable → xl</text>\n", "code": "<!-- root: polymorphic heading, h1 by default -->\n<component\n  :is=\"tag\"\n  :id=\"id\"\n  v-contrast\n  class=\"origam-title\"\n  :class=\"[densityClasses, colorClasses, borderClasses, paddingClasses, marginClasses]\"\n  :style=\"[colorStyles, borderStyles, paddingStyles, marginStyles]\"\n>\n  <slot v-if=\"hasContent\" name=\"default\">{{ text }}</slot>\n</component>", "legend": [{"cls": ".origam-title", "num": 1, "descriptionKey": "components.title.anatomy.root", "descriptionFallback": "Root element. Renders as <h1> by default (overridable via tag prop). Uses vContrast directive for automatic text color contrast. Three density modifier classes control font size: --density-compact, --density-default, --density-comfortable."}], "classes": [{"cls": "origam-title", "descriptionKey": "components.title.anatomy.root", "descriptionFallback": "Root element. font-family, font-weight, letter-spacing, line-height come from tokens."}, {"cls": "origam-title--density-compact", "descriptionKey": "components.title.anatomy.density_compact", "descriptionFallback": "Applied when density=\"compact\". font-size: var(--origam-title---font-size-xs)."}, {"cls": "origam-title--density-default", "descriptionKey": "components.title.anatomy.density_default", "descriptionFallback": "Applied when density=\"default\". font-size: var(--origam-title---font-size-md)."}, {"cls": "origam-title--density-comfortable", "descriptionKey": "components.title.anatomy.density_comfortable", "descriptionFallback": "Applied when density=\"comfortable\". font-size: var(--origam-title---font-size-xl)."}], "svgDesc": "Schematic of the Title component — single root element with density class.", "svgTitle": "Anatomy of OrigamTitle", "rootClass": "origam-title", "figcaption": "Anatomy of <code>&lt;origam-title&gt;</code> — a single polymorphic element ①. Font size is controlled by <code>density</code> via three token tiers.", "svgViewBox": "0 0 600 160"}, "cssVars": [{"name": "--origam-title---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.title.css_vars.color", "descriptionFallback": "Default heading text color."}, {"name": "--origam-title---font-family", "defaultValue": "{font.family.sans}", "descriptionKey": "components.title.css_vars.font_family", "descriptionFallback": "Heading font family."}, {"name": "--origam-title---font-weight", "defaultValue": "{font.weight.semibold}", "descriptionKey": "components.title.css_vars.font_weight", "descriptionFallback": "Heading font weight."}, {"name": "--origam-title---letter-spacing", "defaultValue": "{font.letterSpacing.tight}", "descriptionKey": "components.title.css_vars.letter_spacing", "descriptionFallback": "Heading letter-spacing."}, {"name": "--origam-title---line-height", "defaultValue": "{font.lineHeight.tight}", "descriptionKey": "components.title.css_vars.line_height", "descriptionFallback": "Heading line-height."}, {"name": "--origam-title---font-size-xs", "defaultValue": "{font.size.md}", "descriptionKey": "components.title.css_vars.font_size_xs", "descriptionFallback": "Font size for density=\"compact\"."}, {"name": "--origam-title---font-size-md", "defaultValue": "{font.size.xl}", "descriptionKey": "components.title.