INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('cc77ff55-1227-41c7-883f-99f18896fc32', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'composable', 'use-router', 'useRouter', NULL, 'Commons', 'mdi-routes', '', 'Thin wrappers around Vue Router that expose the current route and router instance from the Vue component instance rather than via direct vue-router import. Also provides useLink (a link-resolution helper used by all clickable Origam components) and useBackButton (navigation guard for hardware/browser back button interception).', NULL, '// Returns the active route as a reactive ref
