INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('9a401349-1cc9-4947-af58-c1107ae9e444', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'composable', 'use-textarea-rich', 'useTextareaRich', NULL, 'Textarea', 'mdi-format-text', '', 'Owns the runtime contract of the rich-text textarea (OrigamTextareaRich). Mounts a contenteditable host, applies formatting commands via document.execCommand, tracks active formatting state at the caret for toolbar UI feedback, and sanitises every emit so the consumer v-model never carries XSS payloads. Registers Cmd/Ctrl keyboard shortcuts for the common formatting commands.', NULL, 'function useTextareaRich(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('5dcdea00-0876-4915-a337-2f2340282639', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'composable', 'use-text-color', 'useTextColor', NULL, 'Commons', 'mdi-format-color-text', '', 'Foreground-only color helper. Resolves the `color` prop to a utility class (`origam--color-*`) for tokenised intents, or to an inline `color:` declaration for raw CSS values and gradients.', NULL, 'function useTextColor<T extends Record<K, TColor>, K extends string>(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('4d6e6f39-7944-4304-beea-42d85cd5bce7', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'composable', 'use-theme', 'useTheme', NULL, 'Theme', 'mdi-theme-light-dark', '', 'Module-level singleton managing the brand theme axis (data-theme attribute) and the color-mode axis (data-mode attribute). Persists both axes to localStorage and reacts to prefers-color-scheme. Every call to useTheme() shares the same refs.', NULL, 'function useTheme(): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('a5647ffe-c14f-4954-a73d-48be1c5fbd98', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'composable', 'use-throttle', 'useThrottleFn', NULL, 'Commons', 'mdi-timer-outline', '', 'Wraps a function so it executes at most once per wait milliseconds. The first call fires immediately; subsequent calls within the wait window are silently discarded. After the window expires the next call fires again immediately. Designed for scroll, resize, and pointer-move handlers where firing on every frame would be prohibitively expensive.', NULL, 'function useThrottleFn<T extends any[], R = void>(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('3564c14a-ba8e-48cf-9e51-0a58548a38dc', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'composable', 'use-toggle-scope', 'useToggleScope', NULL, 'Commons', 'mdi-toggle-switch-outline', '', 'Conditionally activates a Vue effectScope driven by a reactive boolean source. When the source turns true the scope starts (running the provided callback inside it); when it turns false the scope is stopped and discarded. The scope is also stopped on parent scope dispose.', NULL, 'function useToggleScope(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('ae769824-6f04-4793-b72a-98b3ed262700', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'composable', 'use-touch', 'useTouch', NULL, 'Commons', 'mdi-gesture-swipe', '', 'Enables swipe-to-open / swipe-to-close gesture handling for drawer-like components. Listens to touchstart / touchmove / touchend on window, computes drag progress relative to a positioned edge (left, right, top, bottom), and resolves the gesture via velocity-based fling detection using useVelocity.', NULL, 'function useTouch(options: {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('d6d349fc-ad84-4fbf-87f5-dbabff6c0db9', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'composable', 'use-transition', 'useTransition', NULL, 'Transition', 'mdi-transition', '', 'Family of three composables (useTransition, useCssTransition, useWindowTransition) that resolve a transition name from ITransitionProps and wire optional lifecycle hooks. useCssTransition handles leaveAbsolute / hideOnLeave helpers. useWindowTransition coordinates height animations for window-based transitions in stepper or tab containers.', NULL, 'function useTransition(
