INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('d0cf1472-0bba-496a-a709-49523c89975a', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'composable', 'use-waveform', 'useWaveform', NULL, 'Audio', 'mdi-waveform', '', 'Headless waveform composable. Decodes the audio file referenced by a reactive URL ref, downsamples its channel-0 amplitude data into a configurable number of normalised peaks (default 200), and exposes the result as a reactive array. SSR-safe. Recomputes automatically when the source URL changes. Errors are captured reactively instead of thrown.', NULL, 'function useWaveform(
