INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('bc686dfb-dccf-4f17-bf70-b24dfc43af54', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'interface', 'i-chart-sankey-node', 'IChartSankeyNode', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_sankey_node.description', 'Internal node descriptor produced by the Sankey layout engine. All coordinates are in SVG-user-unit space. Nodes are inferred from the union of all from and to strings in IChartSankeyDatum; column is assigned by topological depth (Kahn''s algorithm).', 'export interface IChartSankeyNode {
