INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ad8bd2d4-b0cd-4567-9521-2bf1dc019cef', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '8fd41c9c-69b0-4597-945f-e58dcdeeb555', 'props', 'IActivatorProps', true, NULL, '', 'Props controlling how the overlay is triggered. Includes activator selector/element, open-on strategy (click, hover, focus, context-menu), close-on-content-click, delay settings inherited from IDelayProps, and an optional target override.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('78747417-cd7d-48c2-9b2e-a71309918ee7', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '8fd41c9c-69b0-4597-945f-e58dcdeeb555', 'isActive', 'Ref<boolean>', true, NULL, '', 'Reactive flag representing the open/closed state of the overlay. useActivator reads and writes this ref to toggle the overlay on user interaction.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d31d21de-bdf5-4dd1-a168-c77de3025756', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '8fd41c9c-69b0-4597-945f-e58dcdeeb555', 'isTop', 'Ref<boolean>', true, NULL, '', 'Reactive flag set by the overlay stack manager. When true, this overlay is the topmost one; when it becomes false while hover/focus-triggered, the composable auto-closes the overlay.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f743f0e1-e094-48c2-9af7-e4ff44996ac4', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'a82eb42d-7eb4-418c-adf4-ee1be8679c2d', 'props', 'IActiveProps & Record<string, any>', true, NULL, '', 'Component props. Reads `props[prop]` (default: `props.active`).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('396e422b-9868-4a0f-a69d-5f7104e6c92f', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'a82eb42d-7eb4-418c-adf4-ee1be8679c2d', 'prop', 'string', false, '''active''', '', 'The prop key to read for the active value. Use "modelValue" for components with a v-model binding.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0069fb2f-a948-4055-b073-84cabdb92680', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'a82eb42d-7eb4-418c-adf4-ee1be8679c2d', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name prefix for the `{name}--active` class.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b8cce40d-7d7f-41c3-898b-597aa20b7439', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'cd449d3c-83f1-4a01-a7c0-9a4a5d91ce92', 'props', 'IAdjacentProps', true, NULL, '', 'Props carrying prependIcon, appendIcon, prependAvatar, and appendAvatar values. The composable reads these to determine whether the outer prepend/append regions should render.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9cf6857c-4950-49ae-8cdc-1e59a1ebae14', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'cd449d3c-83f1-4a01-a7c0-9a4a5d91ce92', 'prependIcon', 'Ref | ComputedRef', false, NULL, '', 'Optional reactive icon override for the prepend slot. When provided, takes precedence over props.prependIcon, enabling status-aware icon swapping without prop mutation.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6a169be0-cd4c-41f8-a537-4c63d0d3cc36', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'cd449d3c-83f1-4a01-a7c0-9a4a5d91ce92', 'appendIcon', 'Ref | ComputedRef', false, NULL, '', 'Optional reactive icon override for the append slot. Same semantics as prependIcon but for the trailing position.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2615a2b9-427d-4600-a39e-0b7cf6e35bc9', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'ca830d25-cb7a-4ece-bc69-10e8fa629b2e', 'props', 'IAdjacentInnerProps', true, NULL, NULL, NULL, 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('905f6676-3297-442d-ba68-8a9e0b06b231', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'f519b0b5-c0c1-423a-9bea-53597dd33cc9', 'props', '{ aspectRatio?: string | number }', true, NULL, '', 'Object carrying an optional aspectRatio value. Accepts a numeric ratio (1.777 for 16:9), a division expression string ("16/9"), or is left undefined to use window.innerWidth / window.innerHeight as the ratio.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('57fa6cf7-04c9-41e0-a156-11ec4d9c5dd2', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '921fb89b-a335-4096-b2d8-53e7d26d4aab', 'props', 'IUseAudioProps', true, NULL, '', 'Props object with audio (URL of the audio source) and playAudio (boolean flag). When playAudio changes to true the composable calls onPlay(); when it changes to false it calls onStop(). When audio changes, wasPlayed and isPlaying are reset.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0d6eb311-56b2-44b8-a80d-dfb8b3e509c0', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '4e28f5bb-c853-46a1-8b6d-7bc99ff2cb39', 'options', 'IUseOrigamAudioPlayerOptions', false, '{}', '', 'Optional configuration. Accepts `audioRef` (bring your own ref), `autoplay`, `muted`, `loop`, and `preload`. All fields are optional.', 0, false, NULL, NULL);
