INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9f064784-9088-43a2-8ad6-3c9c0b1d38d7', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '88c1faab-c97a-4762-9716-7e889bc797dd', 'name', 'K', false, NULL, '', 'The key to read from the props object. Typically "bgColor". Omit when passing a plain Ref.', 1, false, NULL, NULL);
