INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('fec780b3-3123-45a1-912a-835143cb7dda', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'a372d08e-2538-43dc-89ab-13128922a523', 'options', 'IUseCalendarOptions', true, NULL, '', 'Configuration thunks. All fields are getter functions so the composable reacts to reactive sources without re-instantiation. Includes events, view, currentDate, firstDayOfWeek, slotDuration, dayStartHour, dayEndHour, and optional minDate/maxDate/locale.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('29c12a53-6061-47fb-8b70-8aa807ba09d2', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'a372d08e-2538-43dc-89ab-13128922a523', 'setView', '(view: TCalendarView) => void', false, NULL, '', 'Optional callback invoked by the returned setView proxy. Bind to a v-model:view setter to keep the parent state in sync when the calendar switches views.', 1, false, NULL, NULL);
