INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ce352b21-0a0f-4445-9e6e-32b599e68191', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '98ad706f-aca6-44b7-9e3a-c2b5fd69de85', 'callback', 'ResizeObserverCallback', false, NULL, '', 'Optional raw ResizeObserver callback. Receives the full entries array and the observer instance. Called on every resize event before contentRect is updated.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2be51031-a444-4363-ad43-0bb428564cc4', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '98ad706f-aca6-44b7-9e3a-c2b5fd69de85', 'box', '''content'' | ''border''', false, '''content''', '', 'Which box model dimension to capture. "content" uses entries[0].contentRect; "border" calls getBoundingClientRect() on the element for border-box dimensions including padding and border.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c2a39ae8-8457-4682-ab58-dac09d6e509c', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'e770ab97-ad76-402b-afe9-d579f9db33fa', 'props', 'IRoundedProps | Ref<boolean | number | string | TRounded | null | undefined>', true, NULL, '', 'Either the component props object or a plain Ref. Reads the `rounded` value.', 0, false, NULL, NULL);
