INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1845a2c7-9518-40cf-b690-e4a9dcad5b8e', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'd1f325a3-2f75-4462-9521-147ca9e5ca72', 'link', 'IUseLink', true, NULL, '', 'The link object returned by useRouter/useLink. Exposes isLink (whether an href/to prop is present) and isActive (whether the current route matches the link target). Watched by the composable to trigger selection.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d58b5765-78a9-4c1b-84a8-729dc69c668a', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'd1f325a3-2f75-4462-9521-147ca9e5ca72', 'select', '(value: boolean, e?: Event) => void', false, NULL, '', 'The group selection callback injected by useGroup. When the link becomes active, this is called with value=true on the next tick. When undefined, the composable becomes a no-op.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d573f45f-bd81-4233-9fe1-c2d4e96bbd42', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'a724f87f-dcdf-450f-9ba8-ba32aa64b369', 'options', 'ISheetSwipeOptions', true, NULL, '', 'Configuration object. Includes el (sheet root element ref), handle (drag handle element ref), snapPoints (reactive array of TSheetSnapPoint), defaultSnap (initial snap id), disabled (Ref<boolean> to suspend gesture), and persistent (Ref<boolean> to block the closed snap).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0fc642df-f797-43ff-89f6-4465f4eb5d32', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '432e4648-4a50-400a-a0a5-b582c67539bc', 'props', 'ISizeProps', true, NULL, '', 'Component props extending ISizeProps. Reads the `size` value.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('511473b3-9fae-459d-8528-1fb7083b6aa7', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '432e4648-4a50-400a-a0a5-b582c67539bc', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name prefix for the `{name}--size-{value}` class.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f658544e-421b-40a6-a0af-cc232834d4a9', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'fb72b5fd-1060-40ad-ac19-08174fd37df6', 'props', 'ISliderFieldProps', true, NULL, '', 'Component props. Reads min (default 0), max (default 100), and step (default 0 = no stepping). All three accept string or number — they are parsed with parseFloat internally.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f2a4ff64-4d2b-44a9-a971-502fb6741bd4', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '0d2215ba-ddd2-45ea-8e4a-61f32856570c', 'milliseconds', 'number', true, NULL, '', 'Total countdown duration in milliseconds. This is the initial value of time and the value it resets to on reset().', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1c37249b-5347-49f7-b196-5c551b5bebe1', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '2276ed4f-4922-4ab0-a2ad-e39ad43482c2', 'options', 'IUseSnackbarGroupOptions', false, '{}', '', 'Optional configuration. id (string) namespaces the stack so multiple independent stacks can coexist on the same page (default: SNACKBAR_GROUP_DEFAULT_ID). max (number) caps the stack size with FIFO eviction. defaultDuration (ms) is the fallback auto-dismiss delay for items that omit their own (default: 5000 ms).', 0, false, NULL, NULL);
