INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('107a5fa5-7f82-4087-9275-2099a6441dbc', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '0788ceed-6d53-47d4-8301-9c42f251b892', 'isActive', 'Readonly<Ref<boolean>>', true, NULL, '', 'Reactive open/closed state. When it flips to true, useStack registers the component in the global stack and computes a new z-index. When false, the entry is removed and z-index is released.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('278a95b8-5cfe-48b9-9a8a-717519e50cac', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '0788ceed-6d53-47d4-8301-9c42f251b892', 'zIndex', 'Readonly<Ref<string | number>>', true, NULL, '', 'Base z-index to start from when no other overlays are open. Typically comes from the component props (e.g. zIndex="200").', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('333a1f8d-be6e-4d4e-b790-ba8a80adb650', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '0788ceed-6d53-47d4-8301-9c42f251b892', 'disableGlobalStack', 'Readonly<Ref<boolean>>', true, NULL, '', 'When true, skips registration in GLOBAL_STACK. Use for overlays that manage their own z-index independently (e.g. nested teleport roots) and should not compete with the global stacking order.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('52b23794-a4c0-40c4-8ff8-7317a37b2fbf', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'd78ca017-6285-49ac-afbc-f5955f27f38d', 'props', 'TStateEffectProps', true, NULL, '', 'Component props implementing all eight axes: IColorProps & IBgColorProps & IBorderProps & IRoundedProps & IElevationProps & IPaddingProps & IMarginProps & { gap? }. Also reads props.status when present to force the matching semantic intent (overrides color/bgColor).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('41fbacae-f95f-4a11-b3a4-81e2dcca0deb', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'd78ca017-6285-49ac-afbc-f5955f27f38d', 'isHover', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'Reactive hover state from useHover. When true, the composable applies the override values from hoverState for each axis.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('17eac108-bd6a-4426-8d82-c987d8bbcae6', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'ae769824-6f04-4793-b72a-98b3ed262700', 'touchless', 'Ref<boolean>', true, NULL, '', 'When true all touch handling is disabled. Lets the consumer disable swipe gestures without unmounting the composable.', 3, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6df477df-d579-4dce-af1a-b95697f9bfc8', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'd78ca017-6285-49ac-afbc-f5955f27f38d', 'isActive', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'Reactive active/selected state from useActive. When true (and isHover is false), override values from activeState are applied. Hover takes priority when both are engaged simultaneously.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ff88e5a8-7388-42ba-b89d-7af6c8dd89d4', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'd78ca017-6285-49ac-afbc-f5955f27f38d', 'hoverState', 'ComputedRef<IHoverState | undefined>', false, 'computed(() => undefined)', '', 'State config object from useHover. Contains per-axis override values (color, bgColor, border, rounded, elevation, padding, margin, gap) to apply while hovered.', 3, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0dc949e6-b0bc-45cb-a65c-c0b4519e9958', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'd78ca017-6285-49ac-afbc-f5955f27f38d', 'activeState', 'ComputedRef<IActiveState | undefined>', false, 'computed(() => undefined)', '', 'State config object from useActive. Same shape as IHoverState — per-axis overrides applied while the item is selected/active.', 4, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('62459c2a-8a8b-49f0-9371-4e5bc7fb94f4', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'd78ca017-6285-49ac-afbc-f5955f27f38d', 'isDisabled', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'When true, colorClasses is emptied (utility classes suppressed) so the disabled opacity veil is not overridden by a tokenised background.', 5, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9727c7a9-b7db-4b2b-a167-a009b3abac98', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'd78ca017-6285-49ac-afbc-f5955f27f38d', 'flat', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'When true, elevationClasses and elevationStyles resolve to empty. Bridges the flat prop of Btn / Card without requiring a separate useElevation call.', 6, false, NULL, NULL);
