INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8f0f2f41-c800-4d11-a701-8dcead3bb823', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '3564c14a-ba8e-48cf-9e51-0a58548a38dc', 'fn', '(reset: () => void) => void', true, NULL, '', 'Callback run inside the new effectScope. Receives a `reset()` function that can be called from inside the scope to stop the current scope and immediately restart it — useful for subscriptions that need to re-initialise when an inner condition changes.', 1, false, NULL, NULL);
