INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e642d048-f69e-46b7-bcb6-e3d16d6dbf4f', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'd3574da4-bed0-441c-8a54-c3b92c925122', 'items', 'Ref<readonly T[]>', true, NULL, '', 'The full dataset ref. The composable slices this array to produce `computedItems`. Changing the ref triggers an offset recalculation.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('28bf6729-87f4-4943-b3c2-fbc6077fee60', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '518a2716-9fca-4061-a4cf-2bb7fb16d2db', 'props', 'Props', true, NULL, '', 'The component props object returned by defineProps. The composable reads `props[prop]` and inspects `vm.vnode.props` to detect whether the listener is wired.', 0, false, NULL, NULL);
