INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('34349528-3bca-4cd9-8a66-5999764cec64', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'd0cf1472-0bba-496a-a709-49523c89975a', 'srcRef', 'Ref<string | undefined | null>', true, NULL, '', 'Reactive reference to the audio file URL. The composable watches this ref and re-triggers computation whenever the value changes. null / undefined clears the peaks array.', 0, false, NULL, NULL);
