INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('efe66d04-8dc4-4bac-b5c1-521c0dd00bd0', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:54.636531+00', '9a67ee29-b9a9-49ee-a769-ead6f46fafea', 'lineNumbers', 'boolean', '', 'primitive', NULL, false, 'false', 'components.code.props.line_numbers.description', 'Shows a left gutter with line numbers. Pure CSS counter — no JS layout work.', 2, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5c693ade-a23f-4d4f-81d8-7921cf254fdc', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:54.636531+00', '9a67ee29-b9a9-49ee-a769-ead6f46fafea', 'highlightLines', 'number[] | string | null', '', 'primitive', NULL, false, 'null', 'components.code.props.highlight_lines.description', 'Lines to highlight. Accepts a 1-based array ([2, 5, 6]) or a range string (''2,5-7''). Null/empty disables.', 3, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('eb0c7b4e-43ab-4324-a67d-0c6c3c8ce418', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:54.636531+00', '9a67ee29-b9a9-49ee-a769-ead6f46fafea', 'copyable', 'boolean', '', 'primitive', NULL, false, 'true', 'components.code.props.copyable.description', 'Shows the copy-to-clipboard button. True by default — most code blocks benefit from it.', 4, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ef2eb093-88eb-4a9e-9fd3-f513c48b620b', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:54.636531+00', '9a67ee29-b9a9-49ee-a769-ead6f46fafea', 'format', 'boolean', '', 'primitive', NULL, false, 'false', 'components.code.props.format.description', 'Auto-format the code before highlighting. Reserved — currently a no-op that warns in dev mode. Prettier is not bundled at runtime to keep the tarball small.', 5, false, NULL, NULL);
