INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c699de2c-5f7b-463a-aa62-b87f6f4d3748', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'a724f87f-dcdf-450f-9ba8-ba32aa64b369', 'currentSnap', 'Ref<TSheetSnapId>', '', 'The id of the currently active snap point. Writable — programmatically call snapTo() or assign directly. Kept in sync with options.defaultSnap via a watcher.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0e4628c4-c226-44b5-85c5-a82869737a27', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'a724f87f-dcdf-450f-9ba8-ba32aa64b369', 'dragOffset', 'ShallowRef<number>', '', 'Live pixel offset from the baseline snap height during an active drag. Positive = sheet growing (finger moving up). Resets to 0 on pointer release. Bind to a CSS translateY to achieve 1:1 finger tracking.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9f13777e-ad55-49ea-a9b3-c04b2dd30dda', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'a724f87f-dcdf-450f-9ba8-ba32aa64b369', 'isDragging', 'ShallowRef<boolean>', '', 'True while a pointer is captured by the handle. Use it to suppress the sheet transition (transition: none) so the user sees immediate 1:1 tracking instead of the animated snap.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f2cc4cb4-1da4-4f93-97b0-c10be3f6a2f6', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'a724f87f-dcdf-450f-9ba8-ba32aa64b369', 'snapTo', '(id: TSheetSnapId) => void', '', 'Programmatically move to a named snap point. Respects the persistent constraint (cannot snap to closed when persistent=true). Resets dragOffset to 0.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8783eefc-6429-4b16-a793-d229d764cbda', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'a724f87f-dcdf-450f-9ba8-ba32aa64b369', 'dismiss', '() => void', '', 'Convenience wrapper for snapTo("closed"). Blocked when persistent=true (falls back to the lowest non-zero snap).', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3878f85e-75e3-4bf5-b35e-4157223e5cd1', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'a724f87f-dcdf-450f-9ba8-ba32aa64b369', 'currentSnapHeight', 'ComputedRef<number>', '', 'Resolved pixel height of the current snap point. SSR-safe (returns 0 when window is absent). Used to compute the sheet height style: currentSnapHeight + dragOffset.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8ef7a740-4e5a-49b2-a051-c126af85fa42', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '432e4648-4a50-400a-a0a5-b582c67539bc', 'sizeClasses', 'ComputedRef<string[]>', '', 'Component-local BEM modifier class (e.g. "origam-btn--size-small") plus the typographic utility class (e.g. "origam--text-sm") bridging the legacy to modern taxonomy.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('eceda762-a422-4ff4-974c-b1c4ad9fe082', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '432e4648-4a50-400a-a0a5-b582c67539bc', 'sizeStyles', 'ComputedRef<string[]>', '', 'Inline width and height declarations for custom numeric or CSS-length sizes (when the value is not a named preset).', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c2aa55f0-fb8b-476c-9780-a3d9449f648f', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'fb72b5fd-1060-40ad-ac19-08174fd37df6', 'min', 'ComputedRef<number>', '', 'Parsed minimum value. Defaults to 0 when props.min is undefined or null.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ccf22281-afdb-4342-941b-ebf7d60fdc02', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'fb72b5fd-1060-40ad-ac19-08174fd37df6', 'max', 'ComputedRef<number>', '', 'Parsed maximum value. Defaults to 100 when props.max is undefined or null.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('79baed1b-e1ba-4e9b-b5d8-1d245ad3dc70', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'fb72b5fd-1060-40ad-ac19-08174fd37df6', 'step', 'ComputedRef<number>', '', 'Parsed step value. 0 means no stepping (any value between min and max is valid). Positive values define the snap grid.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d7efb2dc-9dc1-41cc-82fb-5923035730d8', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'fb72b5fd-1060-40ad-ac19-08174fd37df6', 'decimals', 'ComputedRef<number>', '', 'Number of decimal places to preserve in roundValue output. Derived from max(getDecimals(step), getDecimals(min)) to match the precision implied by the step grid.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b0c9191d-1418-4679-847a-582d4c80e767', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'fb72b5fd-1060-40ad-ac19-08174fd37df6', 'roundValue', '(value: string | number) => number', '', 'Snap a raw value to the nearest valid step, clamped to [min, max]. Handles the min-offset edge case so that a step=5 min=3 grid snaps to 3, 8, 13, … rather than 0, 5, 10, ….', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('bbd12880-2b35-43d2-be00-ed6139d27bff', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '0d2215ba-ddd2-45ea-8e4a-61f32856570c', 'time', 'ShallowRef<number>', '', 'Remaining milliseconds. Starts at the initial milliseconds value, decrements on each tick, and bottoms out at 0. Bind to a progress bar width to visualise the countdown.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8f1f1bce-c536-476f-8a85-612bce7c7eb0', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '0d2215ba-ddd2-45ea-8e4a-61f32856570c', 'clear', '() => void', '', 'Stops the interval without resetting time. Use to pause the countdown (e.g. while the user is hovering the snackbar).', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('02232f83-ef3e-42e7-8cfd-ad8c98b45025', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '0d2215ba-ddd2-45ea-8e4a-61f32856570c', 'reset', '() => void', '', 'Clears the interval and resets time to the initial milliseconds value on the next tick. Use when the snackbar content changes and the countdown should restart.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8ff43bc5-8b48-4cdc-8ca9-a7846ba0ff75', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '0d2215ba-ddd2-45ea-8e4a-61f32856570c', 'start', '(el?: HTMLElement) => void', '', 'Start (or resume) the countdown. Reads the CSS transitionDuration of el to synchronise tick frequency with the progress bar animation. Falls back to 200 ms when no element is provided or no transition is set. Clears any existing interval before starting.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0d06c78b-443c-4d65-a22a-42808c658889', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '2276ed4f-4922-4ab0-a2ad-e39ad43482c2', 'items', 'Readonly<Ref<ReadonlyArray<ISnackbarGroupItem>>>', '', 'Reactive read-only snapshot of the current stack. Mutate only through notify / dismiss / dismissAll — direct writes are blocked at the TypeScript level.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c0b477b9-5624-487b-9632-d18aa1f5ddaa', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '2276ed4f-4922-4ab0-a2ad-e39ad43482c2', 'notify', '(opts: ISnackbarGroupItemOptions) => string', '', 'Push a new item onto the stack. Accepts ISnackbarGroupItemOptions (message, variant, icon, duration, onDismiss callback…). Returns the generated item id so the caller can dismiss it early.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6e8a5106-369f-481d-bafc-2903e33b2d99', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '2276ed4f-4922-4ab0-a2ad-e39ad43482c2', 'dismiss', '(itemId: string) => void', '', 'Remove the item with the given id from the stack, cancel its auto-dismiss timer, and invoke its onDismiss callback if any.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('fbb8aa90-6675-44df-aa85-35b3c5e9aa8e', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '2276ed4f-4922-4ab0-a2ad-e39ad43482c2', 'dismissAll', '() => void', '', 'Dismiss every item in the stack in one call. Iterates a snapshot of the ids so mid-loop mutations are safe.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('eca0b5c9-3d91-426c-ab9e-9f1bdce0ca0c', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '85a360e0-d3e4-4be5-9fbd-3fbad4d13db8', 'sortBy', 'Ref<Array<IDataTableSortItem>>', '', 'Reactive array of active sort descriptors, each with a key (column key) and an order (asc | desc). Driven by useVModel against the host table props.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('69cf7f9a-775d-49df-b0a9-5dfbe4867c71', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '85a360e0-d3e4-4be5-9fbd-3fbad4d13db8', 'toggleSort', '(column: IInternalDataTableHeader) => void', '', 'Cycle the sort state for a column: none → asc → desc → none (or asc when mustSort=true). Respects multiSort — when false, replaces the entire sortBy array with a single entry.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('87ac1418-f8af-4243-8cca-571d38167e66', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '85a360e0-d3e4-4be5-9fbd-3fbad4d13db8', 'isSorted', '(column: IInternalDataTableHeader) => boolean', '', 'Returns true when the column has an active sort entry in sortBy. Used by header cells to show the sort icon.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('45caa42d-e312-4e91-bb6a-2ade8c90132b', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '436b1775-2780-4549-bc97-637bd5b3c180', 'ssrBootStyles', 'ComputedRef<CSSProperties | []>', '', 'An object `{ transition: "none !important" }` when the component has not yet booted, or an empty array after the first animation frame. Spread onto the root element via :style to suppress hydration-flash transitions.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9b5a6d8f-fc32-4378-ae41-6de79f555f53', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '436b1775-2780-4549-bc97-637bd5b3c180', 'isBooted', 'Readonly<ShallowRef<boolean>>', '', 'False on the server and during the first rAF after mount, true thereafter. Useful as a guard before running DOM-dependent logic that assumes the component is fully hydrated.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('695e86ca-69bd-4cb8-9648-5d529859a95b', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'b0779ce0-182c-4ee8-b7a5-5eafa8fe2264', NULL, 'number', 'utils.detail.apc_acontrast.returns', 'Signed APCA contrast value. Absolute value >= 45 is the recommended minimum for body text.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('178f7074-d345-4db7-a866-9f526ab85621', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '0788ceed-6d53-47d4-8301-9c42f251b892', 'globalTop', 'Readonly<ShallowRef<boolean>>', '', 'True when this component is the last entry in GLOBAL_STACK (topmost overlay on the page). Updated asynchronously via setTimeout to avoid synchronous circular reads during stack registration.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d32f9d34-c8f2-4db1-ba40-bffa8a9cd0e1', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '0788ceed-6d53-47d4-8301-9c42f251b892', 'localTop', 'ComputedRef<boolean>', '', 'True when this overlay has no active child overlays (nothing opened on top of it within its own sub-tree). Used to decide whether clicks on the backdrop should close this overlay.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c16928cf-f487-41c9-ad26-7cb9899549ec', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '0788ceed-6d53-47d4-8301-9c42f251b892', 'stackStyles', 'ComputedRef<{ zIndex: number }>', '', 'Style object containing the computed zIndex. Spread onto the overlay root element so it automatically rises above the previous topmost overlay.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('045a3603-d05f-4793-a6f5-4b0962591eeb', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'd78ca017-6285-49ac-afbc-f5955f27f38d', 'colorClasses / colorStyles', 'ComputedRef<string[]>', '', 'Tokenised intent values emit a utility class (origam--bg-primary); custom CSS colors emit an inline style. Both are empty when disabled/hover/active is true (state-inline path takes over).', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5b09a86c-e0b7-4456-9104-feddcfb39fe2', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'd78ca017-6285-49ac-afbc-f5955f27f38d', 'borderClasses / borderStyles', 'ComputedRef<string[]>', '', 'Delegated to useBorder with a reactive proxy that swaps to hoverState/activeState.border when the state is engaged.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f8e10f81-e962-4503-9ecf-153b49d466a0', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'd78ca017-6285-49ac-afbc-f5955f27f38d', 'roundedClasses / roundedStyles', 'ComputedRef<string[]>', '', 'Delegated to useRounded. State-aware: applies hoverState/activeState.rounded when engaged.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('92d79219-2cdc-4ce3-97de-510a34c47df8', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'd78ca017-6285-49ac-afbc-f5955f27f38d', 'elevationClasses / elevationStyles', 'ComputedRef<string[]>', '', 'Delegated to useElevation. Cleared when flat=true. State-aware via the pickEffective resolver.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1830fbff-39ba-402e-ad8f-c5ba8d2a3750', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'd78ca017-6285-49ac-afbc-f5955f27f38d', 'paddingClasses / paddingStyles', 'ComputedRef<string[]>', '', 'Delegated to usePadding via a reactive getter proxy to preserve dependency tracking across state swaps.', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('939f68da-fe01-4bcd-92b1-925ea70da11f', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'd78ca017-6285-49ac-afbc-f5955f27f38d', 'marginClasses / marginStyles', 'ComputedRef<string[]>', '', 'Delegated to useMargin via a reactive getter proxy.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0436ca58-2437-4b9b-a304-c1acaf230a45', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'd78ca017-6285-49ac-afbc-f5955f27f38d', 'gapClasses / gapStyles', 'ComputedRef<string[]>', '', 'Gap has no dedicated composable. Emits an inline style (gap: Npx or gap: <value>) when a gap override is present. gapClasses is always empty.', 6, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f4823733-18d8-494a-a852-bc918f256e49', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '1f91a59c-65c5-446a-ac72-7286b73ce01e', 'icon', 'ComputedRef<string | undefined>', '', 'Resolved center/replace icon. Returns the status icon when statusIconPosition="replace" and no explicit props.icon was provided, otherwise passes through props.icon.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('282ed1f7-567d-4800-bfdb-9bd21ef9290b', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '1f91a59c-65c5-446a-ac72-7286b73ce01e', 'prependIcon', 'ComputedRef<string | undefined>', '', 'Resolved prepend-slot icon. Injects the status icon when statusIconPosition is prepend or both and props.prependIcon is unset.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2d083559-cab4-4e7c-8b19-71a01e4617ef', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '1f91a59c-65c5-446a-ac72-7286b73ce01e', 'appendIcon', 'ComputedRef<string | undefined>', '', 'Resolved append-slot icon. Injects the status icon when statusIconPosition is append or both and props.appendIcon is unset.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c3365ca0-41b5-4a2a-a9a5-04601e35be89', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '1f91a59c-65c5-446a-ac72-7286b73ce01e', 'statusClasses', 'ComputedRef<string[]>', '', 'Array containing `{name}--{status}` when a status is set, empty otherwise. Bind to the root element for SCSS state selectors.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('85262673-684d-4bf8-9ecc-74438b64d673', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '1f91a59c-65c5-446a-ac72-7286b73ce01e', 'statusIntent', 'ComputedRef<TColor | undefined>', '', 'The resolved TColor intent for the current status (success→success, info→info, warning→warning, error→danger). Undefined when no status is set. Consumed by useStateEffect to force the semantic surface color.', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('fe370178-9ca2-43c9-9b6c-084bbdd5ec89', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'db1cfcb4-8ea9-41ea-a463-2e5076f0f124', 'isStuck', 'ShallowRef<boolean | "top" | "bottom">', '', 'Current stuck state. "top" = anchored at the top of the viewport (sidebar shorter than viewport or scrolled to top), "bottom" = anchored at the bottom edge, true = stuck mid-page (sidebar taller than viewport, user scrolled past the top edge), false = not sticky (isSticky prop is false).', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1c0a2719-7939-4241-aa40-952a85ebea34', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'db1cfcb4-8ea9-41ea-a463-2e5076f0f124', 'stickyStyles', 'ComputedRef<Array<CSSProperties | undefined>>', '', 'Two-element style array to spread on the element. The first resets top/bottom/height when isSticky is enabled. The second applies the computed positional offset: the layoutItem top when not yet stuck, or the scrolled stuckPosition when stuck mid-page or at the bottom.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('09cbca22-2945-4ad8-860e-03d4c6659901', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'e46336d3-95d7-4a78-b741-9c1616cebe4c', 'id', 'ComputedRef<string>', '', 'The element id used as the CSS scope selector (#id). Apply this id to the root element of the component so the injected styles target only this instance.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5cd6870f-05de-4c1c-915a-00c1cacfc9b7', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'e46336d3-95d7-4a78-b741-9c1616cebe4c', 'css', 'ShallowRef<string>', '', 'The current generated CSS string. Reactive — updates whenever the styles ComputedRef changes.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ab6664d9-2f9d-462d-990e-638cd2ee773f', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'e46336d3-95d7-4a78-b741-9c1616cebe4c', 'load / unload', '() => void', '', 'Manually control style tag injection. Normally called automatically on mount / scope dispose. Call load() to re-inject after an explicit unload().', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b1b9c1e4-934e-4174-b98b-4e5fa260afed', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'e46336d3-95d7-4a78-b741-9c1616cebe4c', 'isLoaded', 'Readonly<ShallowRef<boolean>>', '', 'True when the <style> tag is currently present in document.head.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5885b969-3182-4054-9a10-66eff6e579d3', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '496ac428-b08a-4405-a5df-65004d337d18', 'teleportTarget', 'ComputedRef<Element | undefined>', '', 'The resolved .origam-overlay-container element inside the target, or undefined when teleport is disabled (target=true) or the app is running on the server (SSR). Pass directly to <Teleport :to="teleportTarget">.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('422338c2-f8e3-4aab-a809-2f6d63dee957', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '9a401349-1cc9-4947-af58-c1107ae9e444', 'hostRef', 'Ref<HTMLElement | undefined>', '', 'Template ref to assign to the contenteditable element. The composable uses it to read and write innerHTML, attach the selectionchange listener, and focus the element before applying a format command.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d013f5c6-a743-45ec-8604-4eaa90c71e9d', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '9a401349-1cc9-4947-af58-c1107ae9e444', 'active', 'ITextareaRichActiveState', '', 'Reactive object tracking the formatting state at the current caret position. Properties: bold, italic, underline, code, link (booleans), listBullet, listOrdered (booleans), heading (0 | 1 | 2 | 3). Bind to toolbar button :active props.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0c411850-2bab-45ce-909a-0a111689e469', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '9a401349-1cc9-4947-af58-c1107ae9e444', 'format', '(command: TTextareaToolbarCommand, value?: string) => void', '', 'Apply a formatting command. Delegates to document.execCommand for bold, italic, underline, lists, and headings. Handles link creation (value = URL) and inline code toggling (insertHTML). Calls onFormat and onUpdate after every change.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e1c771b0-cef3-4b16-a917-b3826ed06f61', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '9a401349-1cc9-4947-af58-c1107ae9e444', 'isFormatActive', '(command: TTextareaToolbarCommand) => boolean', '', 'Returns whether the given command is active at the current caret position. Reads from the reactive active object — a convenience wrapper for toolbar binding.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f711b459-7a74-4295-a4e0-42b73ce17a7a', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '9a401349-1cc9-4947-af58-c1107ae9e444', 'setValue', '(html: string) => void', '', 'Imperatively update the contenteditable innerHTML with sanitised HTML. No-ops when hostRef is unset or when the content is already identical (avoids cursor jump).', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('450969ee-b53c-42d3-a164-314072fc3059', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '9a401349-1cc9-4947-af58-c1107ae9e444', 'onInput / onKeydown / onPaste', '(event) => void', '', 'Event handlers to bind on the host element. onInput emits sanitised HTML. onKeydown intercepts Cmd/Ctrl+B/I/U/E/K and Cmd+Shift+7/8 for list shortcuts. onPaste strips HTML to sanitised form (or escapes plain text) before inserting.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('871e79bd-3ef2-4e00-982d-b2e592cb4049', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '5dcdea00-0876-4915-a337-2f2340282639', 'textColorClasses', 'ComputedRef<string[]>', '', 'Utility class names (e.g. ["origam--color-primary"]) to bind via :class.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('eb1b6a7b-548b-4979-833c-3cd5904f9648', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '5dcdea00-0876-4915-a337-2f2340282639', 'textColorStyles', 'ComputedRef<string[]>', '', 'Inline CSS declarations (e.g. ["color: #6d28d9"]) to bind via :style. For gradients, includes background-image + background-clip: text.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b561d8f9-1f05-4525-9588-a0db7b03b218', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '4d6e6f39-7944-4304-beea-42d85cd5bce7', 'theme', 'Readonly<Ref<TTheme>>', '', 'The current brand theme value: ''auto'' | ''light'' | ''dark'' | string (custom brand). Read-only reactive ref.', 0, false, NULL, NULL);
