INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('73d1de6d-006c-41d6-8c3b-aab8525c198d', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'd3574da4-bed0-441c-8a54-c3b92c925122', 'containerRef', 'Ref<HTMLElement | undefined>', '', 'Assign to the scrollable container element. The composable reads `scrollTop` from it and listens to `handleScroll` / `handleScrollend`.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('227f6a73-5f6d-4b21-a901-0bd254bad203', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'd3574da4-bed0-441c-8a54-c3b92c925122', 'markerRef', 'Ref<HTMLElement | undefined>', '', 'Assign to a zero-height element at the top of the list content area. Its `offsetTop` is used to compute an offset if there is padding or a header above the virtual list.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b2872d05-5eb3-4864-9613-59273ae4f22a', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'd3574da4-bed0-441c-8a54-c3b92c925122', 'computedItems', 'ComputedRef<Array<{ raw: T; index: number }>>', '', 'The slice of items currently in the render window. Each entry carries the original `raw` item and its absolute `index` in the full list.', 2, false, NULL, NULL);
