INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2c58f6d5-6bad-4b7b-9fe1-66e038d87733', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'd3574da4-bed0-441c-8a54-c3b92c925122', 'paddingBottom', 'ShallowRef<number>', '', 'Pixel padding to add below the last rendered item to preserve the scroll height.', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9bc7285e-30b9-4db6-b9bd-af4255c02935', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'd3574da4-bed0-441c-8a54-c3b92c925122', 'scrollToIndex', '(index: number, options?: Partial<IGoToOptions>) => void', '', 'Programmatically scroll the container to a specific item index. Defers the scroll if the list has not yet measured (first render not complete). Pass `{ duration: 0 }` for instant scroll.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a6550f7d-ac37-47ba-be58-18a02d98f742', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'd3574da4-bed0-441c-8a54-c3b92c925122', 'handleScroll', '() => void', '', 'Bind to the `scroll` event of the container element. Computes scroll velocity and triggers visible-items recalculation.', 6, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4d6b4286-6298-4861-893a-28fee4eef49d', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'd3574da4-bed0-441c-8a54-c3b92c925122', 'handleScrollend', '() => void', '', 'Bind to the `scrollend` event. Resets scroll velocity and recalculates the visible window.', 7, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f1f2c432-68de-4237-99a7-78ef28c9a736', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', 'd3574da4-bed0-441c-8a54-c3b92c925122', 'handleItemResize', '(index: number, height: number) => void', '', 'Call when a rendered item changes its measured height. Updates the size cache and triggers an offset recalculation. Wire via a ResizeObserver on each rendered row.', 8, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('685cb3ce-4de3-421e-b4fe-143db07506ee', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '518a2716-9fca-4061-a4cf-2bb7fb16d2db', '(model)', 'Ref<TInnerVal<Inner>> & { readonly externalValue: Props[Prop] }', '', 'A writable computed ref. Reading it returns the current value (controlled or internal). Writing it updates the internal ref and emits `update:prop`. The `externalValue` accessor returns the raw prop value without transformIn applied.', 0, false, NULL, NULL);
