INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('87e85e3d-f09c-466d-817c-72b387dd3fef', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '93862ef5-fe21-44e5-8e24-5f8a25583944', 'list', 'types.detail.file_field_display.list', 'Default. Renders each selected file as a card in a vertical stack below the field. Suitable when filenames and per-file actions (remove, download, progress) need to be visible.', 0, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1931e046-9a17-41e4-adea-fbe3895251f2', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '93862ef5-fe21-44e5-8e24-5f8a25583944', 'chips', 'types.detail.file_field_display.chips', 'Renders each selected file as a closable <OrigamChip> inline inside the field. Compact mode — best for forms where many files can be selected but vertical space is limited.', 1, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2cacf8c4-e21e-4ccb-924e-570da6e709d1', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '93862ef5-fe21-44e5-8e24-5f8a25583944', 'counter', 'types.detail.file_field_display.counter', 'Shows a single "N files selected" line with an <OrigamCounter>. Most compact mode — use when the file names are irrelevant to the user after selection.', 2, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5a45363c-a3f6-4301-b95c-430b673a6fed', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '24de4b0b-c8a3-4455-809e-f3edf20b5a7a', 'false', 'types.detail.file_size.false', 'File sizes are not displayed. This is the default behaviour when the showSize prop is omitted.', 0, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('bf98314d-0d9f-4c58-81e6-46a5acbc166a', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '24de4b0b-c8a3-4455-809e-f3edf20b5a7a', 'true', 'types.detail.file_size.true', 'File sizes are displayed using the SI divisor (1 000) — KB, MB, GB.', 1, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8bbf7b1b-078e-4a4e-b6b7-3ee3c3c62665', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '24de4b0b-c8a3-4455-809e-f3edf20b5a7a', '1000', 'types.detail.file_size.1000', 'Explicit SI (decimal) units: 1 KB = 1 000 bytes, 1 MB = 1 000 000 bytes. Matches the marketing convention used by most storage providers.', 2, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('aa22b21a-34bd-4dca-b75b-0c3757348420', '2026-11-05 18:21:26.770015+00', '2026-11-05 18:21:26.770015+00', '24de4b0b-c8a3-4455-809e-f3edf20b5a7a', '1024', 'types.detail.file_size.1024', 'Binary / IEC units: 1 KiB = 1 024 bytes, 1 MiB = 1 048 576 bytes. Traditional computing convention; more accurate for OS-reported file sizes.', 3, false, NULL, NULL);
